/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} l1
 * @param {ListNode} l2
 * @return {ListNode}
 */
var addTwoNumbers = function(l1, l2) {


    const recCalculator=(n1,n2,carry)=>{
        if(!n1 && !n2 && !carry) return null
        const sum=(n1?.val||0)+(n2?.val||0)+carry
        const nextNode= recCalculator(n1?.next, n2?.next,Math.floor(sum/10))
        return  new ListNode(sum%10,nextNode)
    }


    return recCalculator(l1,l2,0)

};

public class Solution {
    public string LongestPalindrome(string s) {
        int start = 0; // Initialize the start index of the longest palindromic substring.
        int end = 0;   // Initialize the end index of the longest palindromic substring.

        for (int i = 0; i < s.Length; i++) {
            // Check for odd length palindromes centered at s[i].
            int len1 = ExpandAroundCenter(s, i, i);

            // Check for even length palindromes centered at s[i] and s[i+1].
            int len2 = ExpandAroundCenter(s, i, i + 1);

            // Get the maximum length among these two cases.
            int len = Math.Max(len1, len2);

            if (len > end - start) {
                // If the current palindrome is longer than the previous longest one,
                // update the start and end indices accordingly.
                start = i - (len - 1) / 2;
                end = i + len / 2;
            }
        }

        // Extract and return the longest palindromic substring.
        return s.Substring(start, end - start + 1);
    }

    private int ExpandAroundCenter(string s, int left, int right) {
        while (left >= 0 && right < s.Length && s[left] == s[right]) {
            left--;
            right++;
        }
        return right - left - 1;
    }
}

class Solution {
    public int maxArea(int[] height) {
        int left = 0;                  
        int right = height.length - 1;  
        int maxWater = 0;               
        while (left < right) {
            int width = right - left;
            int h = Math.min(height[left], height[right]);
            int water = width * h;
            maxWater = Math.max(maxWater, water);
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }

        return maxWater; 
    }
}

class Solution {
public:
    string intToRoman(int num) {
        vector <string> ones = {"", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"};
        vector <string> tens = {"", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"};
        vector <string> hrns = {"", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"};
        vector <string> ths = {"", "M", "MM", "MMM"};

        return ths[num/1000] + hrns[(num%1000)/100] + tens[(num%100)/10] + ones[num%10];
    }
};

class Trie{
private:
    struct Node{
        Node* links[26];
        bool flag;
        int cp = 0;

        bool contains(char e){
            return links[e-'a'] != NULL;
        }

        void add(char e,Node* node){
            links[e-'a'] = node;
        }

        Node* next(char e){
            return links[e-'a'];
        }

        void setend(){
            this->flag = true;
        }
        void incresePrefix(){
            this->cp++;
        }
    };
private:
    Node* root;
public:
    Trie(){
        root = new Node();
    }
    void insert(string&s){
        Node* node = root;
        for(char&e: s){
            if(!node->contains(e))
                node->add(e,new Node());
            node = node->next(e);
            node->incresePrefix();
        }
        node->setend();
    }
    int num_of_prefix(string&s){
        Node* node = root;
        for(char&e: s){
            if(!node->contains(e)) return 0;
            node = node->next(e);
        }
        return node->cp;
    }
};

class Solution {
public:
    string longestCommonPrefix(vector<string>& strs) {
        int n = size(strs), mn = 1e9;
        Trie *trie = new Trie();
        string s,t;
        for(auto&e: strs){
            if(size(e) < mn){
                mn = size(e);
                s = e;
            }
            trie->insert(e);
        }
        for(char&e: s){
            t += e;
            if(trie->num_of_prefix(t) != n){
                t.pop_back();
                return t;
            }
        }
        return t;
    }
};

public class Solution {
    public IList<string> LetterCombinations(string digits) {
        int levels=digits.Length;
        // make array containing string of letters for each index as number
        string[] arr = new string[10];
        arr[2]="abc";
        arr[3]="def";
        arr[4]="ghi";
        arr[5]="jkl";
        arr[6]="mno";
        arr[7]="pqrs";
        arr[8]="tuv";
        arr[9]="wxyz";
        List<string> ans=new();
        if(levels==0)
            return ans;
        // we read input ltr for each char we make a loop 
        int l1=digits[0]-'0';
        foreach(var c1 in arr[l1]){
            if(levels>1){
                int l2=digits[1]-'0';
                foreach(var c2 in arr[l2]){
                    if(levels>2){
                        int l3=digits[2]-'0';
                        foreach(var c3 in arr[l3]){
                            if(levels>3){
                                int l4=digits[3]-'0';
                                foreach(var c4 in arr[l4]){
                                    ans.Add(c1.ToString()+c2.ToString()+c3.ToString()+c4.ToString());
                                }
                            }
                            else{
                                ans.Add(c1.ToString()+c2.ToString()+c3.ToString());
                            }
                        }
                    }
                    else{
                        ans.Add(c1.ToString()+c2.ToString());
                    }
                }
            }
            else{
                ans.Add(c1.ToString());
            }
        }
        return ans;
    }
}

class Solution {
public:
    unordered_map <int,string> mp;
    string ans = ""; 
    void solve(int idx,string &digits,vector<string> &v){
        if(idx >= digits.size()){ // Base Case when idx is greater or equal to digits length
            v.push_back(ans); // Save the answer
            return;
        }    
        int num = digits[idx]-'0'; // Stored is ASCII, therefore substract it with '0' 
        string s = mp[num]; // Store the mapped value to the string s
        for(int i=0;i<s.size();i++){
            ans += s[i]; // Add
            solve(idx+1,digits,v); // Move forward
            ans.pop_back(); // BackTrack 
        }
    }
    vector<string> letterCombinations(string digits) {
        mp[2] = {"abc"}; // Making int -> string Map given accordingly
        mp[3] = {"def"};
        mp[4] = {"ghi"};
        mp[5] = {"jkl"};
        mp[6] = {"mno"};
        mp[7] = {"pqrs"};
        mp[8] = {"tuv"};
        mp[9] = {"wxyz"};
        vector<string> v;
        if(digits.size() == 0)
            return v;
        solve(0,digits,v);
        return v;
    }
};

class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        vector<vector<int>>v;
        sort(nums.begin(),nums.end());
        int n=nums.size();
        for(int i=0;i<n;i++)
        {
            if(i>0&& nums[i]==nums[i-1])continue;
            for(int j=i+1;j<n;j++)
            {
                if(j!=(i+1) && nums[j]==nums[j-1])continue;
                int k=j+1;
                int l=n-1;
                while(k<l)
                {
                    long long  sum=nums[i];
                    sum+=nums[j];
                    sum+=nums[k];
                    sum+=nums[l];
                    if(sum==target)
                    {
                    vector<int> temp={nums[i],nums[j],nums[k],nums[l]};
                    v.push_back(temp);
                    k=k+1;
                    l=l-1;
                    while(k<l && nums[k]==nums[k-1])k=k+1;
                    while(k<l && nums[l]==nums[l+1])l=l-1;
                    }
                    else if(sum<target)
                    {
                        k++;
                    }
                    else{l--;}
                }
            }
        } 
        return v;
    }
};

public class Solution {
    public int Search(int[] nums, int target) {
        int left = 0;
        int right = nums.Length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                return mid;
            }

            if (nums[left] <= nums[mid]) { // Left half is sorted
                if (nums[left] <= target && target < nums[mid]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            } else { // Right half is sorted
                if (nums[mid] < target && target <= nums[right]) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }

        return -1; // Target not found
    }
}

class Solution(object):
    def searchInsert(self, nums, target):
        l = 0
        r = len(nums) - 1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] < target:
                l = mid + 1
            elif nums[mid] > target:
                r = mid - 1
            else:
                return mid
        return l

class Solution {
    public void solveSudoku(char[][] board) {
        // Start solving sudoku from the first cell
        solve(board, 0, 0);
    }

    private boolean solve(char[][] board, int row, int col) {
        // Base case: If row is equal to board length, entire board has been filled
        if (row == board.length) {
            return true;
        }

        // Move to next row when current row is fully filled
        if (col == board[0].length) {
            return solve(board, row + 1, 0);
        }

        // Skip cells that are already filled
        if (board[row][col] != '.') {
            return solve(board, row, col + 1);
        }

        // Try different numbers in current cell
        for (char num = '1'; num <= '9'; num++) {
            if (isValidPlacement(board, row, col, num)) {
                board[row][col] = num; // Fill current cell with valid number

                // Move to next cell
                if (solve(board, row, col + 1)) {
                    return true;
                }

                // Backtrack to previous state if solution not found
                board[row][col] = '.';
            }
        }

        // No valid solution found
        return false;
    }

    private boolean isValidPlacement(char[][] board, int row, int col, char num) {
        // Check if num is already in the same row, column or 3x3 subgrid
        for (int i = 0; i < board.length; i++) {
            // Check row
            if (board[i][col] == num) {
                return false;
            }

            // Check column
            if (board[row][i] == num) {
                return false;
            }

            // Check 3x3 subgrid
            int subgridRow = 3 * (row / 3) + i / 3; // Calculate row index of subgrid
            int subgridCol = 3 * (col / 3) + i % 3; // Calculate column index of subgrid

            if (board[subgridRow][subgridCol] == num) {
                return false;
            }
        }

        // Placement is valid
        return true;
    }
}

class Solution {
private:
    bool isSafe(int row, int col, vector<vector<char>>& board, int val)
    {
        for(int i=0 ; i<9 ; i++)
        {
            if(board[row][i]==val+48)
                return false;
            if(board[i][col]==val+48)
                return false;
            if(board[3*(row/3)+i/3][3*(col/3)+i%3]==val+48)
                return false;
        }
        return true;
    }

    bool solve(vector<vector<char>>& board)
    {
        for(int row=0; row<board.size() ; row++)
        {
            for(int col=0; col<board[0].size() ; col++)
            {
                if(board[row][col]=='.')
                {
                    for(int val=1 ; val<=9 ; val++)
                    {
                        if(isSafe(row, col, board, val))
                        {
                            board[row][col] = val+48;

                            // Recursion
                            if(solve(board))
                                return true;

                            // BackTracking
                            else
                            {
                                board[row][col] = '.';
                            }
                        }
                    }
                    return false;
                }
            }

        }
        return true;
    }
public:
    void solveSudoku(vector<vector<char>>& board) {
        solve(board);
    }
};

class Solution {
public:
    void solve(vector<int> c, int t,vector<vector<int>>& ans,vector<int> output,int index){
        if(t <= 0){
            if(t == 0){
                ans.push_back(output);
            }
            return;
        }

        for(int i = index; i < c.size(); i++){
            if(c[i] > t) break;
            output.push_back(c[i]);
            solve(c,t-c[i],ans,output,i);
            output.pop_back();
        }
    }

    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        vector<vector<int>> ans;
        sort(candidates.begin(),candidates.end());
        candidates.erase(unique(candidates.begin(),candidates.end()),candidates.end());
        vector<int> output;
        solve(candidates,target,ans,output,0);
        return ans;
    }
};

class Solution {
private:
void solve(int index,int target,vector<int> &arr,vector<vector<int>> &ans,vector<int> &ds)
{
    if(target == 0)
    {
        ans.push_back(ds);
        return;
    }

    for(int i = index; i< arr.size();i++)
    {
       if(i > index && arr[i] == arr[i-1])
       continue;

       if(arr[i] > target)
       break;

       ds.push_back(arr[i]);
       solve(i+1,target-arr[i],arr,ans,ds);
       ds.pop_back();
    }

    return;
}
public:
    vector<vector<int>> combinationSum2(vector<int>& candidates, int target) {
        sort(candidates.begin(),candidates.end());
        vector<vector<int>> ans;
        vector<int> ds;
        solve(0,target,candidates,ans,ds);
        return ans;
    }
};

class Solution {
public:
    string multiply(string s1, string s2) {
        if (s1 == "0" || s2 == "0") return "0";
        string s1n ="";
        string s2n ="";

        if(s1[0] == '-'){
            s1n ="-"; s1 = s1.substr(1);
        }
        if(s2[0] == '-'){
            s2n = "-"; s2 = s2.substr(1);
        }

        // if both negative just empty the string
        if(s2n == "-" && s1n == "-") s1n=s2n="";

        int n = s1.size();
        int m = s2.size();
        string res(n+m,'0');

        for(int i=n-1; i>=0; i--){
            for(int j=m-1; j>=0; j--){                
                int num = (s1[i]-'0') * (s2[j]-'0') + (res[i+j+1]-'0'); // res will store carry
                res[i+j+1] = num % 10 + '0';
                res[i+j] += num / 10; // carry

            }
        }

        int i=0;
        while(i < res.size() && res[i] == '0') i++;
        return s1n + s2n + res.substr(i);
    }
};

class Solution {
public:
    int solve(int i ,int j ,string &s1, string &s2, vector<vector<int>> &dp)
    {

        if(i < 0 || j < 0)
        {
            while(j >= 0 && s2[j] == '*')
                j-- ;
            if(i < 0 && j < 0)
               return true  ;
            else
              return false ;
        }

        if(dp[i][j] != -1)
           return dp[i][j] ;

        if(s1[i] == s2[j] || s2[j] == '?')
           return dp[i][j] = solve(i-1,j-1,s1,s2,dp)  ;

        else if(s2[j] == '*')
        {
            for(int k = 0 ; k <= i + 1  ;k++)
               if(solve(i-k,j-1,s1,s2,dp))
                   return dp[i][j] = true ;
        }
        return dp[i][j] = false ;

    }
    bool isMatch(string s, string p) 
    {
        int n = s.size() ;
        int m = p.size() ;
        vector<vector<int>> dp(n+1,vector<int> (m+1,-1)) ;

        return solve(n-1,m-1,s,p,dp) ;
    }
};

public class Solution {
    public IList<IList<int>> Permute(int[] nums) {
        IList<IList<int>> result = new List<IList<int>>();
        List<int> currentPermutation = new List<int>();
        HashSet<int> usedIndices = new HashSet<int>();
        Backtrack(nums, currentPermutation, usedIndices, result);
        return result;
    }

    private void Backtrack(int[] nums, List<int> currentPermutation, HashSet<int> usedIndices, IList<IList<int>> result) {
        if (currentPermutation.Count == nums.Length) {
            result.Add(new List<int>(currentPermutation));
            return;
        }

        for (int i = 0; i < nums.Length; i++) {
            if (!usedIndices.Contains(i)) {
                currentPermutation.Add(nums[i]);
                usedIndices.Add(i);
                Backtrack(nums, currentPermutation, usedIndices, result);
                currentPermutation.RemoveAt(currentPermutation.Count - 1);
                usedIndices.Remove(i);
            }
        }
    }
}

