class Solution {
public:
    int uniquePaths(int m, int n) {
        vector<vector<int>> dp(2, vector<int>(n,1));
        for(int i = 1; i < m; i++)
            for(int j = 1; j < n; j++)
                dp[i & 1][j] = dp[(i-1) & 1][j] + dp[i & 1][j-1];   // <- &  used to alternate between rows
        return dp[(m-1) & 1][n-1];
    }
};

class Solution {

    static int helper2(int arr[][]){
        int m = arr.length;
        int n = arr[0].length;

        int dp[][] = new int[m+1][n+1];
        for(var a : dp) Arrays.fill(a,0);
        dp[m-1][n-1] = 1;

        for(int i=m-1; i>=0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (i == m - 1 && j == n - 1) continue;
                if (arr[i][j] == 1) dp[i][j] = 0;
                else dp[i][j] = dp[i + 1][j] + dp[i][j + 1];
            }
        }
        return dp[0][0];
    }
    public int uniquePathsWithObstacles(int[][] arr) {

       if(arr[arr.length-1][arr[0].length-1]==1) return 0;
       return helper2(arr);
    }
}

class Solution {
public:
    int minPathSum(vector<vector<int>>& grid) {
        int n=grid.size(),m=grid[0].size();
        vector<vector<int>> test(n,vector<int>(m,0));
        test[0][0]=grid[0][0];
        for(int i=1;i<m;i++){       //1st row
            test[0][i]=test[0][i-1]+grid[0][i];
        }
        for(int i=1;i<n;i++){       //1st col
            test[i][0]=test[i-1][0]+grid[i][0];
        }

        for(int i=1;i<n;i++){
            for(int j=1;j<m;j++){
                int up=test[i-1][j];
                int left=test[i][j-1];
                test[i][j]=min(up+grid[i][j],left+grid[i][j]);
            }
        }
        return test[n-1][m-1];
    }
};

class Solution {
public:

    int helper(vector<vector<int>>& arr){
        int n = arr.size();
        int m = arr[0].size();
        vector<vector<int>> dp(n+1,vector<int>(m+1,INT_MAX));
        dp[n-1][m-1] = arr[n-1][m-1];

        for(int i=n-1; i>=0; i--){
            for(int j=m-1; j>=0; j--){
                if(i==n-1 && j==m-1) continue;

                dp[i][j] = arr[i][j] + min(dp[i+1][j],dp[i][j+1]);
            }
        }
        return dp[0][0];
    }
    int minPathSum(vector<vector<int>>& grid) {
        return helper(grid);
    }
};

class Solution {
public:
    vector<string> fullJustify(vector<string>& words, int maxWidth) {
        vector<string> result;
        for(int i = 0, j; i < words.size(); i = j) {
            int width = 0;
            for(j = i; j < words.size() && width + words[j].size() + j - i <= maxWidth; j++) {
                width += words[j].size();
            }
            int space = 1, extra = 0;
            if(j - i != 1 && j != words.size()) {
                space = (maxWidth - width) / (j - i - 1);
                extra = (maxWidth - width) % (j - i - 1);
            }
            string line = words[i];
            for(int k = i + 1; k < j; k++) {
                line += string(space, ' ');
                if(extra > 0) {
                    extra--;
                    line += " ";
                }
                line += words[k];
            }

            line += string(maxWidth - line.size(), ' ');
            result.push_back(line);
        }
        return result;
    }
};

class Solution {
public:
    int mySqrt(int x) {
        if (x == 0)
            return x;
        int first = 1, last = x;
        while (first <= last) {
            int mid = first + (last - first) / 2;
            // mid * mid == x gives runtime error
            if (mid  == x / mid)
                return mid;
            else if (mid > x / mid) {
                last = mid - 1;
            }
            else {
                first = mid + 1;
            }
        }
        return last;
    }
};

class Solution {
public:
    int climbStairs(int n) {
        if (n == 0 || n == 1) {
            return 1;
        }

        vector<int> dp(n+1);
        dp[0] = dp[1] = 1;

        for (int i = 2; i <= n; i++) {
            dp[i] = dp[i-1] + dp[i-2];
        }
        return dp[n];
    }
};

class Solution {
    public String simplifyPath(String path) {
        Stack<String> s = new Stack<>();
        StringBuilder res = new StringBuilder();
        String[] p =path.split("/");

        for(int i=0;i<p.length;i++){
            if(!s.isEmpty()  && p[i].equals("..")) s.pop();
            else if(!p[i].equals("") && !p[i].equals(".") && !p[i].equals(".."))
                s.push(p[i]);
        }


        if(s.isEmpty()) return "/";
        while(!s.isEmpty()){
            res.insert(0,s.pop()).insert(0,"/");
        }

        return res.toString();
    }
}

