class Solution {
public:
    bool search(vector<int>& nums, int target) {
        int l = 0;
        int r = nums.size() - 1;

        while(l <= r)
        {
            int mid = l + (r-l) / 2;
            if (nums[mid] == target)
                return true;
			// with duplicates we can have this contdition, just update left & right
            if((nums[l] == nums[mid]) && (nums[r] == nums[mid]))
            {
                l++;
                r--;
            }
			// first half
			// first half is in order
            else if(nums[l] <= nums[mid])
            {
				// target is in first  half
                if((nums[l] <= target) && (nums[mid] > target))
                    r = mid - 1;
                else
                    l = mid + 1;
            }
			// second half
			// second half is order
			// target is in second half
            else
            {
                if((nums[mid] < target) && (nums[r]>= target))
                    l = mid + 1;
                else
                    r = mid - 1;
            }
        }
        return false;
    }
	// for github repository link go to my profile.
};

class Solution {

    /*
        Time Complexity : O(N)
        Space Complexity : O(N)
    */

public:
    int largestRectangleArea(vector<int>& heights) {
        stack<int> s1;
        int res = 0, n = heights.size();

        for(int i=0; i<=n; i++){
            while(!s1.empty() and (i==n || heights[s1.top()] >= heights[i])){
                int len = heights[s1.top()];
                s1.pop();

                int bre;
                if(s1.empty()) bre = i;
                else bre = i - s1.top() - 1;
                res = max(res, len*bre);
            }

            s1.push(i);
        }

        return res;
    }
};

class Solution {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        if(n == 0) return 0; // Base Condition
        int maxArea = 0;
        int left[] = new int[n]; //fill left boundary
        int right[] = new int[n]; // fill right boundary

        left[0] = -1;
        right[n - 1] = n;

        for(int i = 1; i < n; i++){
            int prev = i - 1; // previous for comparing the heights
            while(prev >= 0 && heights[prev] >= heights[i]){
                prev = left[prev]; // we have done this to minimise the jumps we make to the left
            }
            left[i] = prev;
        }
        // Similarly we do for right
        for(int i = n - 2; i >= 0; i--){
            int prev = i + 1; 
            while(prev < n && heights[prev] >= heights[i]){
                prev = right[prev]; 
            }
            right[i] = prev;
        }
        // once we have these two arrays fill we need width & area
        for(int i = 0; i < n; i++){
            int width = right[i] - left[i] - 1;
            maxArea = Math.max(maxArea, heights[i] * width);
        }
        return maxArea;

    }
}

var maximalRectangle = function (aa) {
    let m = aa.length,
        n = aa[0].length;

    let widthOnLeftTillHere = Array.from({ length: m }, () =>
        new Array(n).fill(0)
    );
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++)
            if (aa[r][c] === "1") {
                widthOnLeftTillHere[r][c] =
                    (widthOnLeftTillHere[r][c - 1] || 0) + 1;
            }

    let maxArea = 0;
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++)
            if (aa[r][c] === "1") {
                let minWidthGoingUp = Infinity;
                let increasingHeight = 1;
                for (let r2 = r; r2 >= 0; r2--, increasingHeight++) {
                    minWidthGoingUp = Math.min(
                        minWidthGoingUp,
                        widthOnLeftTillHere[r2][c]
                    );
                    maxArea = Math.max(
                        maxArea,
                        minWidthGoingUp * increasingHeight
                    );
                }
            }
    return maxArea;
};

import java.util.Stack;

public class Solution {

    public int largestRectangleArea(int[] heights) {
        Stack<Integer> stack = new Stack<>();
        int maxArea = 0;
        int n = heights.length;
        for (int i = 0; i <= n; i++) {
            while (!stack.isEmpty() && (i == n || heights[stack.peek()] >= heights[i])) {
                int height = heights[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, width * height);
            }
            stack.push(i);
        }
        return maxArea;
    }

    public int maximalAreaOfSubMatrixOfAll1(char[][] matrix, int n, int m) {
        int maxArea = 0;
        int[] height = new int[m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (matrix[i][j] == '1') {
                    height[j]++;
                } else {
                    height[j] = 0;
                }
            }
            int area = largestRectangleArea(height);
            maxArea = Math.max(maxArea, area);
        }
        return maxArea;
    }

    public int maximalRectangle(char[][] matrix) {
        return maximalAreaOfSubMatrixOfAll1(matrix, matrix.length, matrix[0].length);
    }
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* partition(ListNode* head, int x) {
        ListNode *lesser = NULL;
        ListNode *greater = NULL;
        ListNode *startLesser = NULL;
        ListNode *startGreater = NULL;

        ListNode *prev;

        while(head != NULL){
            prev = head;
            head = head->next;
            prev->next = NULL;

            if(prev->val < x){
                if(lesser == NULL){
                    lesser = prev;
                    startLesser = lesser;
                }
                else{
                    lesser->next = prev;
                    lesser = lesser->next;
                }
            }

            else{
                if(greater == NULL){
                    greater = prev;
                    startGreater = greater;
                }
                else{
                    greater->next = prev;
                    greater = greater->next;
                }
            }

        }

        if(!startLesser) return startGreater;
        if(!startGreater) return startLesser;
        lesser->next = startGreater;

        return startLesser;

    }
};

class Solution {
    public List<Integer> grayCode(int n) {
       List< String> greystr=solve(n);
        List<Integer> ans=new ArrayList();
        for(String s:greystr)
        {
            ans.add(Integer.parseInt(s,2));
        }
        return ans;
    }
    public List<String> solve (int n)
    {
        if(n==1)
        {
            List<String> base=new ArrayList();
            base.add("0");
            base.add("1");
            return base;
        }   
        List<String> ans=new ArrayList();
        List<String> temp=solve(n-1);
        for(int i=0;i<temp.size();i++)
            ans.add("0"+temp.get(i));
        for(int i=temp.size()-1;i>=0;i--)
            ans.add("1"+temp.get(i));
        return ans;
    }
}

class Solution {
public:
    bool isValidNumber(string s){
        return stoi(s)>=0 and stoi(s)<=255 and to_string(stoi(s))==s;
    }
    bool isValidIPAddress(string s){
        int n=s.size();
        s.push_back('.');
        int i=0;
        while(i<=n){
            string temp;
            while(s[i]!='.'){
                temp.push_back(s[i++]);
            }
            i++;
            if(temp.size()>3 or !isValidNumber(temp)){
                return false;
            }
        }
        s.pop_back();
        return true;
    }
    vector<string> ans;
    void solve(int idx,int dot,string& ds,string& s){
        int n=s.size();
        if(idx==n){
            if(isValidIPAddress(ds) and dot==0){
                ans.push_back(ds);
            }
            return ;
        }
        ds.push_back(s[idx]);
        if(dot>=1 and ds.back()!='.' and idx!=n-1){
            ds.push_back('.');
            solve(idx+1,dot-1,ds,s);
            ds.pop_back();
        }
        solve(idx+1,dot,ds,s);
        ds.pop_back();
    }
    vector<string> restoreIpAddresses(string s) {
        string ds="";
        solve(0,3,ds,s);
        return ans;
    }
};

class Solution {
public:
    int numTrees(int n) {
        vector<int> dp(n+1);
        dp[0] = dp[1] = 1;
        for(int i = 2; i <= n; i++) 
            for(int j = 1; j <= i; j++)
                dp[i] += dp[j-1] * dp[i-j];
        return dp[n];
    }
};

class Solution {
public:
    int dp[101][101][201];
    int n , m, N;

    bool solve(int i, int j, int k, string &s1, string &s2, string &s3 )
    {
        if(i==n && j==m && k==N)
            return true;

        if(k>=N)
            return false;

        if(dp[i][j][k] !=-1)
        {
            return dp[i][j][k];
        }
        bool res = false;
        if(s1[i] == s3[k])
        {
            res = solve(i+1,j,k+1,s1,s2,s3);
        }

        if(res)
            return res;

        if(s2[j] == s3[k])
        {
            res = solve(i,j+1,k+1,s1,s2,s3);
        }

        return dp[i][j][k] = res;



    }

    bool isInterleave(string s1, string s2, string s3) {
        n = s1.length();
        m = s2.length();
        N = s3.length();

        memset(dp,-1,sizeof(dp));

        return solve(0,0,0,s1,s2,s3);
    }
};

class Solution {
