class Solution {
public:
    int minimumTotal(vector<vector<int>>& triangle) {
        int n = triangle.size();
        vector<int> curr(n + 1, 0), next(n + 1, 0);

        for (int row = n-1; row >= 0; row--) {
            for (int idx = row; idx >= 0; idx--) {
                int down = next[idx];
                int downRight = next[idx + 1];
                curr[idx] = triangle[row][idx] + min(down, downRight);
            }
            next = curr;
        }

        return next[0];
    }
};

class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int lsf = INT_MAX;
        int op = 0;
        int pist = 0;

        for(int i = 0; i < prices.size(); i++){
            if(prices[i] < lsf){
                lsf = prices[i];
            }
            pist = prices[i] - lsf;
            if(op < pist){
                op = pist;
            }
        }
        return op;
    }
};

class Solution {
public:

    int maxProfit(vector<int>& prices) 
    {
         int ans = 0;
        int minValue = prices[0];
        for(int i=1; i<prices.size();i++){
            int tmpSum = prices[i] - minValue;
