class Solution {
public:
    int dfs(int i,int j,int k,vector<int>& prices,vector<vector<vector<int>>> &dp){
        int n = prices.size();
        if(i == n) return 0;
        int ans = 0;
        if(k == 2) return 0;
        if(dp[i][j][k] != -1) return dp[i][j][k];
        if(j == 0){
            ans = max(dfs(i+1,1,k,prices,dp)-prices[i],dfs(i+1,0,k,prices,dp));
        }
        else{
            ans = max(dfs(i+1,0,k+1,prices,dp)+prices[i],dfs(i+1,1,k,prices,dp));
        }
        return dp[i][j][k] = ans;
    }
    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        vector<vector<vector<int>>> dp(n,vector<vector<int>>(2,vector<int>(3,-1)));
        return dfs(0,0,0,prices,dp);
    }
};

class Solution {

    class QueueElement {
        String word;
        int level;
        QueueElement(String word, QueueElement prev) {
            this.word = word;
            this.level = prev.level+1;
        }
        QueueElement(String word, int level) {
            this.word = word;
            this.level = level;
        }
    }

    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        if(beginWord.equals(endWord)) {
            return 1;
        }
        Set<String> dict = new HashSet<>(wordList);
        if(!dict.contains(endWord))
            return 0;
        Queue<QueueElement> q = new LinkedList<>();
        q.add(new QueueElement(beginWord, 1));
        Set<String> visited = new HashSet<>();
        visited.add(beginWord);

        while(!q.isEmpty()) {
            QueueElement polled = q.poll();
            if(polled.word.equals(endWord)) {
                return polled.level;
            }
            int L = polled.word.length();
            char[] polledChars = polled.word.toCharArray();
            for(int i = 0; i < L; i++) {
                char temp = polledChars[i];
                for(char c = 'a'; c <= 'z'; c++) {
                    if(c == temp)
                        continue;
                    polledChars[i] = c;
                    String potentialNextWord = new String(polledChars);
                    if(!visited.contains(potentialNextWord) && dict.contains(potentialNextWord)) {
                        visited.add(potentialNextWord);
                        q.add(new QueueElement(potentialNextWord, polled));
                    }
                }
                polledChars[i] = temp;
            }
        }
        return 0;
    }
}

class Solution {
public:
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> dict(wordList.begin(), wordList.end());
        queue<string> todo;
        todo.push(beginWord);
        int ladder = 1;
        while (!todo.empty()) {
            int n = todo.size();
            for (int i = 0; i < n; i++) {
                string word = todo.front();
                todo.pop();
                if (word == endWord) {
                    return ladder;
                }
                dict.erase(word);
                for (int j = 0; j < word.size(); j++) {
                    char c = word[j];
                    for (int k = 0; k < 26; k++) {
                        word[j] = 'a' + k;
                        if (dict.find(word) != dict.end()) {
                            todo.push(word);
                        }
                     }
                    word[j] = c;
                }
            }
            ladder++;
        }
        return 0;
    }
};

class Solution {
public:
    vector<vector<string>> res;
    bool pal(int i,int j,string &s)
    {
        while(i<j)
        {
            if(s[i]!=s[j])
                return false;
            i++;j--;
        }
        return true;
    }
    void f(int i,string &s,vector<string> ans)
    {
        if(i>=s.size())
        {
            if(ans.size()>0)
               res.push_back(ans);
            return;
        }
        for(int k=i;k<s.size();k++)
        {
            if(pal(i,k,s))
            {
                ans.push_back(s.substr(i,k-i+1));
                f(k+1,s,ans);
                ans.pop_back();
            }
        }
    }
    vector<vector<string>> partition(string s) {
        vector<string> ans;
        f(0,s,ans);
        return res;
    }
};

class Solution {
public:
    bool isPalindrome(string &s,int i,int j){
        while(i < j){
            if(s[i] != s[j]){
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
    int dfs(int i,int j,string s,vector<int> &dp){
        if(i >= j or isPalindrome(s,i,j)) return 0;
        if(dp[i] != -1) return dp[i];
        int ans = INT_MAX;
        for(int k=i;k<j;k++){
            if(isPalindrome(s,i,k)){
                int count = 1+dfs(k+1,j,s,dp);
                ans = min(ans,count);
            }

        }
        return dp[i] = ans;
    }
    int minCut(string s) {
        int n = s.size();
        vector<int> dp(n+1,-1);
        return dfs(0,n-1,s,dp);
    }
};

class Solution {
public:
    unordered_map<Node* , Node*> mp; // declaring map, to check whwther we have a copy of node or not and also to store copy

    Node* cloneGraph(Node* node) {
        if(node == NULL) // if node is null, then simply return null
        {
            return NULL;
        }

        Node* first = new Node(node -> val, {}); // make a copy of first node
        mp[node] = first;

        queue<Node*> q; //For bfs, we create queue
        q.push(node); // push into queue

        while(q.empty() == false) // until q. empty == false
        {
            Node* curr = q.front(); // extract front node
            q.pop(); // pop that from queue

            for(auto adj: curr -> neighbors) // now travel in adjcant
            {
                if(mp.find(adj) == mp.end()) // if not present in map
                {
                    mp[adj] = new Node(adj -> val, {}); // then create copy
                    q.push(adj); // push nto the queue

                }

                mp[curr] -> neighbors.push_back(mp[adj]); // in current node push adjcant node
            }
        }

        return mp[node];
    }
};

class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int n = gas.length;
        int total_surplus = 0;
        int surplus = 0;
        int start = 0;

        for(int i = 0; i < n; i++){
            total_surplus += gas[i] - cost[i];
            surplus += gas[i] - cost[i];
            if(surplus < 0){
                surplus = 0;
                start = i + 1;
            }
        }
        return (total_surplus < 0) ? -1 : start;
    }
}

