class Solution {
public:
    Node* copyRandomList(Node* head) {
        if(head == NULL)return NULL;
        for(Node *curr = head; curr != NULL; curr = curr->next){
            Node *newNode = new Node(curr->val);
            Node *next = curr->next;
            curr->next = newNode;
            curr = newNode;
            newNode->next = next;
        }
        for(Node *curr = head; curr != NULL; curr = curr->next->next){
            Node *copy = curr->next;
            copy->random = (curr->random == NULL) ?  NULL : curr->random->next;
        }
        Node *dummyHead = new Node(0), *currCopyPtr = dummyHead;
        for(Node *curr = head; curr != NULL; curr = curr->next){
              currCopyPtr->next = curr->next;
              currCopyPtr = curr->next;
              curr->next = currCopyPtr->next;
        }
        return dummyHead->next;
    }
};

class Solution {
public:
    ListNode *detectCycle(ListNode *head) {
    ListNode* slow = head;
    ListNode* fast = head;

    // Find the meeting point of the slow and fast pointers
    while (slow != nullptr && fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;

        // If the slow and fast pointers meet, there is a cycle
        if (slow == fast) {
            fast = head;  // Move the fast pointer back to the head

            // Move the slow and fast pointers at the same pace until they meet again
            while (fast != slow) {
                fast = fast->next;
                slow = slow->next;
            }

            return fast;  // Return the node where the cycle begins
        }
    }

    return nullptr;  // Return null if there is no cycle
    }
};

class Solution:
    def reorderList(self, head):
        def middleNode(head):
            slow, fast = head, head
            while fast and fast.next:
                slow = slow.next
                fast = fast.next.next
            return slow

        def reverseList(head):
            prev = None
            while head:
                nextNode = head.next
                head.next = prev
                prev, head = head, nextNode
            return prev

        if not head or not head.next: return
        R, L, i = reverseList(middleNode(head)), head.next, 0
        while L != R:
            if i & 1:
                head.next, L = L, L.next
            else:
                head.next, R = R, R.next
            head, i = head.next, i + 1

class Solution:
    def insertionSortList(self, head):
        cur = head
        while cur:
            j = head
            while j != cur:
                if j.val > cur.val: 
                    j.val, cur.val = cur.val, j.val
                j = j.next
            cur = cur.next
