class Solution:
    def insertionSortList(self, head):
        dummy, cur_prev, cur = ListNode(-1, head), head, head.next
        while cur:
            j_prev, j, cur_next = dummy, dummy.next, cur.next
            if cur.val > cur_prev.val:
                cur_prev = cur
            else:                
                while j.val < cur.val:
                    j_prev, j = j, j.next
                cur.next = j
                j_prev.next = cur
                cur_prev.next = cur_next
            cur = cur_next
        return dummy.next

class Solution {
public:
    int solve(vector<int>& nums, int start, int end){
        //base case
        if(start > end){
            return INT_MIN;
        }
        if(start == end){
            return nums[start];
        }

        int mid = start + (end-start)/2;
        int leftProduct = solve(nums, start, mid);
        int rightProduct = solve(nums, mid+1, end);

        int leftMin = 0, leftMax = 0, rightMin = 0, rightMax = 0;
        int product = 1;
        for(int i = mid; i >= start; i--){
            product *= nums[i];
            if(product > leftMax){
                leftMax = product;
            }
            if(product < leftMin){
                leftMin = product;
            }
        }

        product = 1;
        for(int i = mid+1; i <= end; i++){
            product *= nums[i];
            if(product > rightMax){
                rightMax = product;
            }
            if(product < rightMin){
                rightMin = product;
            }
        }
        int crossBorderProduct = max(leftMin * rightMin, leftMax * rightMax);
        return max(crossBorderProduct, max(leftProduct, rightProduct));
    }


    int maxProduct(vector<int>& nums) {
        int start = 0, end = nums.size()-1;
        return solve(nums, start, end);
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) {
        unordered_map<ListNode *,int> mp;
        ListNode *temp=headA;
        while(temp){
            mp[temp]++;
            temp=temp->next;
        }
        temp=headB;
        while(temp){
            if(mp.find(temp)!=mp.end()){
                return temp;
            }
            temp=temp->next;
        }
        return NULL;
    }
};

class Solution {
    public int compareVersion(String version1, String version2) {
        String[] a = version1.split("\\."), b = version2.split("\\.");
        boolean changed = false;
        if (a.length < b.length) {
            String[] temp = a;
            a = b;
            b = temp;
            changed = true;
        }
        for (int i = 0; i < a.length; i++) {
            String one = removeLeadingZeros(a[i]), two = i >= b.length ? "0" : removeLeadingZeros(b[i]);
            if (!one.equals(two)) {
                if (one.length() > two.length()) return changed ? -1 : 1;
                else if (one.length() < two.length()) return changed? 1 : -1;
                else {
                    for (int j = 0; j < one.length(); j++) {
                        if (one.charAt(j) > two.charAt(j)) return changed ? -1 : 1;
                        else if (one.charAt(j) < two.charAt(j)) return changed ? 1 : -1;
                    }
                }
            }
        }
        return 0;
    }

    private static String removeLeadingZeros(String s) {
        for (int i = 0; i < s.length(); i++) if (s.charAt(i) != '0') return s.substring(i);
        return "0";
    }
}

class Solution {
public:
    int compareVersion(string version1, string version2) {
        vector<int> v1, v2; string temp = ""; 
        for(int i=0; i<version1.size(); i++){
            if(version1[i] == '.'){ v1.push_back(stoi(temp)); temp = ""; }
            else temp += version1[i]; 
        }
        if(temp!= "") v1.push_back(stoi(temp)); temp = ""; 
        for(int i=0; i<version2.size(); i++){
            if(version2[i] == '.'){ v2.push_back(stoi(temp)); temp = ""; }
            else temp += version2[i]; 
        }
        if(temp!="") v2.push_back(stoi(temp)); temp = ""; 
        for(int i = v1.size()-1; i>=0; i--) {if(v1[i] == 0) v1.erase(v1.begin() + i); else break;  }
        for(int i = v2.size()-1; i>=0; i--) {if(v2[i] == 0) v2.erase(v2.begin() + i); else break;  }
        if(v1 == v2) return 0; 
        int m = v1.size(); if(m > v2.size()) m = v2.size(); 

        for(int i=0; i<m; i++) {
            if(v1[i] < v2[i]) return -1; 
            if(v1[i] > v2[i]) return 1; 
            if(v1[i] == v2[i]) continue; 
        }

        if(v1.size() > v2.size()) return 1; 
        return -1; 

    }
};

class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int [] res = {-1 , -1};

        HashSet<Integer> set = new HashSet<>();
        for (int n : numbers) {
            set.add(n);
        }

           StringBuilder str = new StringBuilder();
           int i = 1 ;
        for (int num : numbers)
        {
            if ( res[0] == -1 && set.contains(target - num))
            {
                res[0] = i;
                str.append(target - num);
            }else if (res[0] != -1 && Integer.parseInt(str.toString()) == num ){
                res[1] = i;
                return res;
            }
            i++;
        }
        return res;
    }
}

