class Solution {
    int dfs(int i, int t, int k, int n, vector<int> & p, vector<vector<int>> &dp) {
        if(i == n || t == 2 * k) return 0;
        if(dp[i][t] != -1) return dp[i][t];

        if(t % 2 == 0) {
            return dp[i][t] = max(-p[i] + dfs(i + 1, t + 1, k, n, p, dp), 0 + dfs(i + 1, t, k, n, p, dp));
        }
        return dp[i][t] = max(p[i] + dfs(i + 1, t + 1, k, n, p, dp), 0 + dfs(i + 1, t, k, n, p, dp));
    }
public:
    int maxProfit(int k, vector<int>& prices) {
        int n = prices.size();
        vector<vector<int>> dp(n, vector<int>(2 * k, -1));

        return dfs(0, 0, k, n, prices, dp);
    }
};

class Solution {
public:
    int maxProfit(int k, vector<int>& p) {
        int n = p.size();
        vector<vector<int>> dp(n + 1, vector<int>(2 * k + 1));

        for(int i=n-1; i>=0; i--) {
            for(int t=0; t<2 * k; t++) {
                if(t % 2 == 0) {
                    dp[i][t] = max(-p[i] + dp[i + 1][t + 1], 0 + dp[i + 1][t]);
                }
                else dp[i][t] = max(p[i] + dp[i + 1][t + 1], 0 + dp[i + 1][t]);
            }
        }
        return dp[0][0];
    }
};

class Solution {
public:
    // time/space: O(8)/O(2 ^ 4)
    int hammingWeight(uint32_t n) {
        // divide and conquer
        int count = 0;
        for (int i = 0; i < 8; i++) {
            count += uint4_bits[n & 0b1111];
            n >>= 4;
        }
        return count;
    }
private:
    // build the pre-computed table for the `4-bit` integers
    const vector<int> uint4_bits = {
        0,      // 0b0000
        1,      // 0b0001
        1,      // 0b0010
        2,      // 0b0011
        1,      // 0b0100
        2,      // 0b0101
        2,      // 0b0110
        3,      // 0b0111
        1,      // 0b1000
        2,      // 0b1001
        2,      // 0b1010
        3,      // 0b1011
        2,      // 0b1100
        3,      // 0b1101
        3,      // 0b1110
        4,      // 0b1111
    };
};

