    vector<int> kmp(n+1);
    int i = 0,j = -1;
    kmp[0] = -1;
    while(i < n){
        while(j != -1 && s[j] != s[i]){
            j = kmp[j];      
        }
        j++; i++;     
        kmp[i] = j; 
    }

    return kmp;   
}


