class Solution {
public:

    vector<vector<int>> getSkyline(vector<vector<int>>& buildings) {

        int n = buildings.size();

        vector<vector<int>> arr;

        for(int i = 0; i < n; i++)
        {
            int left = buildings[i][0];

            int right = buildings[i][1];

            int height = buildings[i][2];

