            arr.push_back({left, -height});

            // height >= 0, will denote the end point of rectangle

            arr.push_back({right, height});
        }

        // sort the arr

        sort(arr.begin(), arr.end());

        vector<vector<int>> res;

        int curr_height = 0;

        // declare a multiset, this will store the height of active rectangle

        multiset<int, greater<int>> s;

        s.insert(0);

        for(int i = 0; i < arr.size(); i++)
        {
            if(arr[i][1] < 0)
            {
                s.insert(-arr[i][1]);
            }
            else if(arr[i][1] >= 0)
            {
                // remove the height from multiset, b/c this is not a active rectangle now

                auto it = s.find(arr[i][1]);

                if(it != s.end())
                {
                    s.erase(it);
                }
            }

            // take out the maximum height from multiset

            // if curr_height != max_height, then this is a breaking point

            if(curr_height != *s.begin())
            {
                // push the curr point into res

                res.push_back({arr[i][0], *s.begin()});

                // update curr_height

                curr_height = *s.begin();
            }
        }

        return res;
    }
};

class Solution {
    public List<List<Integer>> getSkyline(int[][] buildings) {
        List<List<Integer>> res = new ArrayList<>();
        List<int[]> heights = new ArrayList<>();

        // transforming buildings
        for (int[] building : buildings) {          // O(n)
            heights.add(new int[] {building[0], -building[2]});
            heights.add(new int[] {building[1], building[2]});
        }

        Collections.sort(heights, (a, b) -> (a[0] == b[0]) ? a[1] - b[1] : a[0] - b[0]);    // O(nlogn)

        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        pq.offer(0);

        int prevMax = 0;

        for (int[] height : heights) {  // O(n)

            if (height[1] < 0) pq.offer(-height[1]);    // takes O(logn)
            else pq.remove(height[1]);                  // takes O(n)

            int currMax = pq.peek();

            if (currMax != prevMax) {
                res.add(Arrays.asList(height[0], currMax));
                prevMax = currMax;
            }
        }

        return res;
    }
}

