class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        if (k == 0) return false;

        Map<Integer, Integer> hashMap = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int integer = nums[i];
            if (hashMap.containsKey(integer) && i - hashMap.get(integer) <= k)
                return true;
            hashMap.put(integer, i);
        }
        return false;
    }
}

class Solution:
    def maximalSquare(self, M):
        m, n, ans = len(M), len(M[0]), 0
        dp, onesRow, onesCol = ([[0]*(n+1) for i in range(m+1)] for cnt in range(3))

        for i, j in product(range(m-1, -1, -1), range(n-1, -1, -1)):
            onesRow[i][j] = 1 + onesRow[i][j+1] if M[i][j] == '1' else 0
            onesCol[i][j] = 1 + onesCol[i+1][j] if M[i][j] == '1' else 0

        for i, j in product(range(m-1, -1, -1), range(n-1, -1, -1)):
            dp[i][j] = 1 + min(onesRow[i][j]-1, onesCol[i][j]-1, dp[i+1][j+1]) if M[i][j] == '1' else 0
            ans = max(ans, dp[i][j])
        return ans * ans

class Solution {
public:
    int maximalSquare(vector<vector<char>>& M) {
        int m = size(M), n = size(M[0]), ans = 0;
        vector<vector<int>> dp(2, vector<int>(n+1));
        for(int i = m-1; ~i; i--)
            for(int j = n-1; ~j; j--) 
                dp[i&1][j] = (M[i][j] == '1' ? 1 + min({dp[(i+1)&1][j], dp[i&1][j+1], dp[(i+1)&1][j+1]}) : 0),
                ans = max(ans, dp[i&1][j]);

        return ans * ans;
    }
};

class Solution {
public:
	int computeArea(int ax1, int ay1, int ax2, int ay2, int bx1, int by1, int bx2, int by2) {
		int a1=(ax2-ax1)*(ay2-ay1), a2=(bx2-bx1)*(by2-by1);
		if(ax1>=bx2 || ax2<=bx1 || ay1>=by2 || ay2<=by1){return a1+a2;}
		vector<int>v, v1;
		v.push_back(ax1); v.push_back(ax2); v.push_back(bx1); v.push_back(bx2);
		sort(v.begin(), v.end());
		v1.push_back(ay1); v1.push_back(ay2); v1.push_back(by1); v1.push_back(by2);
		sort(v1.begin(), v1.end());
		return a1+a2-(v[2]-v[1])*(v1[2]-v1[1]);
	}
};

