class Solution {
public:
    bool isAnagram(string s, string t) {
        int count[26] = {0};

        // Count the frequency of characters in string s
        for (char x : s) {
            count[x - 'a']++;
        }

        // Decrement the frequency of characters in string t
        for (char x : t) {
            count[x - 'a']--;
        }

        // Check if any character has non-zero frequency
        for (int val : count) {
            if (val != 0) {
                return false;
            }
        }

        return true;
    }
};

class Solution {
    public List<String> binaryTreePaths(TreeNode root) {
        List<String> result = new ArrayList<>();
        dfs(root, "", result);
        return result;
    }

    private void dfs(TreeNode node, String path, List<String> result) {
        if (node == null) return;
        //Append the current node's value to the path.
        path += node.val;

        //If it's a leaf node, add the path to the result list.
        if (node.left == null && node.right == null) {
            result.add(path);
        } else {
            path += "->";// Separate nodes in the path.
            dfs(node.left, path, result);
            dfs(node.right, path, result);
        }
    }
}

class Solution {
  private void dfs(TreeNode node, String s, List<String> res) {
    s += node.val;

    if (node.left == null && node.right == null) {
      res.add(s);
      return;
    }
    s += "->";

    if (node.left != null) dfs(node.left, s, res);
    if (node.right != null) dfs(node.right, s, res);
  }

  public List<String> binaryTreePaths(TreeNode root) {
    var res = new ArrayList<String>();
    dfs(root, "", res) ;
    return res;
  }
}

