class Solution:
    def nthUglyNumber(self, n):
        factors, k = [2,3,5], 3
        starts, Numbers = [0] * k, [1]
        for i in range(n-1):
            candidates = [factors[i]*Numbers[starts[i]] for i in range(k)]
            new_num = min(candidates)
            Numbers.append(new_num)
            starts = [starts[i] + (candidates[i] == new_num) for i in range(k)]
        return Numbers[-1]

class Solution {
public:
    int firstBadVersion(int n) {
        long long int start = 0 ; 
        long long int end = n ; 
        long long int minBadVersion ;

        while (start <= end)
        {
            long long int mid = (start + end) / 2 ; 

            if (isBadVersion(mid) == 1)
            {
                minBadVersion = mid ; 
                end = mid - 1 ; 
            }
            else
            {
                start = mid + 1 ; 
            }
        }
        return minBadVersion ;
    }
};

class Solution {
    public void moveZeroes(int[] nums) {
        int i = 0; // Iterator for iterating through the array
        int j = 0; // Position to swap non-zero elements to

        while (i < nums.length) {
            if (nums[i] == 0) {
                // If the current element is zero, just move the iterator forward
                i++;
            } else {
                // If the current element is non-zero, swap it with the element at position j
                int temp = nums[i];
                nums[i] = nums[j];
                nums[j] = temp;

                // Move both iterators forward
                i++;
                j++;
            }
        }
    }
}

