class Solution {
public:
    ListNode* oddEvenList(ListNode* head) {
        vector<int>v;
        ListNode* rt=head;
        ListNode* rt1=head;
        int j=0;
        while(rt){
            if(!(j&1)){v.push_back(rt->val);}
            rt=rt->next;
            j++;
        }
        int j1=0;
        while(rt1){
            if(j1&1){v.push_back(rt1->val);}
            rt1=rt1->next;
            j1++;
        }
        ListNode* root=NULL;
        int i=0;
        while(i<v.size()){
            ListNode* ans=new ListNode;
            ans->val=v[i];
            i++;
            ans->next=root;
            root=ans;
        }
        ListNode* current=root;
        ListNode *prev = NULL, *next = NULL;
        while(current!=NULL){
            next=current->next;
            current->next=prev;
            prev=current;
            current=next;
        }
        root=prev;
        return root;
    }
};

class Solution {
public:
    ListNode* oddEvenList(ListNode* head) {
        int i = 0;
        vector<pair<int,int>> v;
        while(head){
            v.push_back({head->val,++i});
            head = head->next;
        }
        stable_partition(begin(v),end(v),[](auto x){return x.second&1;}); // it'll partition the odd & even element
        ListNode *ans = NULL,*myhead = NULL;
        for(auto &_v: v){
            if(_v.second&1){
                if(!ans){
                    ans = new ListNode(_v.first);
                    myhead = ans;
                }else{
                    ans->next = new ListNode(_v.first);
                    ans = ans->next;
                }
            }else{
                ans->next = new ListNode(_v.first);
                ans = ans->next;
            }
        }
        return myhead;
    }
};

class Solution {
    vector<int> dx = {-1, 0, 1, 0}, dy = {0, 1, 0, -1};
    int dfs(int i, int j, int n, int m, vector<vector<int>> &matrix, vector<vector<int>> &dp) {
        int mx = 0;
        for(int k=0; k<4; k++) {
            int x = i + dx[k], y = j + dy[k];
            if(x >= 0 && x < n && y >= 0 && y < m && matrix[x][y] > matrix[i][j]) {
                if(dp[x][y]) mx = max(mx, dp[x][y]);
                else mx = max(mx, dfs(x, y, n, m, matrix, dp));
            }
        }
        return dp[i][j] = 1 + mx;
    }
public:
    int longestIncreasingPath(vector<vector<int>>& matrix) {
        int n = matrix.size(), m = matrix[0].size(), ans = 0;
        vector<vector<int>> dp(n, vector<int>(m));

       for(int i=0; i<n; i++) {
           for(int j=0; j<m; j++) {
               ans = max(ans, dfs(i, j, n, m, matrix, dp));
           }
       }
       return ans;
    }
};

class Solution {
public:
    bool increasingTriplet(vector<int>& nums) {
        // creating two arrays which will stores the right max and left min values of index of the array nums  
        vector<int> a(nums.size());vector<int> b(nums.size());
        // at starting the min value is the number it self and at end the max value is also number it self 
        a[0]=nums[0];b[nums.size()-1]=nums[nums.size()-1];
        // filling up all the left minimum value using a single loop
        for(int i=1;i<nums.size();i++) a[i]=min(a[i-1],nums[i]);
        // filling up all the right max value using a single loop 
        for(int i=nums.size()-2;i>=0;i--) b[i]=max(b[i+1],nums[i]);
        // if the pair exists we return true and if not the answer will be false 
        for(int i=1;i<nums.size()-1;i++) if(nums[i]>a[i] && nums[i]<b[i]) return true;
        return false;
    }
};

public class NestedIterator implements Iterator<Integer> {

    private List<Integer> flattenedList;
    private Iterator<Integer> it;

    public NestedIterator(List<NestedInteger> nestedList) {
        flattenedList = new LinkedList<Integer>();
        flatten(nestedList);
        it = flattenedList.iterator();
    }

    private void flatten(List<NestedInteger> nestedList) {
        for (NestedInteger i : nestedList) {
            if (i.isInteger()) {
                flattenedList.add(i.getInteger());
            } else {
                flatten(i.getList());
            }
        }
    }

    @Override
    public Integer next() {
        return it.next();
    }

    @Override
    public boolean hasNext() {
        return it.hasNext();
    }
}

