var isPowerOfFour = function(n) {
    if (n <= 0) return false;
    let root = Math.floor(Math.log(n) / Math.log(4));
    if(Math.pow(4,root) == n) return true;
    else return false;
};

class Solution {
    public int integerBreak(int n) {
        if (n == 2 || n == 3) {
            return n - 1;
        }

        int[] dp = new int[n + 1];
        dp[2] = 2;
        dp[3] = 3;

        for (int i = 4; i <= n; i++) {
            dp[i] = Math.max(2 * dp[i - 2], 3 * dp[i - 3]);
        }

        return dp[n];
    }
}

