class Solution {
public:
    bool validUtf8(vector<int>& data) {
        int rbytes = 0; // remaining bytes

        for(int val : data) {
            if(rbytes == 0) { 
                if((val >> 7) == 0b0) { // 1st byte of 1 length char
                    rbytes = 0;
                } else if((val >> 5) == 0b110) { // 1st byte of 2 length char
                    rbytes = 1;
                } else if((val >> 4) == 0b1110) { // 1st byte of 3 length char
                    rbytes = 2;
                } else if((val >> 3) == 0b11110) { // 1st byte of 4 length char
                    rbytes = 3;
                } else { // special cases if arr starts with (10110011) or (11111111)
                    return false;
                }
            } else {
                if((val >> 6) == 0b10) {
                    rbytes--;
                } else {
                    return false;
                }
            }
        }

        if(rbytes == 0) {
            return true;
        } else {
            return false;
        }
    }
};

class Solution {
public:
    string repeat(string& s, int times) {
        for(int n = size(s); --times; s += s.substr(0, n));
        return s;
    }    
    string decodeString(string& s) {
        stack<pair<string, string>> stk;                          // {n, ans} = {count to repeat, string formed in this level till now}
        string ans = "", n = "";
        for(auto c : s)
            if(isalpha(c))      ans += c;
            else if(isdigit(c)) n += c;
            else if(c == '[')   stk.push({move(n), move(ans)});   // directly moves into stack avoiding copy & thus also clears n and ans
            else {
                auto [cnt, prev] = stk.top(); stk.pop();
                ans = prev + repeat(ans, stoi(cnt));
            }

        return ans;
    }
};

class Solution:
    def longestSubstring(self, s, k):
        result = 0
        for T in range(1, len(Counter(s))+1):
            beg, end, Found, freq, MoreEqK = 0, 0, 0, [0]*26, 0
            while end < len(s):
                if MoreEqK <= T:
                    s_new = ord(s[end]) - 97
                    freq[s_new] += 1
                    if freq[s_new] == 1:
                        MoreEqK += 1
                    if freq[s_new] == k:
                        Found += 1
                    end += 1
                else:
                    symb = ord(s[beg]) - 97
                    beg += 1
                    if freq[symb] == k:
                        Found -= 1
                    freq[symb] -= 1
                    if freq[symb] == 0:
                        MoreEqK -= 1

                if MoreEqK == T and Found == T:
                    result = max(result, end - beg)

        return result

class Solution {
public:
    long long solve(long long n)
{
    if(n <= 0){
        return 1e9;
    }
    if (n == 1)
    {
        return 0;
    }

    if (n & 1)
    {
        return 1 + min(solve(n - 1), solve(n + 1));
    }
    else
    {
        return 1 + solve(n / 2);
    }
}

