class Solution {
public:
    bool spaceoptimise2(vector<int> &nums,int target){
        vector<bool> curr(target+1,0);
        curr[0]=1;
        int n=nums.size();
         for(int index=n-1;index>=1;index--){
                for(int t=target;t>=0;t--){
                    bool include=0;
                if(t-nums[index]>=0)
                    include=curr[t-nums[index]];
                    bool exclude=curr[t];
                    curr[t]=(include|| exclude);
                }
            }
            return curr[target];
    }
    bool canPartition(vector<int>& nums) {
        int sum=0;
        for(int i=0;i<nums.size();i++){
            sum+=nums[i];
        }
        if(sum & 1)
            return false;
        int target=sum/2;
        int index=0;
        return spaceoptimise2(nums,target);
    }
};

class Solution {
    public boolean canPartition(int[] nums) {

        int sum=0;
        for(int n:nums){
            sum+=n;
        }
        if(sum%2!=0) return false;
        sum=sum/2;
        int[][] dp=new int[nums.length][sum+1];
       int y= help(nums,0,sum,dp);
       if(y==1) return true;
       return false;
    }
int help(int[] n,int i,int s,int[][] dp){
    if(s==0) return 1;
    if(i>=n.length) return 2;
    if(dp[i][s]!=0) return dp[i][s];
    if(n[i]<=s){
        int h=help(n,i+1,s-n[i],dp);
        int g=help(n,i+1,s,dp);
        if(h==1&&g==2||h==2&&g==1||h==1&&g==1) dp[i][s]=1;
       else dp[i][s]=2;
    }
    else dp[i][s]= help(n,i+1,s,dp);

    return dp[i][s];
}
}

class Solution {
    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        int row=heights.length;
        int col=heights[0].length;

        int pacific[][]=new int[row][col];
        int atlantic[][]=new int[row][col];

        int delRow[]={1,-1,0,0};
        int delCol[]={0,0,1,-1};


        for(int i=0;i<row;i++){
            dfs(i,0,heights,pacific,Integer.MIN_VALUE,delRow,delCol);//first col
            dfs(i,col-1,heights,atlantic,Integer.MIN_VALUE,delRow,delCol);//last col
        }

        for(int j=0;j<col;j++){
            dfs(0,j,heights,pacific,Integer.MIN_VALUE,delRow,delCol);//first row
            dfs(row-1,j,heights,atlantic,Integer.MIN_VALUE,delRow,delCol);//last row
        }

        List<List<Integer>>ans=new ArrayList<>();
        for(int i=0;i<row;i++){
            for(int j=0;j<col;j++){
                if(pacific[i][j]==1 && atlantic[i][j]==1){
                    List<Integer>res=new ArrayList<>();
                    res.add(i);
                    res.add(j);
                    ans.add(res);
                }
            }
        }
        return ans;
    }

    public void dfs(int i,int j,int [][]heights,int[][]visit,int height,int []delRow,int delCol[]){
        int n=heights.length;
        int m=heights[0].length;
        if(i<0 || i>=n || j<0 || j>=m || visit[i][j]==1 || heights[i][j] < height) return;
        visit[i][j]=1;

        for(int k=0;k<4;k++){
            int nrow=i+delRow[k];
            int ncol=j+delCol[k];

            dfs(nrow,ncol,heights,visit,heights[i][j],delRow,delCol);

        }
    }
}

class trie{
    public:
    trie *child[2];
    trie(){
        child[0] = child[1] = NULL;
    }
};

class Solution {
public:
    trie *root;
    int findMaximumXOR(vector<int>& nums) {
        root = new trie();
        for(auto &e : nums){
            insert(root, e);
        }

        int ans = 0;
        for(auto &e : nums){
            int res = 0;
            findmax(root, e, res);
            ans = max(ans, res);
        }
        return ans;
    }

    void findmax(trie *root, int num,  int &res, int i = 31){
        if(!root) return;
        if(i < 0) return;
        int num_b = (num>>i) & 1;
        if(num_b == 1){
            if(root->child[0]){
                res |= (1<<i);
                findmax(root->child[0], num, res, i-1);
            }
            else{
                findmax(root->child[1], num, res, i-1);
            }
        }
        else if(num_b == 0){
            if(root->child[1]){
                res |= (1<<i);
                findmax(root->child[1], num, res, i-1);
            }
            else{
                findmax(root->child[0], num, res, i-1);
            }
        }
    }

    void insert(trie *root, int num, int i = 31){
        if(i >= 0){
            int b = (num>>i)&1;
            if(!root->child[b]) root->child[b] = new trie();
            insert(root->child[b], num, i-1);
        }
    }
};

