class Solution {
public:

    Node* solve(vector<vector<int>>& g,int x, int y,int lim)
    {

        Node *node = new Node(0,false);
        if(lim == 1){
            node->val =   g[x][y];
            node->isLeaf = true;
        }
        else
        {
            lim/=2;
            node->topLeft = solve(g,x,y,lim);
            node->topRight = solve(g,x,y+lim,lim);
            node->bottomLeft = solve(g,x+lim,y,lim);
            node->bottomRight = solve(g,x+lim,y+lim,lim);


        if(node->topLeft->isLeaf && node->topRight->isLeaf && node->bottomLeft->isLeaf && node->bottomRight->isLeaf &&
         node->topLeft->val == node->topRight->val && node->topLeft->val == node->bottomLeft->val && node->topLeft->val == node->bottomRight->val){
            node->val = node->topLeft->val;
            node->isLeaf = true;
            node->topLeft = node->topRight = node->bottomLeft = node->bottomRight = NULL;
      }
        }

        return node;

    }

    Node* construct(vector<vector<int>>& g) {
        return solve(g,0,0,g.size());

    }
};

class Solution {
public:
    vector<vector<int>> levelOrder(Node* root) {
        vector<vector<int>> ans;
        if (!root) return ans;
        queue<Node*> q;
        q.push(root);
        while (!q.empty()) {
            vector<int> vec;
            int len = q.size();
            while (len--) {
                root = q.front();
                q.pop();
                vec.push_back(root->val);
                for (auto node: root->children) {
                    q.push(node);
                }
            }
            ans.push_back(vec);
        }
        return ans;
    }
};

class Solution {
public:
    Node* flatten(Node* head) {
        Node *ptr = head, *tmp_next, *runner;

        while (ptr) {
            if (ptr->child) {

                // Save the current next and connect the child to next
                tmp_next = ptr->next;
                ptr->next = ptr->child;
                ptr->next->prev = ptr;
                ptr->child = NULL;

                // Run till the end of the current list and connect last node to saved next
                runner = ptr->next;
                while (runner->next) runner = runner->next;
                runner->next = tmp_next;
                if (runner->next) runner->next->prev = runner;
            }

            ptr = ptr->next;
        }

        return head;
    }
};

