class Solution {
public:
    vector<string> findAllConcatenatedWordsInADict(vector<string>& words) {
        unordered_set<string> words_set;
        for (string word : words) words_set.insert(word);
        vector<string> res;

        for (string word : words) {
            int n = word.size();
            vector<int> dp(n + 1, 0);
            dp[0] = 1;
            for (int i = 0; i < n; i++) {
                if (!dp[i]) continue;
                for (int j = i + 1; j <= n; j++) {
                    if (j - i < n && words_set.count(word.substr(i, j - i))) {
                        dp[j] = 1;
                    }
                }
                if (dp[n]) {
                    res.push_back(word);
                    break;
                }
            }
        }
        return res;
    }
};

class Solution {
public:
    int findComplement(int num) {
        int i = 31;
        while((num & 1 << i) == 0) i--;   // skip the left 0 bits till we reach the 1st set bit from left
        while(i >= 0)
            num ^= 1 << i--;              // flip all bits by XORing with 1
        return num;
    }
};

