public class Solution {
    public int findMaxConsecutiveOnes(int[] nums) {
        int ans = 0, sum = 0;
        for (int n : nums) {
            sum *= n;
            sum += n;
            ans = Math.max(ans, sum);
        }
        return ans;
    }
}

class Solution {
public:
    map<vector<int>,int>mp;
    void solve(vector<vector<int>>&res,vector<int>&nums,int x,vector<int>&temp){
    if(temp.size()>=2)
        {   
         mp[temp]++;
         if(mp[temp]>1)
             return;
         res.push_back(temp);

        }
        if(x>nums.size())
        {
              return ;
        }


        for(int i=x;i<nums.size();i++){
            if(temp.size()>=1)
            {if(nums[i]<temp[temp.size()-1])
                continue;}

            temp.push_back(nums[i]);
            solve(res,nums,i+1,temp);
            temp.pop_back();//backtracking the changes we made

        }
        return;
    }
    vector<vector<int>> findSubsequences(vector<int>& nums) {
        vector<vector<int>>result;
        vector<int>temp;
        solve(result,nums,0,temp);

        return result;
    }
};

class Solution {
public:
    int solve(int ind, vector<int> &nums, int target, int n)
{
    if (ind == n)
    {
        if (target == 0)
        {
            return 1;
        }
        return 0;
    }

    int pos = solve(ind + 1, nums, target - nums[ind], n);
    int neg = solve(ind + 1, nums, target + nums[ind], n);
    return pos + neg;
}

int findTargetSumWays(vector<int> &nums, int target)
{
    return solve(0, nums, target, nums.size());
}
};

/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number[]}
 */
var nextGreaterElement = function(nums1, nums2) {
    const ans = [];
    for(let i = 0; i < nums1.length; i++){
        let max = -1;
        for(let j = 0; j < nums2.length; j++){
            let index = j;
            if(nums1[i] === nums2[j]){ // Found element in nums2 that matches current element in nums1
                while(index !== nums2.length){ // Iterate through remaining elements in nums2 to find next greater element
                    if(nums2[index] > nums1[i]){
                        max = nums2[index]; // Update max if we find a greater element
                        break;
                    }
                    index++;
                }
            }
        }
        ans.push(max);
    }
    return ans;
}

class Solution {
public:
   vector<int> findDiagonalOrder(vector<vector<int>>& mat) {
        vector<int> res;
        int i = 0, j = 0, n = mat.size(), m = mat[0].size(), add = -1;
        res.push_back(mat[i][j]);
        while (i < n - 1 || j < m - 1) {
            if (j < m - 1 && ((i == 0 && add == -1) || (i == n - 1 && add == 1))) {
                ++ j;
                add = -add;
            } else if ((j == 0 && add == 1) || (j == m - 1 && add == -1)) {
                ++ i;
                add = -add;
            } else {
                i += add;
                j -= add;
            }
            res.push_back(mat[i][j]);
        }
        return res;
    }
};

public class Solution {
    public int[] findDiagonalOrder(int[][] matrix) {
        if (matrix == null || matrix.length == 0) return new int[0];
        int m = matrix.length, n = matrix[0].length;

        int[] result = new int[m * n];
        int row = 0, col = 0, d = 0;
        int[][] dirs = {{-1, 1}, {1, -1}};

        for (int i = 0; i < m * n; i++) {
            result[i] = matrix[row][col];
            row += dirs[d][0];
            col += dirs[d][1];

            if (row >= m) { row = m - 1; col += 2; d = 1 - d;}
            if (col >= n) { col = n - 1; row += 2; d = 1 - d;}
            if (row < 0)  { row = 0; d = 1 - d;}
            if (col < 0)  { col = 0; d = 1 - d;}
        }

        return result;
    }
}

class Solution {
public:
    int findMaximizedCapital(int k, int w, vector<int>& p, vector<int>& c) {
        priority_queue<pair<int,int>> pq1;
        priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pq2;
        for(int i=0;i<p.size();i++){
            if(c[i]>w) pq2.push({c[i],p[i]});
            else pq1.push({p[i],c[i]});
        }

        while(k>0 && (!pq1.empty() || !pq2.empty())){
            while(!pq2.empty() && pq2.top().first<=w){
                pq1.push({pq2.top().second,pq2.top().first});
                pq2.pop();
            }
            if(!pq1.empty()) {
                w+=pq1.top().first;
                pq1.pop();
                k--;
            } else return w;
        }
        return w;
    }
};

class Solution {
public:
    int solve(TreeNode* root,unordered_map<int,int> &mp,int& x){
        if(root ==NULL)return 0;
        int l = solve(root->left,mp,x);
        int r = solve(root->right,mp,x);
        x = max(x,++mp[root->val+l+r]);
        return root->val+l+r;
    }
    vector<int> findFrequentTreeSum(TreeNode* root) {
        int x = -1;
        unordered_map<int,int> mp;
        solve(root,mp,x);
        vector<int> ans;
        for(auto &i: mp){
            if(i.second == x){
                ans.push_back(i.first);
            }
        }
        return ans;
    }
};

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public int findBottomLeftValue(TreeNode root) {
        return helper(root, 0).getKey().val;
    }

    private Pair<TreeNode, Integer> helper(TreeNode root, int height) {
        if(root != null) {
            Pair<TreeNode, Integer> left = helper(root.left, height + 1);
            Pair<TreeNode, Integer> right = helper(root.right, height + 1);

            if(left.getKey() == null && right.getKey() == null)
                return new Pair<>(root, height);

            if(right.getValue() > left.getValue())
                return right;

            return left;
        }

        return new Pair<>(null, Integer.MIN_VALUE);
    }
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<int> largestValues(TreeNode* root) {
          vector<int>res;
          if(!root) return res;

          queue<TreeNode*>q;
          q.push(root);
          while(q.size()){
              int size = q.size();
              int maxi = INT_MIN;
              for(int i =0; i<size; i++){
                  auto node = q.front();
                  q.pop();
                  maxi = max(maxi , node->val);
                  if(node->left) q.push(node->left);
                  if(node->right) q.push(node->right);
              }
              res.push_back(maxi);
          }
          return res;
    }
};

class Solution {
public:
    int findMinMoves(vector<int>& machines) 
    {
        int n= machines.size();
        int sum=0;

        for(int i=0; i<n; i++)
        {
            sum += machines[i];
        }
        if(sum % n != 0)
            return -1;
        int req = sum/n;


        int extra =0, ans=0;
        for(int i=0; i<n; i++)
        {
            extra += machines[i]-req;
            ans = max(ans, max(machines[i]-req, abs(extra)));
        }
        return ans;
    }
};

class Solution {
public:
    int change(int amount, vector<int>& coins) {
        vector<int> dp(amount+1, 0);
        dp[0]=1;//1 comb: no coins for no amount 
        for(int c:coins){
            for(int i=1; i<=amount; i++)
                if (i-c>=0)
                    dp[i]+=dp[i-c];
        }
        return dp[amount]; 
    }
};

class Solution {
public:
    int solve(int amount,vector<int> &coins,vector<vector<int>> &dp,int index)
    {
        if(index>=coins.size())
        {
            return 0;
        }
        if(amount==0)
        {
            return 1;
        }

        if(dp[amount][index]!=-1)
        {
            return dp[amount][index];
        }

        int ans= 0;
        for(int i=index;i<coins.size();i++)
        {
            if(amount>=coins[i])
                ans+=solve(amount-coins[i],coins,dp,i);
        }
        return dp[amount][index] = ans;
    }
    int change(int amount, vector<int>& coins) {
        sort(coins.rbegin(),coins.rend());
        int n = coins.size();
        vector<vector<int>> dp(amount+1,vector<int>(n+1,-1));
        return solve(amount,coins,dp,0);
    }
};

