class Solution:
    def isSubsequence(self, s, t):
        s_i, t_i = 0, 0
        while s_i < len(s) and t_i < len(t):
            s_i, t_i = s_i + (s[s_i] == t[t_i]), t_i + 1
        return s_i == len(s)

    def findLongestWord(self, s, d):
        ans = ""
        for string in d:
            if self.isSubsequence(string, s):
                ans = min(ans, string, key = lambda x: (-len(x), x))
        return ans

class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        //Idea is to replace 0 with -1 & find maximum length of subarray having sum 0;
        for(int i=0;i<nums.size();i++){
            if(nums[i]==0)nums[i]=-1;
        }
        unordered_map<int,vector<int>>m;
        int ans=0,prefix=0;
        for(int i=0;i<nums.size();i++){
            prefix+=nums[i];
            if(prefix==0){
                ans=max(ans,i+1);
            }
            else if(m.find(prefix)!=m.end()){
                ans=max(ans,i-m[prefix][0]);
            }
            m[prefix].push_back(i);

        }
        return ans;

    }
};

class Solution {
