    int f(int ind,vector<int>&vis)
    {
        if(ind==0)
        {
            return 1;
        }
        int ans=0;
        for(int i=1;i<vis.size();i++)
        {
            if(vis[i]==0 && (ind%i==0 || i%ind==0))
            {
                vis[i]=ind;
                ans+=f(ind-1,vis);
                vis[i]=0;
            }
        }
        return ans;
    }
    int countArrangement(int n) {
        vector<int>vis(n+1);
        return f(n,vis);
    }
};

class Solution {
private int x = 0, y = 0;
private int cB(char[][] B,int i,int j){
    int count = 0;
    if(j > 0){
        if(i > 0 && B[i - 1][j - 1] == 'M') count++;
        if(B[i][j - 1] == 'M') count++;
        if(i < x && B[i + 1][j - 1] == 'M') count++;
    }
    if(i > 0 && B[i - 1][j] == 'M') count++;
    if(j < y){
        if(i > 0 && B[i - 1][j + 1] == 'M') count++;
        if(B[i][j + 1] == 'M') count++;
        if(i < x && B[i + 1][j + 1] == 'M') count++;
    }
    if(i < x && B[i + 1][j] == 'M') count++;
    return count;
}
private void uB(char[][] B, int i, int j){
    if(i<0 || j<0 || i>x || j>y || B[i][j] != 'E')
        return;
    int count = cB(B, i, j);
    if(count != 0){
        B[i][j] = (char)(48 + count);
        return;
    }
    B[i][j] = 'B';
    uB(B, i - 1, j - 1);
    uB(B, i - 1, j);
    uB(B, i - 1, j + 1);
    uB(B, i, j - 1);
    uB(B, i, j + 1);
    uB(B, i + 1, j - 1);
    uB(B, i + 1, j);
    uB(B, i + 1, j + 1);
}
public char[][] updateBoard(char[][] B, int[] C) {
    x = B.length - 1;
    y = B[0].length - 1;
    if(B[C[0]][C[1]] == 'M'){
        B[C[0]][C[1]] = 'X';
        return B;
    }
    uB(B, C[0], C[1]);
    return B;
}
}

class Codec:

    def __init__(self):
        self.urls = []

    def encode(self, longUrl):
        self.urls.append(longUrl)
        return 'http://tinyurl.com/' + str(len(self.urls) - 1)

    def decode(self, shortUrl):
        return self.urls[int(shortUrl.split('/')[-1])]

public class Codec {
    Map<String, String> map = new HashMap<>();
    StringBuilder sb = new StringBuilder();
    // Encodes a URL to a shortened URL.
    public String encode(String longUrl) {
        sb.append((char)Math.floor(Math.random() * 100));
        while(map.containsKey(sb.toString())){
            sb.append((char)Math.floor(Math.random() * 100));
        }
        map.put(sb.toString(), longUrl);
        return sb.toString();
    }

    // Decodes a shortened URL to its original URL.
    public String decode(String shortUrl) {
        return map.get(shortUrl);
    }
}

class Solution {
public:
    int findMinDifference(vector<string>& time) {
        vector<int> mi;
        //step 1 time->min
        for(int i=0;i<time.size();i++)
        {
            string cur=time[i];

            int hr=stoi(cur.substr(0,2));
            int minute=stoi(cur.substr(3,2));
            int tot=hr*60+minute;
            mi.push_back(tot);
        }

        //step 2 sort
        sort(mi.begin(),mi.end());

        //step 3 difference min
        int mini=INT_MAX;
        for(int i=0;i<mi.size()-1;i++){
            int diff=mi[i+1]-mi[i];
            mini=min(diff,mini);
        }
        int last1=(mi[0]+1440)-mi[mi.size()-1];
        int last2=mi[mi.size()-1]-mi[0];
        int l=min(last1,last2);
        mini=min(mini,last1);

        return mini;
   }
};

class Solution {
public:
    int singleNonDuplicate(vector<int>& nums) {
        int left = 0, right = nums.size() - 1;
        while (left < right) {
            int mid = (left + right) / 2;
            if (mid % 2 == 1) {
                mid--;
            }
            if (nums[mid] != nums[mid + 1]) {
                right = mid;
            } else {
                left = mid + 2;
            }
        }
        return nums[left];
    }
};

class Solution {
public:
    vector<vector<int>> dir = {{0,1},{0,-1},{-1,0},{1,0}};


    void bfs(queue<vector<int>> q, vector<vector<int>> &arr){
        int n = arr.size();
        int m = arr[0].size();

        while(q.size()!=0){
            vector<int> a = q.front();
            q.pop();
            int r = a[0];
            int c = a[1];
            for(int k=0; k<4; k++){
                int nr = r+dir[k][0];
                int nc = c+dir[k][1];
                if(nr>=0 && nc>=0 && nr<n && nc<m && arr[nr][nc]==-1){
                    arr[nr][nc] = arr[r][c]+1;
                    q.push({nr,nc});
                }
            }
        }
    }
    vector<vector<int>> updateMatrix(vector<vector<int>>& arr) {
        int n = arr.size();
        int m = arr[0].size();

        queue<vector<int>> q;

        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if(arr[i][j]==0){
                    q.push({i,j});
                }else{
                    arr[i][j] = -1;
                }
            }
        }

        bfs(q,arr);
        return arr;
    }
};

class Solution {
public:

    // declare a dp

    int dp[105][105][105];

    int dfs(vector<int>& arr, int left, int right, int streak)
    {
        // base case

        if(left > right)
            return 0;

        // if already is calculated

        if(dp[left][right][streak] != -1)
            return dp[left][right][streak];

        int maxi = 0;

        // break the streak at curr position

        maxi =  (streak + 1) * (streak + 1) + dfs(arr, left + 1, right, 0);

        // remove all the subarrays with different colors

        for(int i = left + 1; i <= right; i++)
        {
            if(arr[i] == arr[left])
            {
                maxi = max({maxi, dfs(arr, left + 1, i - 1, 0) + dfs(arr, i, right, streak + 1)});
            }
        }

        // store the maxi and then return

        return dp[left][right][streak] = maxi;
    }

    int removeBoxes(vector<int>& boxes) {

        int n = boxes.size();

        memset(dp, -1, sizeof(dp));

        return dfs(boxes, 0, n - 1, 0);
    }
};

class Solution {
    private:
    void dfs(unordered_map<int,bool>& visited,int src,vector<vector<int>>& isConnected){
        visited[src]=true;
        int size=isConnected.size();
        for(int col=0;col<isConnected[src].size();col++){
            if(src!=col&& isConnected[src][col]==1){
                if(!visited[col])
                    dfs(visited,col,isConnected);
            }
        }
    }
public:
    int findCircleNum(vector<vector<int>>& isConnected) {
    unordered_map<int,bool> visited;
    int count=0;
    int n=isConnected.size();
    for(int i=0;i<n;i++){
        if(!visited[i]){
            dfs(visited,i,isConnected);
            count++;
        }
    }
    return count;
    }
};

class Solution {
public:
    int findCircleNum(vector<vector<int>>& isConnected) {
        int n = isConnected.size();
        int count = 0;
        vector<int> vis(n, 0);  //Visited Array to check which are visit or not
        queue<int> q;

        for (int i = 0; i < n; i++) {
            if (!vis[i]) {
                count++;
                q.push(i);
                vis[i] = 1;

                while (!q.empty()) {
                    int curr = q.front();
                    q.pop();

                    for (int x = 0; x < n; x++) {   //x - neighbor
                        if (!vis[x] && isConnected[curr][x] == 1) {
                            q.push(x);
                            vis[x] = 1;
                        }
                    }
                }
            }
        }
        return count;
    }
};

class Solution {
public:
    int findCircleNum(vector<vector<int>>& isConnected) {
        int n = isConnected.size();

        // create adjacency list
        vector<vector<int>> adj(n, vector<int>());

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && isConnected[i][j] == 1)
                    adj[i].emplace_back(j);
            }
        }

        vector<bool> visited(n, false);
        int provinces = 0;

        for (int node = 0; node < n; node++) {
            if (!visited[node]) {
                provinces++;
                dfs(node, adj, visited);
            }
        }

        return provinces;
    }

private:
    void dfs(int node, vector<vector<int>>& adj, vector<bool>& visited) {
        visited[node] = true;
        for (auto& adjNode : adj[node]) {
            if (!visited[adjNode])
                dfs(adjNode, adj, visited);
        }
    }
};

class Solution {
public:
int mod = 1e9+7;
    int solve(int n,int a,int b,vector<vector<vector<int>>> &dp){
        if(a<=0)return 0;
        if(b<=0)return 0;
        if(n<=0)return 1;
        if(dp[n][a][b] != -1)return dp[n][a][b];
        return dp[n][a][b] = ((solve(n-1,a,3,dp)+solve(n-1,a-1,3,dp))%mod+solve(n-1,a,b-1,dp))%mod;
    }
    int checkRecord(int n) {
        vector<vector<vector<int>>> dp(n+1,vector<vector<int>>(3,vector<int>(4,-1)));
        return solve(n,2,3,dp);
    }
};

class Solution {
public:
    int subarraySum(vector<int>& arr, int k) {
        int n = arr.size(); // taking the size of the array

        int ans = 0; // ans variable to store our count

        for(int i = 0; i < n; i++) // traverse from the array
        {
            int sum = arr[i]; // provide sum with arr[i]

            if(sum == k) // if element itself equal to k, then also increment count
                ans++;

            for(int j = i + 1; j < n; j++) // now moving forward,
            {
                sum += arr[j]; // add elements with sum

                if(sum == k) // if at any point they become equal to k
                    ans++; // increment answer
            }

        }

        return ans; // and at last, return answer
    }
};

class Solution {
public:
    int arrayNesting(vector<int>& nums) {
        int ans=0;
        vector<int>v(nums.size(), 0);
        for(int i=0; i<nums.size(); i++){
            int cnt=0, k=i;
            while(!v[k]){
                v[k]=1;
                cnt++;
                k=nums[k];
            }
            ans=max(ans, cnt);
        }
        return ans;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    bool isSubtree(TreeNode* root, TreeNode* subRoot) {
        if(subRoot == NULL){
            return true;
        }
        if (root == NULL) {
            return false;
        }
        if (same(root, subRoot)) {
            return true;
        }
        return isSubtree(root->left, subRoot) || isSubtree(root->right, subRoot);
    }
private:
    bool same(TreeNode* r, TreeNode* s) {
        if (r == NULL && s == NULL) {
            return true;
        }
        if (r == NULL || s == NULL) {
            return false;
        }
        if (r->val != s->val) {
            return false;
        }
        return same(r->left, s->left) && same(r->right, s->right);
    }
};

class Solution {
public:
    int minDistance(string A, string B) {
        int n = A.size(), m = B.size();
        int dp[n+1][m+1];
        memset(dp, 0, sizeof(dp));
        for(int i = 1; i <= n; i++){
            for(int j = 1; j <=m; j++){
                dp[i][j] = (A[i-1] == B[j-1]) ? 1 + dp[i-1][j-1] : max(dp[i-1][j], dp[i][j-1]);
            }
        }
        return (n - dp[n][m]) + (m - dp[n][m]);
    }
};

class Solution {
public:
    // To store the output result...
    vector<int> output;
    void traverse(Node* root) {
        // Base case: if the tree is empty...
        if(root == NULL) return;
        // Push the value of the root node to the output...
        output.push_back(root->val);
        // Recursively traverse each node in the children array...
        for(auto node:root->children)
            traverse(node);
    }
    vector<int> preorder(Node* root) {
        output.clear();
        traverse(root);
        return output;
    }
};

class Solution {
public:
    vector<int> preorder(Node* root) {
        vector<int> ans;
        if (root) pre(root, &ans);
        return ans;
    }
    void pre(Node* node, vector<int>* ans) {
        ans->push_back(node->val);
        for (Node* child : node->children)
            pre(child, ans);
    }
};

public class Solution {
    public boolean isValid(String code) {
        if (code.equals("t")) return false;
        code = code.replaceAll("<!\\[CDATA\\[.*?\\]\\]>", "c");

        String prev = "";
        while (!code.equals(prev)) {
            prev = code;
            code = code.replaceAll("<([A-Z]{1,9})>[^<]*</\\1>", "t");
        }

        return code.equals("t");
    }
}

class Solution {
public:
    int lcm(int a,int b)
    {
        return (a/gcd(a,b))*b;
    }
    int gcd(int a,int b)
    {
        return b==0?a:gcd(b,a%b);
    }
    string fractionAddition(string expression) 
    {
        if(expression[0]!='-')
        {
            expression.insert(0,"+");
        }
        vector<pair<int,int>>numden;
        bool leave=false,ispos=true;
        int tempnum;
        int i=0;
        pair<int,int>temp;
        while(1)
        {
            tempnum=0;
            if(expression[i]=='+')
            {
                ispos=true;
                i++;
            }
            else if(expression[i]=='-')
            {
                ispos=false;
                i++;
            }
            while(expression[i]<='9' && expression[i]>='0')
            {
                tempnum*=10;
                tempnum+=(int)(expression[i]-'0');
                i++;
                if(expression[i]=='/')
                {
                    i++;
                    break;
                }
            }
            if(ispos)
            {
                temp.first=tempnum;
            }
            if(!ispos)
            {
                temp.first=-tempnum;
            }
            tempnum=0;
            while(expression[i]<='9' && expression[i]>='0')
            {
                tempnum*=10;
                tempnum+=(int)(expression[i]-'0');
                i++;
                if(i==expression.size())
                {
                    leave=true;
                    break;
                }
                if(expression[i]=='+' || expression[i]=='-')
                {
                    break;
                }
            }
            temp.second=tempnum;
            numden.push_back(temp);
            if(leave)
            {
                break;
            }
        }
        string ans;
        for(i=0;i<numden.size();i++)
        {
            int GCD=gcd(abs(numden[i].first),abs(numden[i].second));
            numden[i].first/=GCD;
            numden[i].second/=GCD;
        }
        int LCM=numden[0].second;
        for(i=1;i<numden.size();i++)
        {
            LCM=lcm(LCM,numden[i].second);
        }
        int deno=LCM;
        int nume=0;
        for(i=0;i<numden.size();i++)
        {
            nume+=(LCM*numden[i].first)/numden[i].second;
        }
        if(nume<0)
        {
            ans.push_back('-');
            nume=-nume;
        }
        int GCD=gcd(nume,deno);
        nume/=GCD;
        deno/=GCD;
        string numerator,denominator;
        if(nume==0)
        {
            numerator="0";
        }
        while(nume!=0)
        {
            numerator.push_back((char)(nume%10+48));
            nume/=10;
        }
        reverse(numerator.begin(),numerator.end());
        if(deno==0)
        {
            denominator="0";
        }
        while(deno!=0)
        {
            denominator.push_back((char)(deno%10+48));
            deno/=10;
        }
        reverse(denominator.begin(),denominator.end());
        ans.append(numerator);
        ans.push_back('/');
        ans.append(denominator);
        return ans;
    }
};

class Solution {
public:
    int dis(vector<int> x,vector<int> y){
        return (x[0]-y[0])*(x[0]-y[0])+(x[1]-y[1])*(x[1]-y[1]);
    }
    bool validSquare(vector<int>& p1, vector<int>& p2, vector<int>& p3, vector<int>& p4) {
        unordered_set<int> st;
        st.insert(dis(p1,p2));
        st.insert(dis(p1,p3));
        st.insert(dis(p1,p4));
        st.insert(dis(p2,p3));
        st.insert(dis(p2,p4));
        st.insert(dis(p3,p4));
        if (st.size()==2){
            for (auto val: st){
                if (val==0)return false;
            }
            return true;
        }
        return false;
    }
};

public class Solution {
    public int findIntegers(int num) {
        StringBuilder sb = new StringBuilder(Integer.toBinaryString(num)).reverse();
        int n = sb.length();

        int a[] = new int[n];
        int b[] = new int[n];
        a[0] = b[0] = 1;
        for (int i = 1; i < n; i++) {
            a[i] = a[i - 1] + b[i - 1];
            b[i] = a[i - 1];
        }

        int result = a[n - 1] + b[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            if (sb.charAt(i) == '1' && sb.charAt(i + 1) == '1') break;
            if (sb.charAt(i) == '0' && sb.charAt(i + 1) == '0') result -= b[i];
        }

        return result;
    }
}

class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        vector<int> tasksCount(26, 0);
        int max = 0, maxCount = 0;

        for (auto task : tasks) if (++tasksCount[task - 'A'] > tasksCount[max]) max = task - 'A';

        for (int i = 0; i < 26; i++) if (tasksCount[i] == tasksCount[max]) maxCount++;

        int result = (tasksCount[max] - 1) * (n + 1) + maxCount;
        return result > tasks.size() ? result : tasks.size();
    }
};

// creating a node that will store data and row and column of it
class node{
public:
    int data;
    int row;
    int col;

    node(int d, int r,int c){
        this->data = d;
        row = r;
        col = c;
    }
};

class cmp{
public:
    bool operator()(node* &a,node* &b){
        return a->data > b->data;
    }
};


class Solution {
public:
    vector<int> smallestRange(vector<vector<int>>& nums) {
        // create a min heap to store the data column and row of an element 
        priority_queue<node*,vector<node*>,cmp> pq;
        //declare initial range 
        int mini =  INT_MAX, maxi = INT_MIN;
        // push the first element of each list (min element of each list) in the heap and also update the min and max value
        for(int i = 0; i < nums.size(); i++){
            int val = nums[i][0];
            mini = min(mini,val);
            maxi = max(maxi,val);
            pq.push(new node(val,i,0));
        }
        // the range for all the first elements of the list will be [mini,maxi] 
        int start = mini, end = maxi;

        while(!pq.empty()){
            node* t = pq.top();
            pq.pop();

            mini = t->data;

            // if the new range is smaller than the previous one then update the new range 
            if(maxi - mini < end - start){
                start = mini;
                end = maxi;
            }
            else if(maxi - mini == end - start){
                if(mini < start){
                    start = mini;
                    end = maxi;
                }
            }

            // if next element exists in the list of mini
            if(t->col < nums[t->row].size() - 1){
                // update maxi if its greater than prev maxi
                maxi = max(maxi,nums[t->row][t->col+1]);
                // push the new element in the heap
                pq.push(new node(nums[t->row][t->col+1],t->row,t->col+1));
            }
            else{
                // if we have exhausted one of the lists then that means we have considered all possible ranges that will have atleast one member from each list
                break;
            }
        }
        return {start,end};
    }
};

class Solution {
    public boolean judgeSquareSum(int c) {
        long a = 0;
        long b = (long) Math.sqrt(c);

        while(a<=b){
            if(((a*a) + (b*b)) == c){
                return true;
            }
            else if((((a*a)+(b*b)) < c)){
                a++;
            }
            else{
                b--;
            }
        }
        return false;
    }
}

class Solution {
public:
    vector<int> exclusiveTime(int n, vector<string>& logs) {
        vector<int> ans(n);
        stack<pair<int,int>> cur;
        int prevTime = 0;
        for (auto& s : logs){
            int num = stoi(s.substr(0, s.find(':')));
            int time = stoi(s.substr(s.rfind(':') + 1));
            if (s.find('e') != -1){
                ans[num] += time - prevTime + 1;
                cur.pop();
                prevTime = time + 1;
            }
            else{
                if (!cur.empty()) ans[cur.top().first] += time - prevTime ;
                cur.push({num, time});
                prevTime = time;
            }
        }
        return ans;
    }
};

/**
 * Dynamic Programming
 *
 * DP[i] = Number of ways to decode the string from 0 to i.
 *
 * DP[i] = DP[i-1] (when i is from 1 to 9) + DP[i-2] (when (i-1,i) is from 10 to
 * 26)
 *
 * Based on star calculate the number of decodings possible.
 *
 * Time Complexity: O(N)
 *
 * Space Complexity: O(1)
 *
 * N = Length of the input string.
 */
class Solution {
    public int numDecodings(String s) {
        if (s == null) {
            throw new IllegalArgumentException("Input string is null");
        }
        if (s.length() == 0 || s.charAt(0) == '0') {
            return 0;
        }

        long pre = 1; // dp[i-2]
        long cur = s.charAt(0) == '*' ? 9 : 1; // dp[i-1]

        for (int i = 1; i < s.length(); i++) {
            long sum = 0; // dp[i]
            char curChar = s.charAt(i);
            char preChar = s.charAt(i - 1);

            if (curChar != '0') {
                sum = cur * (curChar == '*' ? 9 : 1);
            }
            if (preChar == '*') {
                if (curChar == '*') {
                    sum += pre * 15;
                } else if (curChar <= '6') {
                    sum += pre * 2;
                } else {
                    sum += pre;
                }
            } else {
                if (curChar == '*') {
                    if (preChar == '1') {
                        sum += pre * 9;
                    } else if (preChar == '2') {
                        sum += pre * 6;
                    }
                } else {
                    int num = Integer.parseInt(s.substring(i - 1, i + 1));
                    if (num >= 10 && num <= 26) {
                        sum += pre;
                    }
                }
            }

            pre = cur;
            cur = sum % 1000000007;
        }

        return (int) cur;
    }
}

class MyCircularDeque {
    private int[] queue;
    private int front;
    private int rear;
    private int capacity;
    private int size;

    public MyCircularDeque(int k) {
        queue = new int[k];
        front = 0; rear = 0; 
        capacity = k; size = 0;
    }

    public boolean insertFront(int value) {
        if(this.isFull())
            return false;
        front = (capacity + front - 1) % capacity;
        queue[front] = value;
        size++;
        return true;
    }

    public boolean insertLast(int value) {
        if(this.isFull())
            return false;
        queue[rear] = value;
        rear = (rear + 1) % capacity;
        size++;
        return true;
    }

    public boolean deleteFront() {
        if(this.isEmpty())
            return false;
        front = (front + 1) % capacity;
        size--;
        return true;
    }

    public boolean deleteLast() {
        if(this.isEmpty())
            return false;
        rear = (capacity + rear - 1) % capacity;
        size--;
        return true;
    }

    public int getFront() {
        if(this.isEmpty())
            return -1;
        return queue[front];
    }

    public int getRear() {
        if(this.isEmpty())
            return -1;
        return queue[(capacity + rear - 1) % capacity];

    }

    public boolean isEmpty() {
        return size == 0;
    }

    public boolean isFull() {
        return size == capacity;
    }
}

/**
 * Your MyCircularDeque object will be instantiated and called as such:
 * MyCircularDeque obj = new MyCircularDeque(k);
 * boolean param_1 = obj.insertFront(value);
 * boolean param_2 = obj.insertLast(value);
 * boolean param_3 = obj.deleteFront();
 * boolean param_4 = obj.deleteLast();
 * int param_5 = obj.getFront();
 * int param_6 = obj.getRear();
 * boolean param_7 = obj.isEmpty();
 * boolean param_8 = obj.isFull();
 */

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    List<TreeNode> res;
    HashMap<String, Integer> serialCount;
    String pos(TreeNode root)
    {
	    if(root == null) return "#";
	    String serial = root.val + "," + pos(root.left) + pos(root.right);
	    int freq = serialCount.getOrDefault(serial, 0);
	    serialCount.put(serial, ++freq);
	    if (freq == 2) res.add(root);
	    return serial;
    }
    public List<TreeNode> findDuplicateSubtrees (TreeNode root){
	    res = new LinkedList<>();
	    serialCount = new HashMap<>();
	    pos(root);
	    return res;
    }   
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode* constructMaximumBinaryTree(vector<int>& nums) 
    {
        int left = 0;
        int right = nums.size()-1;

        TreeNode* root = NULL;
        return fun(root,nums,left,right);    
    }
    TreeNode* fun(TreeNode* root,vector<int>&nums,int left,int right)
    {
        if(left > right)
        {
            //means we have empty array now 
            //and we dont have the elements to creat the tree further 
            return NULL;
        }

        int pos = search(nums,left,right);

        root = new TreeNode(nums[pos]);
        root->left = fun(root->left,nums,left,pos-1);
        root->right = fun(root->right,nums,pos+1,right);

        return root;
    }
    int search(vector<int>&nums,int left,int right)
    {
        int idx = -1;
        int val = INT_MIN;
        for(int i=left;i<=right;i++)
        {  
            if(nums[i] > val)
            {
                val = nums[i];
                idx = i;
            }
        } 
        return idx;
    }
};

class Solution {
public:
    int heightoftree(TreeNode* root){
        if(!root)return 0;

        return max(heightoftree(root->left),heightoftree(root->right))+1;
    }


    vector<vector<string>> printTree(TreeNode* root) {
        int height=heightoftree(root);

        int m=height,n=pow(2,height)-1;
        vector<vector<string>>ans(m,vector<string>(n,""));

        queue<pair<int,pair<int,TreeNode*>>>q;
        q.push({0,{(n-1)/2,root}});

        while(!q.empty()){

            int s=q.size();

            for(int i=0;i<s;i++){
                auto ele=q.front();
                q.pop();
                int r=ele.first,c=ele.second.first;
                auto root=ele.second.second;

                ans[r][c]=to_string(root->val);

                if(root->left){
                    q.push({r+1,{c-pow(2,height-r-2),root->left}});
                }

                if(root->right){
                    q.push({r+1,{c+pow(2,height-r-2),root->right}});
                }
            }

        }

        return ans;
    }
};

class Solution {
public:
    vector<int> findClosestElements(vector<int>& arr, int k, int x) {        
        int n = size(arr), R = lower_bound(begin(arr), end(arr), x) - begin(arr), L = R - 1;
		// expand the [L, R] window till its size becomes equal to k
        while(k--) 
            if(R >= n || L >= 0 && x - arr[L] <= arr[R] - x) L--;  // expand from left
            else R++;                                              // expand from right
        return vector<int>(begin(arr) + L + 1, begin(arr) + R);
    }
};

class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {

        int start = 0;
        int end = arr.length - 1;
        while (end - start >= k) {
            if (Math.abs(arr[start] - x) > Math.abs(arr[end] - x)) {
                start++;
            } else {
                end--;
            }
        }

        List<Integer> result = new ArrayList<>(k);
        for (int i = start; i <= end; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

class Solution {
public:
    vector<vector<int>> imageSmoother(vector<vector<int>>& inputImage) {
        // Save the dimensions of the image.
        int rows = inputImage.size();
        int cols = inputImage[0].size();

        // Create a new image of the same dimension as the input image.
        vector<vector<int>> smoothImage(rows, vector<int>(cols));

        // Iterate over the cells of the image.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Initialize the sum and count 
                int sum = 0;
                int count = 0;

                // Iterate over all plausible nine indices.
                for (int x = i - 1; x <= i + 1; x++) {
                    for (int y = j - 1; y <= j + 1; y++) {
                        // If the indices form valid neighbor
                        if (0 <= x && x < rows && 0 <= y && y < cols) {
                            sum += inputImage[x][y];
                            count += 1;
                        }
                    }
                }

                // Store the rounded down value in smoothImage[i][j].
                smoothImage[i][j] = sum / count;
            }
        }

        // Return the smooth image.
        return smoothImage;
    }
};

class Solution {
public:
    vector<vector<int>> imageSmoother(vector<vector<int>>& img) {
        // Save the dimensions of the image.
        int m = img.size(); // Number of rows
        int n = img[0].size(); // Number of columns

        // Create a temporary array of size 'n' to store previous row pixel values.
        vector<int> temp(n);
        int prevVal = 0; // Store the original value of temp[j] (representing img[i - 1][j])

        // Iterate over the cells of the image.
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // Initialize the sum and count for averaging.
                int sum = 0;
                int count = 0;

                // Accumulate neighboring pixel values for averaging.
                // Bottom neighbors
                if (i + 1 < m) {
                    if (j - 1 >= 0) {
                        sum += img[i + 1][j - 1];
                        count += 1;
                    }
                    sum += img[i + 1][j];
                    count += 1;
                    if (j + 1 < n) {
                        sum += img[i + 1][j + 1];
                        count += 1;
                    }
                }

                // Next neighbor
                if (j + 1 < n) {
                    sum += img[i][j + 1];
                    count += 1;
                }

                // This cell
                sum += img[i][j];
                count += 1;

                // Previous neighbor
                if (j - 1 >= 0) {
                    sum += temp[j - 1];
                    count += 1;
                }

                // Top neighbors
                if (i - 1 >= 0) {
                    // Left-top corner-sharing neighbor.
                    if (j - 1 >= 0) {
                        sum += prevVal;
                        count += 1;
                    }

                    // Top edge-sharing neighbor.
                    sum += temp[j];
                    count += 1;

                    // Right-top corner-sharing neighbor.
                    if (j + 1 < n) {
                        sum += temp[j + 1];
                        count += 1;
                    }
                }

                // Save the original value of temp[j], which represents the original value of img[i - 1][j].
                if (i - 1 >= 0) {
                    prevVal = temp[j];
                }

                // Save the current value of img[i][j] in temp[j].
                temp[j] = img[i][j];

                // Overwrite the current pixel value with the smoothed value (average).
                img[i][j] = sum / count;
            }
        }

        // Return the smoothed image.
        return img;
    }
};

class Solution {
public:
    public:
    std::vector<std::vector<int>> imageSmoother(std::vector<std::vector<int>>& img) {
        int m = img.size();
        int n = img[0].size();
        std::vector<std::vector<int>> res(m, std::vector<int>(n, 0));

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                res[i][j] = smoothen(img, i, j);
            }
        }

        return res;
    }

private:
    int smoothen(const std::vector<std::vector<int>>& img, int x, int y) {
        int m = img.size();
        int n = img[0].size();
        int sum = 0;
        int count = 0;

        for (int i = -1; i <= 1; ++i) {
            for (int j = -1; j <= 1; ++j) {
                int nx = x + i;
                int ny = y + j;
                if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                    sum += img[nx][ny];
                    ++count;
                }
            }
        }

        return sum / count;
    }
};

class Solution {
    static char ch[]=new char[100]; int n;
    public int strangePrinter(String s) {
        setCompressedString(s);
        return f(0,n-1,new Integer[n][n]);
    }
    private void setCompressedString(String s){
        int x=s.length(),k=0;
        for(int i=0;i<x;i++) 
            if(i==x-1 || s.charAt(i)!=s.charAt(i+1))
                ch[k++]=s.charAt(i);
        n=k;
    }
    private int f(int i, int j, Integer[][] memo){
        if(i==j) return 1;
        if(memo[i][j]!=null) return memo[i][j];
        int res=101;
        for(int k=i;k<j;k++)
            res=Math.min(res, f(i,k,memo)+f(k+1,j,memo));
        return memo[i][j]=ch[i]==ch[j]? res-1:res;
    }
}

class Solution {
public:
    vector<int> constructArray(int n, int k) {
        vector<int> ans;
        int i = 1, j = n;
        while(i<=j)
        {
            if(k>1)
                ans.push_back( (k--)%2 ? i++ : j--); 
            else
                ans.push_back(i++);
        }
        return ans;
    }
};

class Solution {
public:
	// counts number of integers less than or equal to x in multiplication table
    int count(int m, int n, int x) {
        int ans = 0;
        for(int i = 1; i <= m; i++) 
            ans += min(x / i, n);
        return ans;
    }
    int findKthNumber(int m, int n, int k) {
        int L = 1, R = m*n, mid, ans;
        while(L <= R) {
            mid = (L + R) >> 1;
            if(count(m, n, mid) < k) 
                L = mid + 1;
            else
                R = mid - 1, ans = mid;
        }
        return ans;
    }
};

class Solution {
    public TreeNode trimBST(TreeNode root, int low, int high) {
        if(root==null){
            return null;
        }
        root.left=trimBST(root.left,low,high);
        root.right=trimBST(root.right,low,high);
        if(root.val<low || root.val>high){
            if(root.left!=null){
                root=root.left;
            }else if(root.right!=null){
                root=root.right;
            }else{
                root=null;
            }
        }
        return root;
    }
}

class Solution {
    static int[][] dir = {{0,1}, {0, -1}, {1, 0}, {-1, 0}};

    public int cutOffTree(List<List<Integer>> forest) {
        if (forest == null || forest.size() == 0) return 0;
        int m = forest.size(), n = forest.get(0).size();

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (forest.get(i).get(j) > 1) {
                    pq.add(new int[] {i, j, forest.get(i).get(j)});
                }
            }
        }

        int[] start = new int[2];
        int sum = 0;
        while (!pq.isEmpty()) {
            int[] tree = pq.poll();
            int step = minStep(forest, start, tree, m, n);

            if (step < 0) return -1;
            sum += step;

            start[0] = tree[0];
            start[1] = tree[1];
        }

        return sum;
    }

    private int minStep(List<List<Integer>> forest, int[] start, int[] tree, int m, int n) {
        int step = 0;
        boolean[][] visited = new boolean[m][n];
        Queue<int[]> queue = new LinkedList<>();
        queue.add(start);
        visited[start[0]][start[1]] = true;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] curr = queue.poll();
                if (curr[0] == tree[0] && curr[1] == tree[1]) return step;

                for (int[] d : dir) {
                    int nr = curr[0] + d[0];
                    int nc = curr[1] + d[1];
                    if (nr < 0 || nr >= m || nc < 0 || nc >= n 
                        || forest.get(nr).get(nc) == 0 || visited[nr][nc]) continue;
                    queue.add(new int[] {nr, nc});
                    visited[nr][nc] = true;
                }
            }
            step++;
        }

        return -1;
    }
}

class Solution {
    public boolean validPalindrome(String s) {
        return util1(s);
    }
    public boolean util1(String str) {
        int i = 0, j = str.length() - 1;
        while (i <= j) {
            if (str.charAt(i) == str.charAt(j)) {
                i++;
                j--;
            } else {
                return func(str, i + 1, j) || func(str, i, j - 1);
            }
        }
        return true;
    }

    public boolean func(String str, int i, int j) {
        while (i <= j) {
            if (str.charAt(i) != str.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
}

class Solution {
public:
    int longestUnivaluePath(TreeNode* root) {
        if (root == nullptr)
            return 0;

        int longestPath = 0;
        calculateLongestPath(root, longestPath);
        return longestPath;
    }

private:
    int calculateLongestPath(TreeNode* node, int& longestPath) {
        if (node == nullptr)
            return 0;

        int leftPath = calculateLongestPath(node->left, longestPath);
        int rightPath = calculateLongestPath(node->right, longestPath);

        int arrowLeft = 0, arrowRight = 0;
        if (node->left != nullptr && node->left->val == node->val)
            arrowLeft += leftPath + 1;
        if (node->right != nullptr && node->right->val == node->val)
            arrowRight += rightPath + 1;

        longestPath = max(longestPath, arrowLeft + arrowRight);
        return max(arrowLeft, arrowRight);
    }
};

class Solution {
    public int longestUnivaluePath(TreeNode root) {
        int[] res = new int[1];
        if (root != null) dfs(root, res);
        return res[0];
    }

    private int dfs(TreeNode node, int[] res) {
        int l = node.left != null ? dfs(node.left, res) : 0; // Longest-Univalue-Path-Start-At - left child
        int r = node.right != null ? dfs(node.right, res) : 0; // Longest-Univalue-Path-Start-At - right child
        int resl = node.left != null && node.left.val == node.val ? l + 1 : 0; // Longest-Univalue-Path-Start-At - node, and go left
        int resr = node.right != null && node.right.val == node.val ? r + 1 : 0; // Longest-Univalue-Path-Start-At - node, and go right
        res[0] = Math.max(res[0], resl + resr); // Longest-Univalue-Path-Across - node
        return Math.max(resl, resr);
    }
}

class Solution(object):
    def minStickers(self, stickers, target):
        m = len(stickers)
        mp = [[0]*26 for y in range(m)] 
        for i in range(m):
            for c in stickers[i]:
                mp[i][ord(c)-ord('a')] += 1    
        dp = {}
        dp[""] = 0

        def helper(dp, mp, target):
            if target in dp:
                return dp[target]
            n = len(mp)
            tar = [0]*26
            for c in target:
                tar[ord(c)-ord('a')] += 1   
            ans = sys.maxint
            for i in xrange(n):
                if mp[i][ord(target[0])-ord('a')] == 0:
                    continue
                s = ''
                for j in range(26):
                    if tar[j] > mp[i][j]:
                        s += chr(ord('a')+j)*(tar[j] - mp[i][j]) 
                tmp = helper(dp, mp, s)
                if (tmp != -1): 
                    ans = min(ans, 1+tmp)    
            dp[target] = -1 if ans == sys.maxint else ans
            return dp[target]

        return helper(dp, mp, target)

import java.util.*;

class Heap
{
    Object [][] heap;
    int size;
    int startInt = 0;
    String startStr = null;
    int leftSon = 0;
    String leftStr = null;
    int rigthSon = 0;
    String rightStr = null;

    int indexStart;
    int indexLeftSon;
    int indexRigthSon;

    Heap(int sizeHip)
    {
        heap = new Object[sizeHip][2];
        size = 0;
    }

    public Object[] removeMax() //size--
    {
        Object[] answ = heap[0];
        if (size > 0) {
            heap[0] = heap[size - 1];
            size--;
        }
        siftDown();
        return answ;
    }
    public void addElem(String word, int count) //size++
    {
        size++;
        heap[size - 1] = new Object[]{word,count};
        siftUp();
    }


    public void changePlace(int child)
    {
        Object[] tmp;

        tmp = heap[child];
        heap[child] = heap[indexStart];
        heap[indexStart] = tmp;
        indexStart = child;
        indexLeftSon = getLeftChild(indexStart);
        indexRigthSon = getRightChild(indexStart);
    }

    public boolean differentNums(int start, int first, int second, String startStr, String firstStr)
    {
        return (first > second && ((start < first) || (start == first && startStr.compareTo(firstStr) > 0)));
    }
    public boolean onlySize(int startInt, int find, String startStr, String findStr)
    {
        return  ((startInt < find) || (startInt == find && startStr.compareTo(findStr) > 0));
    }

    public void initParams()
    {
        startInt = (int)heap[indexStart][1];
        startStr = (String)heap[indexStart][0];
        leftSon = 0;
        rigthSon = 0;
        leftStr = null;
        rightStr = null;
        if (indexLeftSon < size)
        {
            leftSon = (int)heap[indexLeftSon][1];
            leftStr = (String)heap[indexLeftSon][0];
        }
        if (indexRigthSon < size)
        {
            rigthSon = (int)heap[indexRigthSon][1];
            rightStr = (String)heap[indexRigthSon][0];
        }
    }

    public void siftDown()
    {
        indexStart = 0;
        indexLeftSon = getLeftChild(indexStart);
        indexRigthSon = getRightChild(indexStart);
        while (true)
        {
            initParams();
            if (indexLeftSon < size && indexRigthSon < size)
            {
                if (differentNums(startInt, leftSon, rigthSon, startStr, leftStr))
                    changePlace(indexLeftSon);
                else if (differentNums(startInt, rigthSon, leftSon, startStr, rightStr))
                    changePlace(indexRigthSon);

                else if(leftSon == rigthSon && (leftSon > startInt)) {
                    if (leftStr.compareTo(rightStr) < 0)
                        changePlace(indexLeftSon);
                    else if (leftStr.compareTo(rightStr) > 0)
                        changePlace(indexRigthSon);
                }
                else if(leftSon == rigthSon && leftSon == startInt) {
                    if (leftStr.compareTo(rightStr) < 0) {
                        if (leftStr.compareTo(startStr) < 0) changePlace(indexLeftSon);
                        else break;
                    }
                    else {
                        if (rightStr.compareTo(startStr) < 0) changePlace(indexRigthSon);
                        else break;
                    }
                }
                else
                    break;
            }
            else if ((indexLeftSon < size) && onlySize(startInt, leftSon, startStr, leftStr))
                changePlace(indexLeftSon);
            else if ((indexRigthSon < size) && onlySize(startInt, rigthSon, startStr, rightStr))
                changePlace(indexRigthSon);
            else
                break;
        }
    }

    public void siftUp()
    {
        int child = size - 1;
        int parent = getParent(child);
        Object[] tmp;
        String one = (String)heap[parent][0];
        while (parent > -1 && ((int)heap[parent][1] < (int)heap[child][1]
                || parent != child && heap[parent][1] == heap[child][1]
                && one.compareTo(heap[child][0].toString()) > 0))
        {
            tmp = heap[child];
            heap[child] = heap[parent];
            heap[parent] = tmp;
            child = parent;
            parent = getParent(child);
            one = (String)heap[parent][0];
        }
    }

    public int getParent(int child) { return (child - 1) / 2; }

    public int getLeftChild(int parent) { return parent * 2 + 1; }

    public int getRightChild(int parent) { return parent * 2 + 2; }
}

class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        HashMap<String, Integer> dict = new HashMap<>();
        List<String> answ = new ArrayList<>();
        for (int i = 0; i < words.length; i++)
        {
            if (!dict.containsKey(words[i]))
                dict.put(words[i], 0);
            dict.put(words[i], dict.get(words[i]) + 1);
        }
        Heap heap = new Heap(dict.size());
        for (Map.Entry<String, Integer> entry: dict.entrySet())
            heap.addElem(entry.getKey(), entry.getValue());
        for(int i = 0; i < k; i++)
            answ.add((String)heap.removeMax()[0]);
        return answ;
    }
}

class Solution {
private:
    int dfs(vector<vector<int>>& grid,int i,int j,int& t){
        int n=grid.size(),m=grid[0].size();
        if(i>=0 && i<n && j>=0 && j<m && grid[i][j]==1){
            grid[i][j]=0;
            t++;
            dfs(grid,i+1,j,t);
            dfs(grid,i-1,j,t);
            dfs(grid,i,j+1,t);
            dfs(grid,i,j-1,t);
        }
        return t;
    }

public:
    int maxAreaOfIsland(vector<vector<int>>& grid) {
        int n=grid.size(),m=grid[0].size(),ans=0;
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(grid[i][j]==1){
                    int t=0;
                    ans=max(ans,dfs(grid,i,j,t));
                }
            }
        }
        return ans;
    }
};

class Solution {
    // declare length of rows
    int m;
    // declare length of cols
    int n;
    // declare directions array to traverse coordinates in each direction
    public int[][] directions = new int[][]{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    // declare seen matrix to store visited coordinates
    public boolean[][] seen;
    // declare maxArea that will hold max area of islands
    public int maxArea = 0;
    // declare currArea that will hold area of each found island
    public int currArea = 0;
    public int maxAreaOfIsland(int[][] grid) {
        // set rows length
        m = grid.length;
        // set cols length
        n = grid[0].length;
        // set seen matrix of m * n 
        seen = new boolean[m][n];
        // iterate over rows:
        for(int row = 0; row < m; row++) {
            // iterate over cols:
            for(int col = 0; col < n; col++) {
                // if coordinate are island and we have not visited it:
                if(grid[row][col] == 1 && !seen[row][col]) {
                    // set current coordinate as visited
                    seen[row][col] = true;
                    // increase current area
                    currArea++;
                    // start dfs traversal of island
                    dfs(row, col, grid);
                    // check max value of current area nad max area, and set bigger as maxArea
                    maxArea = Math.max(currArea, maxArea);
                    // clear current area
                    currArea = 0;
                }
            }
        }
        return maxArea;
    }
    // declare isValid function:
    public boolean isValid(int row, int col, int[][] grid) {
        // that checks if current coordinates are ni boundaryies of grid and it's an island
        return 0 <= row && row < m && 0 <= col && col < n && grid[row][col] == 1;
    }
    // declare dfs function:
    public void dfs(int row, int col, int[][] grid) {
        // iterate over all directions:
        for(int[] direction: directions) {
            // get new row coordinate
            int nextRow = row + direction[0];
            // get new col coordinate
            int nextCol = col + direction[1];
            // check if new coordinates are valid and not visited:
            if(isValid(nextRow, nextCol, grid) && !seen[nextRow][nextCol]) {
                // increment current area
                currArea++;
                // set new coordinate as visited
                seen[nextRow][nextCol] = true;
                // traverse island further
                dfs(nextRow, nextCol, grid);
            }
        }
    }
}

class Solution {
public:
    TreeNode* insertIntoBST(TreeNode* root, int val) {
        if(root==NULL)
        return new TreeNode(val);
        if(val> root->val)
        root->right=insertIntoBST(root->right,val);
        else if(val < root->val)
        root->left=insertIntoBST(root->left, val);
        return root;
   }
};

class KthLargest {
public:
    priority_queue <int, vector<int>, greater<int>> pq;
    int x;
    KthLargest(int k, vector<int>& nums) {
        x = k;
        if(nums.size() >= k){
            for(int i = 0; i < k; i++){
                pq.push(nums[i]);
            }
            for(int i = k; i < nums.size(); i++){
                if(nums[i] > pq.top()){
                    pq.pop();
                    pq.push(nums[i]);
                }
            }
        }
        else{
            if(nums.size() != 0){
                for(int i = 0; i < nums.size();i++){
                    pq.push(nums[i]);
                }
            }
        }
    }

    int add(int val) {
        if(x > pq.size()){
            pq.push(val);
        }
        else{
            if(val > pq.top()){
                pq.pop();
                pq.push(val);
            }
        }
        return pq.top();
    }
};

