class Solution {

    class Interval {
        int low;
        int high;
        int preCount;
        Interval(int low, int high, int preCount) {
            this.low = low;
            this.high = high;
            this.preCount = preCount;
        }
    }

    private List<Interval> intervals;
    private Random r;
    private int l;

    public Solution(int N, int[] blacklist) {
        Arrays.sort(blacklist);
        intervals = new ArrayList<>();
        r = new Random();
        l = N - blacklist.length;
        int pre = 0, count = 0;
        for (int b : blacklist) {
            if (pre != b) {
                intervals.add(new Interval(pre, b - 1, count));
                count += b - pre;
            }
            pre = b + 1;
        }
        intervals.add(new Interval(pre, N - 1, count));
    }

    public int pick() {
        int index = r.nextInt(l);
        int low = 0, high = intervals.size() - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            Interval cur = intervals.get(mid);
            if (cur.preCount <= index && index < cur.preCount + cur.high - cur.low + 1) {
                return cur.low + index - cur.preCount;
            } else if (cur.preCount > index) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return -1;
    }
}

public class Solution {
    public int MinimumDeleteSum(string s1, string s2) {
        int m = s1.Length;
        int n = s2.Length;

        int[,] dp = new int[m + 1, n + 1];

        // Initialize base cases
        for (int i = 1; i <= m; i++) {
            dp[i, 0] = dp[i - 1, 0] + s1[i - 1];
        }

        for (int j = 1; j <= n; j++) {
            dp[0, j] = dp[0, j - 1] + s2[j - 1];
        }

        // Fill the dp array
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1[i - 1] == s2[j - 1]) {
                    dp[i, j] = dp[i - 1, j - 1];
                } else {
                    dp[i, j] = Math.Min(dp[i - 1, j] + s1[i - 1], dp[i, j - 1] + s2[j - 1]);
                }
            }
        }

        return dp[m, n];
    }
}

class RangeModule {
public:
   void addRange(int left, int right) {
        int n = invals.size();
        vector<pair<int, int>> tmp;
        for (int i = 0; i <= n; i++) {
            if (i == n || invals[i].first > right) {
                tmp.push_back({left, right});
                while (i < n) tmp.push_back(invals[i++]);
            }
            else if (invals[i].second < left) 
                tmp.push_back(invals[i]);
            else {
                left = min(left, invals[i].first);
                right = max(right, invals[i].second);
            }
        }
        swap(invals, tmp);
    }

    bool queryRange(int left, int right) {
        int n = invals.size(), l = 0, r = n-1;
        while (l <= r) {
            int m = l+(r-l)/2;
            if (invals[m].first >= right)
                r = m-1;
            else if (invals[m].second <= left)
                l = m+1;
            else 
                return invals[m].first <= left && invals[m].second >= right;
        }
        return false;
    }

    void removeRange(int left, int right) {
        int n = invals.size();
        vector<pair<int, int>> tmp;
        for (int i = 0; i < n; i++) {
            if (invals[i].second <= left || invals[i].first >= right)
                tmp.push_back(invals[i]);
            else {
                if (invals[i].first < left)  tmp.push_back({invals[i].first, left});
                if (invals[i].second > right) tmp.push_back({right, invals[i].second});
            }
        }
        swap(invals, tmp);
    }
private:
    vector<pair<int, int>> invals;
};

class Solution {
public:
    int findLength(vector<int>& s1, vector<int>& s2) {
        int x=s1.size();
//calculating Size of first vector s1
        int y=s2.size();
//calculating Size of 2nd vector s2
        vector<vector<int>> dp(x+1,vector<int>(y+1,0));
//a 2d vector of size x+1 and y+1 
        for(int j=0;j<=y;j++){
            dp[0][j]=0;
//storing value 0 for 1st row

        }
        for(int i=0;i<=x;i++){
            dp[i][0]=0;

        }
//storing value 0 for 1st column

        int ans = 0;
//a answer variable initial value set to 0
        for(int i=1;i<=x;i++){
            for(int j=1;j<=y;j++){
                if(s1[i-1]==s2[j-1]){
//if vectors consecutive element are matched the adding 1 to previous //diagonally stored value
                    dp[i][j]=1+dp[i-1][j-1];

                    ans=max(ans,dp[i][j]);
//storing maximum value to ans variable
                }
                else{
                    dp[i][j]=0;
// if element not matched then store 0 at that index
                }
            }
        }
        return ans;
// at last return 0
    }

};


