class Solution {
    public int[][] floodFill(int[][] image, int sr, int sc, int color) {
        int startColor = image[sr][sc];
        if (startColor == color)
            return image;
        image[sr][sc] = color;
        LinkedList<Integer[]> line = new LinkedList<>();
        int [][]move = new int[][]{{0,1}, {0, -1}, {1, 0}, {-1, 0}};
        line.add(new Integer[]{sr, sc});
        Integer []tmp;
        while (line.size() > 0) {
            tmp = line.getFirst();
            line.removeFirst();
            for (int[] step : move) {
                if (tmp[0] + step[0] > -1 && tmp[0] + step[0] < image.length &&
                        tmp[1] + step[1] > -1 && tmp[1] + step[1] < image[0].length &&
                        image[tmp[0] + step[0]][tmp[1] + step[1]] == startColor) {
                    image[tmp[0] + step[0]][tmp[1] + step[1]] = color;

                        line.add(new Integer[]{tmp[0] + step[0], tmp[1] + step[1]});
                }
            }
        }
        return image;
    }
}

class Solution {
public:

    int initialcol;
    int col;

    void helper(vector<vector<int>> &arr, int a, int b){
        int n = arr.size();
        int m = arr[0].size();

        if(a<0 || b<0 || a>=n || b>=m) return;

        if(arr[a][b]!=initialcol) return;

        arr[a][b] = col;

        helper(arr,a,b+1);
        helper(arr,a,b-1);
        helper(arr,a-1,b);
        helper(arr,a+1,b);
    }
    vector<vector<int>> floodFill(vector<vector<int>>& arr, int sr, int sc, int color) {
        initialcol = arr[sr][sc];
        col = color;
        if(initialcol==col) return arr;
        helper(arr,sr,sc);
        return arr;
    }
};

class Solution {
    public int deleteAndEarn(int[] nums) {
        Arrays.sort(nums);

        List<int[]> list = new ArrayList<>();
        for(int num : nums){
            if(!list.isEmpty() && list.get(list.size()-1)[0] == num){
                list.get(list.size()-1)[1]++;
            }
            else{
                list.add(new int[]{num, 1});
            }
        }
        int n = list.size(); 
        int[] memo = new int[n];

        for(int i=n-1; i>=0; i--){
            int curr = list.get(i)[0] * list.get(i)[1];

            int nextToAdj = (i+2 < n ? memo[i+2] : 0) + curr;

            int adj = i+1 < n ? memo[i+1] : 0;

            if(i<n-1 && list.get(i+1)[0] != list.get(i)[0]+1){
                adj += curr;
            }
            memo[i] = Math.max(adj, nextToAdj);
        }

        return memo[0];
    }
}

var isNStraightHand = function(hand, groupSize) {
  if (hand.length % groupSize !== 0) {
    return false;
  }

  const countMap = new Map();

  // Count the occurrences of each card
  for (const card of hand) {
    countMap.set(card, (countMap.get(card) || 0) + 1);
  }

  // Sort the cards in ascending order
  hand.sort((a, b) => a - b);

  for (const card of hand) {
    if (countMap.get(card) === 0) {
      // Skip cards that have been used in previous groups
      continue;
    }

    // Check if we can form a group of consecutive cards
    for (let i = 0; i < groupSize; i++) {
      const currCard = card + i;

      if (countMap.get(currCard) === undefined || countMap.get(currCard) === 0) {
        // If any card in the group is missing, return false
        return false;
      }

      // Reduce the count of the current card in the map
      countMap.set(currCard, countMap.get(currCard) - 1);
    }
  }

  return true;
}

class Solution {

    static void helper(StringBuilder s, long arr[], char alpha[]){
        for(int i=0; i<arr.length; i++){
            long a = s.charAt(i)-97;
            a = a+arr[i];
            a=a%26;
            s.replace(i,i+1,alpha[(int)a]+"");
        }
    }
    public String shiftingLetters(String str, int[] arr) {

        StringBuilder s = new StringBuilder(str);
        char alpha[] = new char[26];
        char ch = 'a';

        for(int i=0; i<26; i++){
            alpha[i] = ch;
            ch++;
        }

        int n = arr.length;
        long a[] = new long[n];
        a[n-1] = arr[n-1];

        for(int i=n-2; i>=0; i--){
            a[i] = a[i+1]+arr[i];
        }

        helper(s,a,alpha);
        return s.toString();
    }
}

class Solution:
    def rectangleArea(self, rectangles):
        xs = sorted(set([x for x1, y1, x2, y2 in rectangles for x in [x1, x2]]))
        ys = sorted(set([y for x1, y1, x2, y2 in rectangles for y in [y1, y2]]))
        x_i = {v: i for i, v in enumerate(xs)}
        y_i = {v: i for i, v in enumerate(ys)}
        m, n = len(y_i), len(x_i)

        grid = [[0] * m for _ in range(n)]
        for x1, y1, x2, y2 in rectangles:
            for x in range(x_i[x1], x_i[x2]):
                for y in range(y_i[y1], y_i[y2]):
                    grid[x][y] = 1

        ans = 0
        for x in range(n-1):
            for y in range(m-1):
                ans += grid[x][y]*(xs[x+1] - xs[x]) * (ys[y+1] - ys[y])
        return ans  % (10**9 + 7)

class Solution {
    public int rectangleArea(int[][] A) {
        int ans = 0, L = 1, R = -1, px = 0, M = (int)1e9+7;
        TreeMap<Integer, List<int[]>> map = new TreeMap<>(); // xmap: x value to a list of items to be updated
        TreeMap<Integer, Integer> ymap = new TreeMap<>(); // ymap: y value to rectangle counts
        for (int i = 0; i < A.length; i++){
            map.computeIfAbsent(A[i][0], o -> new ArrayList<>()).add(new int[]{i, L});
            map.computeIfAbsent(A[i][2], o -> new ArrayList<>()).add(new int[]{i, R});
        }
        for (int x : map.keySet()){
            int py = 0, cnt = 0, sum = 0;
            for (int y : ymap.keySet()){ // sum all y that is covered by a rect
                if (cnt > 0){ // there is at least 1 rect, so add it to sum.
                    sum += y - py;
                }
                py = y;
                cnt += ymap.get(y);
            }
            ans += 1L * (x - px) * sum % M;
            ans %= M;
            px = x;
            for (int[] m : map.get(x)){ // update y values 
                ymap.merge(A[m[0]][1],  1*m[1], Integer::sum); // we can remove this key if count = 0 after update (x2 faster)
                ymap.merge(A[m[0]][3], -1*m[1], Integer::sum); // we can remove this key if count = 0 after update (x2 faster)
            }
        }
        return ans;
    }
}

class Solution {
public:

int carFleet(int target, vector<int> &position, vector<int> &speed)
{
    vector<pair<int, int>> pr;
    int numberOfFleets = position.size();
    if (numberOfFleets == 1)
        return numberOfFleets;
    for (int i = 0; i < numberOfFleets; i++)
        pr.push_back({position[i], speed[i]});

    // sort them according to the position accendingly
    sort(pr.begin(), pr.end());

    // build a number of steps vector
    vector<float> numberOfSteps(numberOfFleets);

    for (int i = 0; i < numberOfFleets; i++)
        numberOfSteps[i] = (target - pr[i].first) / (float)pr[i].second;

    for (int i = position.size() - 1; i > 0; i--)
    {
        if (numberOfSteps[i] >= numberOfSteps[i - 1])
        {
            numberOfFleets--;
            numberOfSteps[i - 1] = numberOfSteps[i];
        }
    }

    return numberOfFleets;
}
};

class Solution {
public:
    int i = 0;

    int scoreOfParentheses(string s) {
        int score = 0;
        while (i < s.size()) {
            char first = s[i];
            i++;
            if (first == '(') {
                if (s[i] == ')') {
                    score++;
                    i++;
                } else {
                    score += 2 * scoreOfParentheses(s);
                }
            } else if (first == ')') {
                return score;
            }
        }
        return score;
    }
};

class Solution {
public:
    bool buddyStrings(string s, string goal) {
        int n = s.length();

        if(goal.length() != n){
            return false;
        }

        if(s == goal){
            set<char> temp(s.begin(), s.end());
            return temp.size() < goal.size(); // Swapping same characters
        }

        int i = 0;
        int j = n - 1;

        while(i < j && s[i] == goal[i]){
            i++;
        }

        while(j >= 0 && s[j] == goal[j]){
            j--;
        }

        if(i < j){
            swap(s[i], s[j]);
        }

        return s == goal;
    }
};

class Solution {
public:

    vector<vector<int>> directions{{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    int shortestPathAllKeys(vector<string>& grid) {
        int m = grid.size();
        int n = grid[0].size();

        queue<vector<int>> que; //{x, y, steps, current_key_status_decimal}
        int count = 0;
        for(int i = 0; i<m; i++) {

            for(int j = 0; j<n; j++) {

                if(grid[i][j] == '@') {
                    que.push({i, j, 0, 0});
                } else if(grid[i][j] >= 'a' && grid[i][j] <= 'f') {
                    count++;
                }

            }

        }

        /*
            If we have 3 keys - '111'  - Decimal value = 8 = 2^3 - 1
            If we have 4 keys - '1111' - Decimal value = 15 = 2^4 - 1
        */

        int final_key_status_decimal = pow(2, count) - 1;


        int visited[m][n][final_key_status_decimal+1];
        memset(visited, 0, sizeof(visited));

        while(!que.empty()) {

            auto temp = que.front();
            que.pop();

            int i                            = temp[0];
            int j                            = temp[1];
            int steps                        = temp[2];
            int current_key_status_decimal   = temp[3];

            if(current_key_status_decimal == final_key_status_decimal) {
                return steps;
            }

            for(vector<int> & dir : directions) {

                int new_i = i + dir[0];
                int new_j = j + dir[1];

                if(new_i >= 0 && new_i < m && new_j >= 0 && new_j < n && grid[new_i][new_j] != '#') {
                    char ch = grid[new_i][new_j];

                    if(grid[new_i][new_j] >= 'A' && grid[new_i][new_j] <= 'F') { //Lock

                        if(visited[new_i][new_j][current_key_status_decimal] == 0 && 
                          ((current_key_status_decimal >> (ch-'A')) & 1) == 1) { //Already have that key then we unlock
                            visited[new_i][new_j][current_key_status_decimal] = 1;
                            que.push({new_i, new_j, steps+1, current_key_status_decimal});
                        }

                    } else if(grid[new_i][new_j] >= 'a' && grid[new_i][new_j] <= 'f') { //Key

                        int newKey_status_decimal = current_key_status_decimal | (1 << (ch - 'a'));

                        if(visited[new_i][new_j][newKey_status_decimal] == 0) {
                            visited[new_i][new_j][newKey_status_decimal] = 1;
                            que.push({new_i, new_j, steps+1, newKey_status_decimal});
                        }

                    } else {
                        if(visited[new_i][new_j][current_key_status_decimal] == 0) {
                            visited[new_i][new_j][current_key_status_decimal] = 1;
                            que.push({new_i, new_j, steps+1, current_key_status_decimal});
                        }
                    }

                }

            }

        }

        return -1;
    }
};

class Solution {
public:
    // Function to compute the transpose of a given matrix
    vector<vector<int>> transpose(vector<vector<int>>& matrix) {
        int row = matrix.size();    // Get the number of rows in the original matrix
        int col = matrix[0].size(); // Get the number of columns in the original matrix

        // Create a new matrix to store the transposed elements
        vector<vector<int>> ans(col, vector<int>(row)); // New matrix with dimensions col x row

        // Traverse through the original matrix
        for (int i = 0; i < row; i++) {
            for (int j = 0; j < col; j++) {
                // Assign transposed elements to the new matrix
                ans[j][i] = matrix[i][j]; // Transpose by swapping row and column indices
            }
        }
        return ans; // Return the transposed matrix
    }
};

class Solution:
    def advantageCount(self, A, B):
        n = len(A)
        B = sorted([(num, i) for i, num in enumerate(B)])[::-1]
        A = sorted(A)[::-1]
        ans = [-1]*n

        beg, end = 0, n - 1

        for num, ind in B:
            if A[beg] > num:
                ans[ind] = A[beg]
                beg += 1
            else:
                ans[ind] = A[end]
                end -= 1

        return ans

class Solution {
public:
    int lenLongestFibSubseq(vector<int>& arr) 
    {
        int n=arr.size();
        int maxi=INT_MIN;
        int count=0;
        unordered_set<int> st;
        for(auto i:arr)
        {
            st.insert(i);
        }
        for(int i=0;i<n;i++)
        {
            for(int j=i+1;j<n;j++)
            {
                int var=arr[i];
                int var2=arr[j];
                int sum=var+var2;
                count=2;
                while(st.find(sum)!=st.end())
                {
                    count++;
                    var=var2;
                    var2=sum;
                    sum=var+var2;
                }
                maxi=max(maxi,count);
            }
        }
        if(maxi>2)
        return maxi;
        else
        return 0;

    }
};

class Solution {
    public int lenLongestFibSubseq(int[] A) {
        int n = A.length;
        int[][] dp = new int[n][n];
        Map<Integer, Integer> pos = new HashMap<>();
        for (int i = 0; i < n; i++) {
            pos.put(A[i], i);
            for (int j = i; j < n; j++) {
                dp[i][j] = 2;
            }
        }
        for (int j = 2; j < n; j++) {
            for (int i = j - 1; i > 0; i--) {
                int prev = A[j] - A[i];
                if (prev >= A[i]) {
                    break;
                }
                if (!pos.containsKey(prev)) {
                    continue;
                }
                dp[i][j] = dp[pos.get(prev)][i] + 1;
            }
        }
        int result = 0;
        for (int j = 2; j < n; j++) {
            for (int i = 1; i < n - 1; i++) {
                if (dp[i][j] > 2) {
                    result = Math.max(result, dp[i][j]);
                }
            }
        }
        return result;
    }
}

class Solution {
public:
    int robotSim(vector<int>& commands, vector<vector<int>>& obstacles) {
        vector<int> dx={0,1,0,-1};
        vector<int> dy={1,0,-1,0};
        int x=0,y=0,idx=0;
        set<pair<int,int>> st;
        for(auto obstacle:obstacles){
            st.insert({obstacle[0],obstacle[1]});
        }
        int res=0;
        for(auto command:commands){
            if(command==-2){
                idx=(idx+3)%4;
            }
            else if(command==-1){
                idx=(idx+1)%4;
            }
            else{
                for(int i=0;i<command;i++){
                    int newX=x+dx[idx];
                    int newY=y+dy[idx];
                    if(st.find({newX,newY})==st.end()){
                        x=newX;
                        y=newY;
                        res=max(res,x*x+y*y);
                    }
                }
            }
        }
        return res;
    }
};

class Solution {
    public int nthMagicalNumber(int n, int a, int b) {

        long A = a, B = b;
        long mod = (long)(Math.pow(10,9)+7);


        long left = Math.min(a,b), right = (long)n*Math.min(a,b);

		// Finding GCD
        while (B > 0) {
            long tmp = A;
            A = B;
            B = tmp % B;
        }

        long lcm = (a*b)/A;     //(n1*n2)/GCD

        while (left < right) {
            long m = left+(right-left)/2;

            if ((m / a) + (m / b) - (m / lcm) < n) left = m + 1;   

            else right = m;
        }
        return (int)(left % mod);
    }
}

class Solution {
public:
    string decodeAtIndex(string s, int k) {
        long long decodedLength = 0;
        for(auto c : s){
            if(isdigit(c)){
                decodedLength = decodedLength * ( c - '0');
            }else{
                decodedLength++;
            }
        }

        for(int i = s.length() - 1; i >= 0; i--){
            char curr = s[i];
            if(isdigit(curr)){
                decodedLength = decodedLength/(curr - '0');
                k = k % decodedLength;
            }else{
                if( k == 0 || decodedLength == k){
                    return string(1,curr);
                }
                decodedLength--;
            }
        }

        return "";
    }
};

class Solution:
    def reachableNodes(self, edges, M, N):
        G = defaultdict(set)
        dist = [float('inf')] * N
        dist[0] = 0

        for i, j, w in edges:
            G[i].add((j, w + 1))
            G[j].add((i, w + 1))

        heap = [(0, 0)]

        while heap:
            min_dist, idx = heappop(heap)
            for neibh, weight in G[idx]:
                cand = min_dist + weight
                if cand < dist[neibh]:
                    dist[neibh] = cand
                    heappush(heap, (cand, neibh)) 

        ans = sum(dist[i] <= M for i in range(N))

        for i, j, w in edges:
            w1, w2 = M - dist[i], M - dist[j]
            ans += (max(0, w1) + max(0, w2))
            if w1 >= 0 and w2 >= 0: ans -= max(w1 + w2 - w, 0)

        return ans

class Solution {
public:
    int reachableNodes(vector<vector<int>>& edges, int maxMoves, int n) {
        vector<pair<int, int>>adj[n];
        int cnt=0;
        for(int i=0; i<edges.size(); i++){
            adj[edges[i][0]].push_back({edges[i][1], edges[i][2]});
            adj[edges[i][1]].push_back({edges[i][0], edges[i][2]});
        }
        vector<int>v(n, 1e9);
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>>q;
        q.push({0, 0});
        v[0]=0;
        while(!q.empty()){
            int pos=q.top().second, wt=q.top().first;
            q.pop();
            for(auto it: adj[pos]){
                if(v[it.first]>wt+it.second+1){
                    v[it.first]=it.second+wt+1;
                    q.push({v[it.first], it.first});
                }
            }
        }
        for(int i=0; i<n; i++){
            if(maxMoves>=v[i]){
                cnt++;
            }
        }
        for(auto it: edges){
            int l1=max(0, maxMoves-v[it[0]]), l2=max(0, maxMoves-v[it[1]]);
            cnt+=min(it[2], l1+l2);
        }
        return cnt;
    }
};

class StockSpanner {
public:
    // Pair will hold two value: first->price and second->index 
    stack<pair<int,int>> st;
    StockSpanner() {
        st.push(make_pair(1e5+10,0));
    }

    int next(int price) {
        int curridx=st.top().second+1;
        while(st.top().first<=price)
        {
            st.pop();
        }
        int ans=curridx-st.top().second;
        st.push(make_pair(price,curridx));
        return ans;
    }
};

class Solution {
    public int[] sortArrayByParity(int[] nums) {
        int sz = nums.length, left = 0, right = sz-1;
        while(left < right){
            while(left < right && nums[left] % 2 == 0){
                left++;
            }
            while(right > left && nums[right] % 2 != 0){
                right--;
            }
            if(left < right){
                swap(nums, left, right);
            }
        }
        return nums;
    }
    private void swap(int nums[], int left, int right){
        int temp = nums[left];
        nums[left] = nums[right];
        nums[right] = temp;
    }
}

class Solution {
public:
    int smallestRangeI(vector<int>& nums, int k) {
        int n = nums.size();
        int maxx = nums[0], minn = nums[0];

        for (int i=0; i<n; i++) {
            maxx = max(maxx, nums[i]);
            minn = min(minn, nums[i]);
        }

        int diff = maxx - minn;

        if (diff - k <= k) return 0;
        return diff-k-k;
    }
};

class Solution {
public:
    int smallestRangeII(vector<int>& nums, int k) {
        vector<pair<int, int>> values;
        for (int i = 0;i < nums.size();i++) { // put all possible value-index pairs into the vector
            values.push_back({nums[i]+k, i});
            values.push_back({nums[i]-k, i});
        }
        sort(values.begin(), values.end()); // sort the whole thing
        int left = 0, right = 0; // window bounds
        unordered_map<int, int> visited; // track the count of each index
        int min_diff = INT_MAX;
        while (right < values.size()) {
            while (right < values.size() && visited.size() < nums.size()) { // slide the right side to include all indices
                auto [num, idx] = values[right++];
                if (!visited.count(idx))
                    visited[idx] = 0;
                visited[idx]++; // increase the count
            }
            while (left < right && visited.size() == nums.size()) { // slide the left side to make the window minimized
                auto [num, idx] = values[left++];
                if (visited[idx] == 1) visited.erase(idx); // minimized
                else visited[idx]--; // decrease the count
            }
            min_diff = min(min_diff, values[right-1].first - values[left-1].first); // compute the difference
        }
        return min_diff;
    }
};

class Solution {
