class Solution {
public:
    int N;
    int GOAL;
    int K;
    long t[101][101];
    const int MOD = 1e9+7;

    long solve(int count_song, int count_unique) {
        if(count_song == GOAL) {
            if(count_unique == N)
                return 1;

            return 0;
        }

        if(t[count_song][count_unique] != -1)
            return t[count_song][count_unique];

        long result = 0;

        //Option-1 (Play a unique song)
        if(count_unique < N)
            result += (N-count_unique) * solve(count_song+1, count_unique+1);

        //Option-2 (Replay a song)
        if(count_unique > K)
            result += (count_unique - K) * solve(count_song+1, count_unique);


        return t[count_song][count_unique] = result % MOD;

    }

    int numMusicPlaylists(int n, int goal, int k) {
        N    = n;
        GOAL = goal;
        K    = k;
        memset(t, -1, sizeof(t));
        return solve(0, 0); 
    }
};

class Solution {
    public int[] sortArrayByParityII(int[] A) {
        int i = 0, j = 1, n = A.length;
        while (i < n && j < n) {
            while (i < n && A[i] % 2 == 0) {
                i += 2;
            }
            while (j < n && A[j] % 2 == 1) {
                j += 2;
            }
            if (i < n && j < n) {
                swap(A, i, j);
            }
        }
        return A;
    }
    private void swap(int[] A, int i, int j) {
        int temp = A[i];
        A[i] = A[j];
        A[j] = temp;
    }
}

let MOD = 10 ** 9 + 7;
function lower_bound_eg(arr, target, L = 0, R = arr.length) {
    while (L < R) {
        let mid = ~~(L / 2 + R / 2);
        arr[mid] < target ? (L = mid + 1) : (R = mid);
    }
    return L;
}
function upper_bound_g(arr, target, L = 0, R = arr.length) {
    while (L < R) {
        let mid = ~~(L / 2 + R / 2);
        arr[mid] <= target ? (L = mid + 1) : (R = mid);
    }
    return L;
}
function equal_range_eg_g(arr, target, L = 0, R = arr.length) {
    const LB = lower_bound_eg(arr, target, L, R);
    const UB = upper_bound_g(arr, target, L, R);
    return [LB, UB];
}
var threeSumMulti = function (a, t) {
    let n = a.length;

    a.sort((a, b) => a - b);

    // i + L + R = t
    let cc = 0;
    for (let i = 0; i < n; i++) {
        for (let L = i + 1; L < n; L++) {
            let search = t - (a[i] + a[L]);

            let [R, R2] = equal_range_eg_g(a, search, L + 1, n);
            if (R !== -Infinity) {
                cc += R2 - R;
                cc = cc % MOD;
            }
        }
    }
    return cc;
};

