class Solution {
public:
    int numSubarraysWithSum(vector<int>& nums, int goal) {
        int n = nums.size(), i = 0, count_1 = 0, ans = 0;
        unordered_map<int,int> mp;
        while(i < n){
            count_1 += nums[i];
            if(count_1 == goal)
                ans++;
            if(mp.find(count_1 - goal) != mp.end())
                ans += mp[count_1 - goal];
            mp[count_1]++;
            i++;
        }
        return ans;
    }
};

let numSubarraysWithSum = function (a, t) {
    let n = a.length;

    const ps = new Array(n).fill(0);
    ps[0] = a[0];
    for (let i = 1; i < n; i += 1) {
        ps[i] = ps[i - 1] + a[i];
    }

    let cc = 0;
    for (let i = -1; i < n; i += 1) {
        let psi = i === -1 ? 0 : ps[i];
        for (let j = i + 1; j < n; j += 1) {
            const s = ps[j] - psi;
            if (s > t) {
                break;
            }
            if (s === t) {
                cc += 1;
            }
        }
    }
    return cc;
};

var numSubarraysWithSum = function (a, t) {
    let i = 0,
        sum = 0,
        cc = 0;
    for (let j = 0; j < a.length; j++) {
        sum += a[j];
        if (sum > t) {
            for (; sum > t && i < j; i++) {
                sum -= a[i];
            }
        }
        if (sum === t) {
            let i2 = i;
            for (; i2 < j && sum + a[i2] === t; i2++) {}
            cc += i2 - i + 1;
        }
    }
    return cc;
};

class Solution {


    // Top down


    // static int helper(int arr[][],int i, int j){
    //     if(j>=m || j<0) return Integer.MAX_VALUE;
    //     if(i==n-1) return arr[i][j];

    //     if(dp[i][j]!=-1) return dp[i][j];

    //     int a = helper(arr,i+1,j);
    //     int b = helper(arr,i+1,j-1);
    //     int c = helper(arr,i+1,j+1);

    //     return dp[i][j] = arr[i][j] + Math.min(a,Math.min(b,c));
    // }


    // Bottom up

    static int helper2(int arr[][]){
        int n = arr.length;
        int m = arr[0].length;

        int dp[][] = new int[n][m];

        for(int j=0; j<m; j++){
            dp[n-1][j] = arr[n-1][j];
        }

        for(int i=n-2; i>=0; i--){
            for(int j=0; j<m; j++){
                if(j==0) dp[i][j] = arr[i][j]+Math.min(dp[i+1][j],dp[i+1][j+1]);
                else if(j==m-1) dp[i][j] = arr[i][j]+Math.min(dp[i+1][j],dp[i+1][j-1]);
                else{
                    dp[i][j] = arr[i][j]+Math.min(dp[i+1][j],Math.min(dp[i+1][j-1],dp[i+1][j+1]));
                }
            }
        }

        int ans = Integer.MAX_VALUE;

        for(int j=0; j<m; j++){
            ans = Math.min(ans,dp[0][j]);
        }
        return ans;
    }
    public int minFallingPathSum(int[][] arr) {

        return helper2(arr);
    }
}

class Solution {
public:
    vector<int> beautifulArray(int n) {
        if (n==1) return {1};

        vector<int> arr = beautifulArray(n-1);

        vector<int> res;
        for (auto i: arr)
            if (2*i - 1 <= n) 
                res.push_back(2*i-1);

        for (auto i: arr)
            if (2*i <= n) 
                res.push_back(2*i);

        return res;
    }
};

class Solution {
public:
    vector<int> beautifulArray(int n) {
        vector<int> ans ;
        ans.push_back(1) ;
        while(ans.size() < n)
        {
            vector<int> temp ;
            for(auto i:ans)
            {
                if(i*2 - 1 <= n)
                {
                    temp.push_back(i*2 - 1) ;
                }
            }
            for(auto i:ans)
            {
                if(i*2 <= n)
                {
                    temp.push_back(i*2) ;
                }
            }
            ans = temp ;
        }
        return ans ;
    }
};

class RecentCounter {
