/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int d1,d2;
    TreeNode* p1,*p2;

    void solve(TreeNode* root,int depth,TreeNode* parent,int x,int y){
        if(!root)
        return ;

        depth+=1;
        parent=root;

        if(root->left){
            if(root->left->val==x){
            d1=depth;
            p1=root;
            return;
            } else if(root->left->val==y){
                d2=depth;
                p2=root;
            } else
                solve(root->left,depth,parent,x,y);


        }

        if(root->right){
            if(root->right->val==y){
            d2=depth;
            p2=root;
            return;
            } else if(root->right->val==x){
            d1=depth;
            p1=root;
            return;
            } else
                solve(root->right,depth,parent,x,y);


        }        
    }

    bool isCousins(TreeNode* root, int x, int y) {
        solve(root,0,NULL,x,y);
        if(d1==d2 and p1!=p2)
        return 1;

        return 0;

    }
};

class Solution {
public:
    int largestSumAfterKNegations(vector<int>& nums, int k) {
        int sum = accumulate(nums.begin(), nums.end(), 0);
        // O(n), min heap
        priority_queue<int, vector<int>, greater<int>> pq(nums.begin(), nums.end());    

        // while smallest numbers are negative
        while (k > 0 && pq.top() < 0) {
            int smallest = pq.top();
            sum -= 2 * smallest;
            pq.pop();
            if (-smallest > -pq.top())
                pq.push(-smallest);
            k--;
        }
        // when all negatives are done, negate the 0 or smallest positive number multiple times
        if (k % 2 == 1) sum -= 2*pq.top(); 

        return sum;
    }
};

