class Solution {
    public int smallestRepunitDivByK(int k) {
        int prev = 0;

        if(k%2==0 || k%5==0) return -1;

        for(int i=1; i<=k; i++){
            prev = (prev*10+1)%k;
            if(prev == 0) return i;
        }
        return -1;
    }
}

class Solution {
    public int smallestRepunitDivByK(int k) {
        // if (k % 2 == 0 || k % 5 == 0) return -1;  // this trick may save a little time
        boolean[] hit = new boolean[k];
        int n = 0, ans = 0;
        while (true) { // at most k times, because 0 <= remainder < k
            ++ ans;
            n = (n * 10 + 1) % k; // we only focus on whether to divide, so we only need to keep the remainder.
            if (n == 0) return ans; // can be divisible
            if (hit[n]) return -1; // the remainder of the division repeats, so it starts to loop that means it cannot be divisible.
            hit[n] = true;
        }
    }
}

class Solution {
public:
    int sumRootToLeaf(TreeNode* node, int pre=0) { // pre is sum of path from root to parent of node
        if (!node->left and !node->right) // node is a leaf node, return the sum of path from root to node
            // return pre << 1 | node->val; // also work
			return pre * 2 + node->val;
        int ans = 0;
        if (node->left) // node.left is not None, recursively find the sum node to leaf
            // ans += sumRootToLeaf(node->left, pre << 1 | node->val); // also work
			ans += sumRootToLeaf(node->left, pre * 2 + node->val);
        if (node->right) // node.right is not None, recursively find the sum node to leaf
            // ans += sumRootToLeaf(node->right, pre << 1 | node->val); // also work
			ans += sumRootToLeaf(node->right, pre * 2 + node->val);
        return ans;
    }
};

class Solution {
public:
    vector<bool> camelMatch(vector<string>& queries, string pattern) {
        vector<bool> ans;
        for (int i = 0; i < queries.size(); i++) {
            int j = 0;
            for (int k = 0; k < queries[i].size(); k++) {
                if (j < pattern.size() && queries[i][k] == pattern[j]) {
                    j++;
                } else if (queries[i][k] >= 'A' && queries[i][k] <= 'Z') {
                    ans.push_back(false);
                    break;
                }
                if (k == queries[i].size() - 1) {
                    if (j == pattern.size()) {
                        ans.push_back(true);
                    } else {
                        ans.push_back(false);
                    }
                }
            }
        }
        return ans;
    }
};

class Solution {
    static final int MIN_DIFF = -500;
    static final int DIFF_RANGE = 1001;

    public int longestArithSeqLength(int[] nums) {
        int n = nums.length;
        if (n == 2)  return 2;
        int maxSeqLen = 0;
        int[][] dp = new int[n][DIFF_RANGE];
        for (int right = 0; right < nums.length; ++right) {
            for (int left = 0; left < right; ++left) {
                int diff = nums[left] - nums[right] - MIN_DIFF;
                maxSeqLen = Math.max(maxSeqLen, (dp[right][diff] = dp[left][diff] + 1));
            }
        }
        return maxSeqLen + 1;
    }
}

class StreamChecker:
    def rollingHash(self, Hash, p_pow, c, mod = 1e9+7):
        return ((Hash + ord(c) * p_pow) % mod, (p_pow * 31) % mod)

    def __init__(self, words):
        self.suffix_hash, self.word_hash, self.query_stream = set(), set(), deque()
        for w in words:
            Hash, p_pow = 0, 1
            for c in w[::-1]:
                Hash, p_pow = self.rollingHash(Hash, p_pow, c)
                self.suffix_hash.add(Hash)
            self.word_hash.add(Hash)

    def query(self, c):
        self.query_stream.appendleft(c)
        Hash, p_pow = 0, 1
        for c in self.query_stream:
            Hash, p_pow = self.rollingHash(Hash, p_pow, c)
            if Hash not in self.suffix_hash: return False
            elif Hash in self.word_hash: return True

class Node{
    Node *arr[26];
    bool flag = false;
public:

    bool contains(char ch){ return arr[ch-'a'] != NULL; }

    void put(char ch, Node *newNode){ arr[ch - 'a'] = newNode;}

    Node *getNext(char ch){return arr[ch-'a'];}

    bool getFlag(){ return flag;}

    void setFlag(){ flag = true;} 

};
class StreamChecker {
public:
    string streamString = "";
    Node *root;

    void insert(string s){
        Node *temp = root;
        for(int i=s.size()-1;i>=0;i--){  //insert in reverse order
            if(!temp->contains(s[i])) temp->put(s[i], new Node());
            temp = temp->getNext(s[i]);
        }
        temp->setFlag();//set flag if you reach end of the string
    }

    StreamChecker(vector<string>& words) {
        root = new Node();
        for(auto word : words) insert(word);

    }

    bool query(char letter) {
        streamString += letter;
        Node *temp = root;
        //search from the end of the string
        for(int i=streamString.size()-1;i>=0&&temp;i--){
            if(!temp && !temp->contains(streamString[i])) return false;

            temp = temp->getNext(streamString[i]);
            if(temp && temp->getFlag()) return true; //return true if you've reached the end
        }
        return false;    
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution
{
public:
	void solve(TreeNode *root, int &x)
	{
		if (root == NULL)
			return;
		solve(root->right, x);
		if (root->val >= 0)
			root->val += x;
		root->val = -root->val;
		x = abs(root->val);
		if (root->left)
		{
			solve(root->left, x);
			if (root->val > 0)
				x += root->val;
		}
	}
	void solve1(TreeNode *root)
	{
		if (!root)
			return;
		root->val = -root->val;
		solve1(root->left);
		solve1(root->right);
	}
	TreeNode *bstToGst(TreeNode *root)
	{
		int x = 0;
		solve(root, x);
		solve1(root);
		return root;
	}
};

class Solution {
public:
int solve(vector<int>& values,int i ,int j ,vector<vector<int>>&dp)
{
    // BASE CASE CHECK IF THE FIRST ELEMENT AND LAST ELEMENT ARE TOGETHER OR NOT 
    if(i+1==j)
    {
        return 0;
    }
    if(dp[i][j]!=-1)
       return dp[i][j];
    int ans = INT_MAX;
    for(int k=i+1;k<j;k++)
    {
        ans = min(ans , values[i]*values[j]*values[k]+solve(values,i,k,dp)+solve(values, k, j , dp));
    }
    dp[i][j]=ans;
    return dp[i][j];

}
    int minScoreTriangulation(vector<int>& values)
    {
        int n = values.size();
        vector<vector<int>>dp(n,vector<int>(n,-1));
        return solve(values,0,n-1,dp); 
    }
};

class Solution {
public:
    vector<int>  ans;
    void BFS(vector<int> adj[],vector<int> &vis,vector<vector<int>> &clrcode,int n,int src)
    {
         queue<int> q;
         q.push(src);
         vis[src] = 1;
         while(!q.empty())
         {
             int node = q.front();
             q.pop();
             int clr = 0;
             for(;clr<4;clr++)
             if(clrcode[node][clr]==0) break;
             clrcode[node][clr] = 1;
             ans[node-1] = clr+1;
             for(auto x : adj[node])
             {
                if(vis[x]==0)
                {
                  q.push(x);
                  vis[x] = 1;
                }
                clrcode[x][clr] = 1;
             }
         }
    }
    vector<int> gardenNoAdj(int n, vector<vector<int>>& paths) {
        vector<int> adj[n+1];
        ans = vector<int>(n,0);
        for(int i = 0;i<paths.size();i++)
        {
        adj[paths[i][0]].push_back(paths[i][1]);
        adj[paths[i][1]].push_back(paths[i][0]);
        }
        vector<vector<int>> clrcode(n+1,vector<int>(4,0));
        vector<int> vis(n+1,0);
        for(int i = 1;i<=n;i++)
        if(vis[i]==0) BFS(adj,vis,clrcode,n,i);
        return ans;
    }
};

class Solution {
public:
    int solve(int i,vector<int> &v,int &k,int &n,vector<int> &dp)
    {
        if(i==n)return 0;
        int mx = 0,ans = 0,len = 0;
        if(dp[i] != -1)return dp[i];
        for(int j = i; j < min(n,(i+k)); j++)
        {
            len++;
            mx = max(mx,v[j]);
            int sum = mx*len + solve(j+1,v,k,n,dp);
            ans = max(ans,sum);
        }
        return dp[i] = ans;
    }
    int maxSumAfterPartitioning(vector<int>& arr, int &k)
     {
        int n = arr.size();
        vector<int> v(n,-1);
        return solve(0,arr,k,n,v);
    }
};

class Solution {
public:
    int longestStrChain(vector<string>& words) {
        sort(words.begin(), words.end(), [](const string& str1, const string& str2)->bool{
            return str1.size() < str2.size();
        });
        unordered_map<string, int> chainLen;
        int maxLen = 0;
        for (string & word : words) {
            for (int indx = 0; indx < word.size(); indx++) {
                string pred = word.substr(0, indx) + word.substr(indx + 1);
                chainLen[word] = max(chainLen[word], chainLen.find(pred) == chainLen.end() ? 1 : chainLen[pred] + 1);
            }
            maxLen = max(maxLen, chainLen[word]);
        }
        return maxLen;
    }
};

class Solution {
    public int lastStoneWeightII(int[] arr) {
        HashSet<Integer> set = new HashSet<>();
        set.add(0);
        for (int a : arr) {
            HashSet<Integer> set2 = new HashSet<>();
            for (int x : set) {
                set2.add(x - a);
                set2.add(x + a);
            }
            set = set2;
        }
        int min = Integer.MAX_VALUE;
        for (int x : set)
            min = Math.min(min, Math.abs(x));
        return min;
    }
}

class Solution {
public:
    vector<int> prevPermOpt1(vector<int>& arr) {

         int temp=INT_MIN;
         int idx=-1;

         for(int i=arr.size()-2;i>=0;i--)
         {
            int num=arr[i];

            for(int j=i+1;j<arr.size();j++)
            {
                 int currnum = arr[j];

                 if(currnum!=num and currnum>temp and currnum<num)
                 {
                     temp = currnum;
                     idx = j;
                 }
            }
             if(idx!=-1)  //found something smaller
             {
                 int x = arr[i];
                 arr[i] = arr[idx];
                 arr[idx] = x;

                 //first part
                 //0 to i
                 // sort(arr.begin()+(i+1),arr.end());
                 return arr;
             }
         }
         sort(arr.begin(),arr.end());
         return arr;
    }
};

var numSubmatrixSumTarget = function(M, T) {
    let xlen = M[0].length, ylen = M.length,
        ans = 0, res = new Map(), csum
    for (let i = 0, r = M[0]; i < ylen; r = M[++i]) 
        for (let j = 1; j < xlen; j++)
            r[j] += r[j-1]
    for (let j = 0; j < xlen; j++)
        for (let k = j; k < xlen; k++) {
            res.clear(), res.set(0,1), csum = 0
            for (let i = 0; i < ylen; i++) {
                csum += M[i][k] - (j ? M[i][j-1] : 0)
                ans += (res.get(csum - T) || 0)
                res.set(csum, (res.get(csum) || 0) + 1)
            }
        }
    return ans
};

class Solution {
public:
    int result=0,target;
    unordered_map<int,int> map;
    void get_result(vector<int>& nums)                          //Get number of subarrays that sum to target.
    {
        int sum=0;
        map.clear();
        map[0]++;
        for(int &i:nums)
        {
            sum+=i;
            result+=map[sum-target];       //get number of subarrays who's sum equals target and end at i and add result to global result.
            map[sum]++;                    //Add the occurence of running sum to map.
        }
    }
    int numSubmatrixSumTarget(vector<vector<int>>& matrix, int target) 
    {
        this->target=target;
        vector<int> row(matrix[0].size());
        for(int i=0;i<matrix.size();i++)                    //Convert 2D array to 1D by row.
        {
            fill(row.begin(),row.end(),0);                  //Clear vector to start the row with i as starting row.
            for(int j=i;j<matrix.size();j++)
            {
                for(int x=0;x<matrix[0].size();x++)         //Add next row
                    row[x]+=matrix[j][x];
                get_result(row);
            }
        }
        return result;
    }
};

class Solution {
    public String[] findOcurrences(String text, String first, String second) {
        String[] split = text.split(" ");
        List<String> list = new ArrayList<>();
        for (int i = 0; i < split.length - 2; i++) {
            if (split[i].equals(first) && split[i + 1].equals(second)) list.add(split[i + 2]);
        }
        String[] arr = new String[list.size()];
        for (int i = 0; i < arr.length; i++) {
            arr[i] = list.get(i);
        }
        return arr;
    }
}

class Solution {
public:

    void solve(string tiles, int& count, int i){
        count++;
        for(int ind=i; ind<tiles.length(); ind++){
            if(ind != i && tiles[ind] == tiles[i]) continue;
            swap(tiles[ind], tiles[i]);
            solve(tiles, count, i+1);
        }
    }


    int numTilePossibilities(string tiles) {
        sort(tiles.begin(), tiles.end());
        int i = 0, count = -1;
        solve(tiles, count, i);
        return count;
    }
};

class Solution {
    public boolean carPooling(int[][] trips, int capacity) {
        int lengthOfTrip[] = new int[1001];

        for(int trip[] : trips){
            lengthOfTrip[trip[1]] += trip[0]; // Increment when passenger is on board
            lengthOfTrip[trip[2]] -= trip[0]; // decrement when they depart
        }

        for(int passenger : lengthOfTrip){
            capacity -= passenger;
            if(capacity < 0) return false;
        }
        return true;
    }
}

class Solution {
    public boolean carPooling(int[][] trips, int capacity) {
        int in_car = 0;
        int[] increase = new int[1001];
        for (int i = 0; i < trips.length; i ++) { // find out the number of the **net increase** passengers for each stop
            increase[trips[i][1]] += trips[i][0];
            increase[trips[i][2]] -= trips[i][0];
        }
        for (int i = 0; i <= 1000; i ++) { // from start to end, for each stop we calculate the number of passengers in the car.
            in_car += increase[i];
            if (in_car > capacity) return false; // once the number of passengers in the car exceeds the capacity
        }
        return true;
    }
}

class Solution {
    public int findInMountainArray(int B, MountainArray A) {
        int n = A.length();
        int maxPosition = -1;
        int left = 1;
        int right = n-2;
        int mid;
        while(left<right){
            mid = left + (right-left)/2;
            if(A.get(mid)<A.get(mid+1)){
                left = mid +1;
            }else{
                right = mid;
            }

        }
        maxPosition = left;
        left = 0;right = maxPosition;
        int me;
        while (left<=right){
            mid = left +(right-left)/2;
            me = A.get(mid);
            if(me==B) return mid;
            if(me>B) right = mid-1;
            else left = mid+1;
        }
        left = maxPosition; right = n-1;
        while (left<=right){

            mid = left +(right-left)/2;
            me = A.get(mid);
            if(me==B) return mid;
            if(me<B) right = mid-1;
            else left = mid+1;
        }
        return -1;
    }
}

class Pair{
    int first;
    int second;
    Pair(int first,int second){
        this.first=first;
        this.second=second;
    }
}

class Solution {
    public int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {

        ArrayList<ArrayList<Integer>>adjRed=new ArrayList<>();
        ArrayList<ArrayList<Integer>>adjBlue=new ArrayList<>();
        for(int i=0;i<n;i++){
            adjRed.add(new ArrayList<>());
            adjBlue.add(new ArrayList<>());
        }

        for(int i=0;i<redEdges.length;i++){
            adjRed.get(redEdges[i][0]).add(redEdges[i][1]);
        }
        for(int i=0;i<blueEdges.length;i++){
            adjBlue.get(blueEdges[i][0]).add(blueEdges[i][1]);
        }

        int visit[][]=new int[n][2];
        int ans[]=new int[n];
        Arrays.fill(ans,-1);

        Queue<Pair>q=new LinkedList<>();

        if(adjRed.get(0)==null){}
        q.add(new Pair(0,0));
        q.add(new Pair(0,1));

        visit[0][0]=0;//0 means red
        visit[0][1]=1;//1 means blue;

        ans[0]=0;
        int level=1;
        while(!q.isEmpty()){
            int len=q.size();
            while(len-->0){
                Pair pt=q.poll();
                int node=pt.first;
                int colorUsed=pt.second;
                if(colorUsed==0){
                    for(int e:adjRed.get(node)){
                        if(visit[e][0]==0){
                            q.add(new Pair(e,1));
                            visit[e][0]=1;
                            if(ans[e]==-1) ans[e]=level;
                        }
                    }
                }

                else{
                    for(int e:adjBlue.get(node)){
                        if(visit[e][1]==0){
                            q.add(new Pair(e,0));
                            visit[e][1]=1;
                            if(ans[e]==-1) ans[e]=level;
                        }
                    }
                }
            }
            level++;
        }

        return ans;
    }
}

class Solution {
public:
    int topDown(vector<int>& arr,map<pair<int,int>,int>& maxi,int left,int right,vector<vector<int>> &dp){
        if(left==right)
            return 0;
        if(dp[left][right]!=-1)
            return dp[left][right];

        int ans=INT_MAX;
        for(int i=left;i<right;i++){
            ans=min(ans,
            (maxi[{left,i}]*maxi[{i+1,right}]+
            topDown(arr,maxi,left,i,dp)
            +topDown(arr,maxi,i+1,right,dp)));
        }
        dp[left][right]=ans;
        return dp[left][right];
    }

    int mctFromLeafValues(vector<int>& arr) {
        map<pair<int,int>, int> maxi;
        for(int i=0;i<arr.size();i++){
            maxi[{i,i}]=arr[i];
             //this is basically 
                // pair<int,int> p;
                // p.first=i;
                // p.second=i;
                // maxi[p]=arr[i];
            for(int j=i+1;j<arr.size();j++){
                maxi[{i,j}]=max(arr[j],maxi[{i,j-1}]);
            }
        }
        int n=arr.size();
        vector<vector<int>> dp(n+1,vector<int>(n+1,-1));
        int ans=topDown(arr,maxi,0,n-1,dp);
        return ans;
      }
};

class Solution {
    public int tribonacci(int n) {
        int arr[] = new int[3+n];
        arr[0]=0;
        arr[1]=1;
        arr[2]=1;
        for(int i=3;i<=n;i++){
            arr[i]=arr[i-3]+arr[i-2]+arr[i-1];
        }
        return arr[n];
    }
}

class Solution {
  public:
    int dfs(int idx_start, int M, vector<int> &postfix, int n, vector<vector<int>> &cach) {
        if (idx_start >= n)
            return 0;

        int minnum = 1000001;
        if (cach[idx_start][M] >= 0) {
            return cach[idx_start][M];
        }
        for (int i = idx_start + 1; i <= idx_start + 2 * M && i <= n; i++) { 
            int tmp = dfs(i, std::max(i - idx_start, M), postfix, n, cach);
            if (minnum > tmp) {
                minnum = tmp;
            }
        }
        cach[idx_start][M] = postfix[idx_start] - minnum;
        return cach[idx_start][M];
    }
    int stoneGameII(vector<int> &piles) {
        int n = piles.size();
        vector<int> postfix(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            postfix[i] = postfix[i + 1] + piles[i];
        }
        vector<vector<int>> cach(n + 1, vector<int>(n + 1, -1));
        return dfs(0, 1, postfix, n, cach);
    }
};

