var dayOfYear = function(date) {
    const d = new Date(date)
    let sum = 0
    const days = [31,leap(d.getFullYear()),31,30,31,30,31,31,30,31,30,31]

    for(let month=0;month<d.getMonth();month++){
        sum += days[month]
    }

    return sum + d.getDate()
};

function leap(year) {
    if(year % 4 === 0){
        if(year % 100 === 0 && !(year % 400 === 0)){
            return 28
        }
        return 29
    }else{
        return 28
    }
}

class Solution {
public:
    int solve(int dice, int faces, int target, vector<vector<int>>& dp) {
        if (target < 0) {
            return 0;
        }
        if (dice == 0 && target != 0) {
            return 0;
        }
        if (dice != 0 && target == 0) {
            return 0;
        }
        if (dice == 0 && target == 0) {
            return 1;
        }
        if (dp[dice][target] != -1) {
            return dp[dice][target];
        }
        int ans = 0;
        for (int i = 1; i <= faces; i++) {
            ans = (ans + solve(dice - 1, faces, target - i, dp)) % 1000000007;
        }
        return dp[dice][target] = ans;
    }

    int numRollsToTarget(int n, int k, int target) {
        vector<vector<int>> dp(n + 1, vector<int>(target + 1, -1));
        return solve(n, k, target, dp);
    }
};

class Solution {
    public List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        if (words == null || puzzles == null) {
            throw new IllegalArgumentException("Input is invalid");
        }

        int puzzlesLen = puzzles.length;
        List<Integer> result = new ArrayList<>(puzzlesLen);
        if (puzzlesLen == 0 || words.length == 0) {
            for (int i = 0; i < puzzlesLen; i++) {
                result.add(0);
            }
            return result;
        }

        // This map will store the count of unique word masks
        HashMap<Integer, Integer> wordMaskCountMap = new HashMap<>();
        for (String word : words) {
            int wordMask = getMask(word, 0);
            wordMaskCountMap.put(wordMask, wordMaskCountMap.getOrDefault(wordMask, 0) + 1);
        }

        for (String puzzle : puzzles) {
            // We will only create subsets of last 6 characters because 1st character needs
            // to be present in all words
            int puzzleMask = getMask(puzzle, 1);
            int firstCharMask = 1 << (puzzle.charAt(0) - 'a');
            int subsetMask = puzzleMask;
            int count = wordMaskCountMap.getOrDefault(firstCharMask, 0);

            while (subsetMask != 0) {
                // Check if the (puzzle subset + first character) is present in the
                // wordMaskCountMap map and add its count.
                count += wordMaskCountMap.getOrDefault(subsetMask | firstCharMask, 0);

                // Get next subset of the puzzle.
                subsetMask = (subsetMask - 1) & puzzleMask;
            }

            result.add(count);
        }

        return result;
    }

    // In this function, we are generating a bit mask of each String.
    // Here we set 0th bit for 'a', 1st bit for 'b', and so on.
    // We will be setting upto 26 bits only.
    private static int getMask(String s, int start) {
        int mask = 0;
        for (int i = start; i < s.length(); i++) {
            mask |= 1 << (s.charAt(i) - 'a');
        }
        return mask;
    }
}

class Solution {
    private int JAN_FIRST = 1, MAX_FEB = 28, LEAP_FEB = 29;
    private int MAX_DAYS_MONTHS1 = 31, MIN_DAYS_MONTHS = 1, MAX_DAYS_MONTHS2 = 30;
    private int MAX_MONTH = 12, MIN_MONTH = 1;
    private int MAX_YEAR = 9999, MIN_YEAR = 1000, MID_YEAR = 2000;
    private int JAN = 1, FEB = 2, MAR = 3, APR = 4, MAY = 5, JUN = 6, JUL = 7, AUG = 8, SEP = 9, OCT = 10, NOV = 11, DEC = 12;

    public String dayOfTheWeek(int day, int month, int year) 
    {
        int dayD = dayInWeek(day, month,  year);

        if(dayD == 1)
        {
            return "Sunday";
        }
        if(dayD == 2)
        {
            return "Monday";
        }
        if(dayD == 3)
        {
            return "Tuesday";
        }
        if(dayD == 4)
        {
            return "Wednesday";
        }
        if(dayD == 5)
        {
            return "Thursday";
        }
        if(dayD == 6) 
        {
            return "Friday";
        }
         return "Saturday";
    }

    private int dayInWeek(int day, int month, int year) 
    {
        int D = day;
        int M;
        year = year;

       if(month < MAR)
       {
          year--;        
          M = month + DEC; 
       }
       else
       {
           M = month;
       }

        int Y = year % 100;
        int C = year / 100;        
        int Day = ((D + ((26*(M + 1)) / 10) + Y + (Y / 4) + (C / 4) - 2 * C) % 7);
        Day = Math.floorMod(Day, 7);

     return Day;

  }
}

class Solution {
public:
    int maximumSum(vector<int>& arr) {
        int oneDelete=0,noDelete=arr[0],ans=arr[0];
        for(int i=1;i<arr.size();i++){
            oneDelete=max(noDelete,oneDelete+arr[i]);
            noDelete=max(noDelete+arr[i],arr[i]);
            ans=max(ans,max(oneDelete,noDelete));
        }
        return ans;
    }
};

typedef long long ll;
#define MAX_ANS 2e9 

class Solution {
public:
    int nthUglyNumber(int n, int a, int b, int c) {
        int left = 0, right = MAX_ANS, result = 0;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (count(mid, a, b, c) >= n) { 
                result = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return result;
    }
    int count(ll num, ll a, ll b, ll c) {
        return (int)(num / a + num / b + num / c
            - num / lcm(a, b)
            - num / lcm(b, c)
            - num / lcm(a, c)
            + num / (lcm(a, lcm(b, c))));
    }
    ll gcd(ll a, ll b) {
        if (a == 0) return b;
        return gcd(b % a, a);
    }
    ll lcm(ll a, ll b) {
        return a * b / gcd(a, b);
    }
};

class Solution {
    public String removeDuplicates(String s, int k) {
        Stack<int []> Master = new Stack<>();

        for(char ch : s.toCharArray()){
            if(!Master.isEmpty() && Master.peek()[0] == ch){
                Master.peek()[1]++;
            }
            else Master.push(new int[]{ch, 1});
            if(Master.peek()[1] == k) Master.pop();
        }
        StringBuilder sb = new StringBuilder();
        while(!Master.isEmpty()){
            int top[] = Master.pop();
            while(top[1] --> 0)
                sb.append((char)top[0]);
        }
        return sb.reverse().toString();
    }
}

