class Solution {
public:
    const long long mod = 1e9+7;
    int countVowelPermutation(int n) {
        vector<vector<long long>> dp(2, vector<long long>(5, 0));
        dp[n & 1].assign(5, 1);

        for (int j = n - 1; j >= 1; j--) {
            dp[j&1][0] = (dp[(j+1)&1][1]) % mod;
            dp[j&1][1] = (dp[(j+1)&1][0] + dp[(j+1)&1][2]) % mod;
            dp[j&1][2] = (dp[(j+1)&1][0] + dp[(j+1)&1][1] + dp[(j+1)&1][3] + dp[(j+1)&1][4]) % mod;
            dp[j&1][3] = (dp[(j+1)&1][2] + dp[(j+1)&1][4]) % mod;
            dp[j&1][4] = (dp[(j+1)&1][0]) % mod;
        }

        long long ans = 0;
        for (int j = 0; j < 5; j++) {
            ans = (ans + dp[1][j]) % mod;
        }

        return ans;
    }
};

class Solution {
public:
    bool checkStraightLine(vector<vector<int>>& coordinates) {
        int ydiff = coordinates[1][1] - coordinates[0][1];
        int xdiff = coordinates[1][0] - coordinates[0][0];
        for(int i=2;i<coordinates.size();i++){
            if(ydiff*(coordinates[i][0] - coordinates[0][0])!=xdiff*(coordinates[i][1] - coordinates[0][1])) return false;
        }
        return true;
    }
};

public class Solution {
    private class TrieNode {
        HashMap<String, TrieNode> children = new HashMap<>();
        String word = null;
    }

    private List<String> parentFolders = new ArrayList<>();
    void getResults(TrieNode root) {
        for (Map.Entry<String, TrieNode> entry : root.children.entrySet()) {
            if (entry.getValue().word != null) {
                parentFolders.add(entry.getValue().word);
            } else {
                getResults(entry.getValue());
            }
        }
    }

    public List<String> removeSubfolders(String[] folders) {
        TrieNode root = new TrieNode();
        for (String folder : folders) {
            String[] parts = folder.substring(1).split("/");
            TrieNode curr = root;
            for (String part : parts) {
                if (!curr.children.containsKey(part)) {
                    curr.children.put(part, new TrieNode());
                }
                curr = curr.children.get(part);
            }
            curr.word = folder;
        }

        parentFolders.clear();
        getResults(root);
        return parentFolders;
    }
}

class Solution {
public:
    vector<int> circularPermutation(int n, int start) {
        vector<int>v;
        int p = (1<<n);
        for(int i=0; i<p; i++){
            v.push_back(i ^ (i/2));
        }
        vector<int>temp1;
        vector<int>ans;
        int flag = 0;
        for(auto num : v){
            if(num == start) flag = 1;
            if(flag == 1) ans.push_back(num);
            else temp1.push_back(num);
        }
        for(auto num:temp1) ans.push_back(num);
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> reconstructMatrix(int upper, int lower, vector<int>& colsum) {
        int m=colsum.size();
        vector<vector<int> > ans(2,vector<int>(m));
        int total=accumulate(colsum.begin(),colsum.end(),0);
        if(total!=upper+lower)
        {
            return {};
        }

            for(int j=0;j<m;j++)
            {
                if(colsum[j]==2)
                {
                    ans[0][j]=1;
                    ans[1][j]=1;
                    upper--;
                    lower--;
                }
                else if(colsum[j]==1)
                {
                    if(upper>lower)
                    {
                      ans[0][j]=1;
                      upper--;
                    }
                    else
                    {
                        ans[1][j]=1;
                        lower--;
                    }
                }    
            }
        if(upper!=0||lower!=0)
        return {};
        return ans;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class FindElements {
public:
    TreeNode* curr;
    FindElements(TreeNode* root) {
        curr=root;
    }
    bool findVal(TreeNode*root,int val,int x){
        if(!root)return false;
        if(val==0)return true;
        root->val=x;
        if(root->val==val)return true;       
        return findVal(root->left,val,(2*root->val)+1)||  findVal(root->right,val,(2*root->val)+2);
    }

    bool find(int target) {
        return findVal(curr,target,0);
    }
};

