class Solution {
    int maxi = 0;
    private void solveRec(int[] nums, int idx, int sum){
        //Base case
        if(idx == nums.length){
            if(sum%3 == 0) maxi = Math.max(maxi, sum);
            return ;
        }

        solveRec(nums, idx+1, sum+nums[idx]);
        solveRec(nums, idx+1, sum+0);
    }


    public int maxSumDivThree(int[] nums) {
/*
        solveRec(nums, 0, 0);
        return maxi;
*/

        int[] dp = new int[3];
        for(int num:nums){
            for(int i:Arrays.copyOf(dp, dp.length)){
                dp[(i+num)%3] = Math.max(dp[(i+num)%3], i+num);
            }
        }
        return dp[0];
    }
}

class Solution {
public:
    int countServers(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();
        int temp = 0;
        int total = 0;
        for(int i=0; i<n; i++){
            int col,cnt = 0;
            for(int j=0; j<m; j++){
                if(grid[i][j] == 1){
                    total++;
                    col = j;
                    cnt++;
                }
            }
            if(cnt == 1){
                int cntCol = 0;
                for(int k=0; k<n; k++){
                    if(grid[k][col] == 1) cntCol++;
                }
                if(cntCol == 1) temp++;
            }
        }
        return total - temp;
    }
};

