// O(m * n)
class Solution {
    private final List<Integer[]> directions = List.of(
            new Integer[]{1, 0}, new Integer[]{0, 1}, new Integer[]{1, 1}
    );

    public int countSquares(int[][] matrix) {
        int count = 0;
        int[][] memo = new int[matrix.length][matrix[0].length];
        for (int[] row: memo) Arrays.fill(row, -1);
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[0].length; j++) {
                count += expand(i, j, matrix, memo);
            }
        }
        return count;
    }

    private int expand(int i, int j, int[][] matrix, int[][] memo) {
        if(notValid(i, j, matrix)) return 0;
        if(matrix[i][j] == 0) {
            memo[i][j] = 0;
            return memo[i][j];
        }
        if(memo[i][j] != -1) return memo[i][j];
        int min = Integer.MAX_VALUE;
        for (Integer[] direction: directions) {
            int x = i + direction[0], y = j + direction[1];
            min = Math.min(min, expand(x, y, matrix, memo));
        }
        memo[i][j] = 1 + min;
        return memo[i][j];
    }

    private boolean notValid(int i, int j, int[][] matrix) {
        return i < 0 || i >= matrix.length || j < 0 || j >= matrix[0].length;
    }
}

class Solution {
public:
    int subtractProductAndSum(int n) {
        vector<int> ans;
        while (n > 0)
        {
            ans.push_back(n % 10);
            n /= 10;
        }
        int product = 1;
        int sum = 0;
        for (int i = 0; i < ans.size(); i++)
        {
            product *= ans[i];
            sum += ans[i];
        }
        return product - sum;
    }
};

class Solution {
public:
    int smallestDivisor(vector<int>& nums, int threshold) {
        int i=1, j=INT_MAX;
        while(i<j){
            int mid=i+(j-i)/2;
            int cnt=0;
            for(auto it: nums){
                cnt+=(it/mid)+(it%mid!=0);
            }
            //cout<<cnt<<endl;
            if(cnt>threshold){
                i=mid+1;
            }
            else{
                j=mid;
            }
        }
        return i;
    }
};

class CombinationIterator {
    string s;
    int n, L, mask = 0;
    bool has_next = true;
public:                            //  initially set bits corresponding ↓ to 1st n bits of s
    CombinationIterator(string s, int n) : s(s), L(size(s)), n(n), mask((1<<n)-1 << L-n) { }
    string next() {
        string combination = "";
        for(int j = L-1; j >= 0; j--)             // iterate over mask from MSB to LSB
                if(mask & 1 << j)                 // if a bit is set,
                    combination += s[L-1-j];      // then add character corresponding to that bit
        updateMask();                             // move to next mask
        return combination;
    }
    void updateMask() {
        int rightMostBit = mask & -mask;            // get right-most set bit
        if(rightMostBit != 1) {                     // if last bit(LSB) is not set, just right-shift
            mask ^= rightMostBit;                   // unset right-most bit
            mask |= rightMostBit>>1;                // and set its right-adjacent bit
        } 
        else {
            // all 1s occur adjacently at right-end means we explored all
            if((mask & (mask + 1)) == 0) { has_next = false; return; } 

            int rightOnesCnt = 0, pos = 0;           // get group of continous 1s at right
            while(mask & 1 << pos) {
                mask ^= 1 << pos;                    // unset these group of 1s
                rightOnesCnt++, pos++;
            }
            int rightMostBit = mask & -mask;         // now get rightmost set bit position & right-shift it
            mask ^= rightMostBit;                    // First: unset it
            mask |= rightMostBit >>= 1;              // Then : set its right-adjacent
            while(rightOnesCnt--)                    // paste rightmost group of 1s that we had unset above /
                mask |= rightMostBit >>= 1;          // right-adjacent to rightMostBit that was right-shifted above
        }
    }
    bool hasNext() { return has_next; }
};

class CombinationIterator {
    string s;
    int n, L, mask = 0;
    bool has_next = true;
public:
    CombinationIterator(string s, int n) : s(s), L(size(s)), n(n), mask((1<<n)-1 << L-n) { }
    string next() {
        string combination = "";
        for(int j = L-1; j >= 0; j--)             // iterate over mask from MSB to LSB
                if(mask & 1 << j)                 // if a bit is set,
                    combination += s[L-1-j];      // then add character corresponding to that bit
        updateMask();                             // move to next mask
        return combination;
    }
    // using Gospel's hack
    void updateMask() {
        int t = mask + 1, u = t ^ mask, v = t & mask;
        mask = v - (v & -v) / (u + 1);
        has_next = mask;
    }
    bool hasNext() { return has_next; }
};

class CombinationIterator {
public:
    void backtrack(string curr, string chars, int n, int start) {
        if (curr.size() == n) {
            combs.push_back(curr);
            return;
        }

        for (int i = start; i < chars.size(); i++) {
            curr.push_back(chars[i]);
            backtrack(curr, chars, n, i+1);
            curr.pop_back();
        }
    }

    CombinationIterator(string characters, int combinationLength) {
        backtrack("", characters, combinationLength, 0);
    }

    string next() {
        return combs[i++];
    }

    bool hasNext() {
        return i < combs.size();
    }

private:
    vector<string> combs;
    int i = 0;
};

class Solution {
    public int findSpecialInteger(int[] arr) {
        int size = arr.length;
        int qtr = size / 4;
        int cnt = 1;
        int p = arr[0];
        for (int i = 1 ; i < arr.length ; i++) {

            if ( p == arr[i]) cnt++;
            else cnt = 1;

            if (cnt > qtr) return arr[i];

            p = arr[i];
        }

        return p;
    }
}

class Solution {
public:
    int minFallingPathSum(vector<vector<int>>& grid) {
        if(grid.size()==1)return grid[0][0];
        int mn1=INT_MAX,mn2=INT_MAX,ind1=-1,ind2=-1,i,j,n=grid.size(),ans1=0,ans2=0,i1=-1,i2=-1;
        for(i = 0; i < n; i++){
            if(i==0){
                for(j = 0; j < n; j++){
                    if(grid[i][j] < mn1){
                        mn2 = mn1;
                        mn1 = grid[i][j];
                        ind1 = j;
                    }else if(grid[i][j]<mn2){
                        mn2 = grid[i][j];
                        ind2 = j;
                    }
                }
            }else{
                for(j = 0; j < n; j++){
                    if(j != ind1){
                        grid[i][j] += mn1;
                    }else{
                        grid[i][j] += mn2;
                    }
                }
                mn1 = mn2 = INT_MAX;
                for(j = 0; j < n; j++){
                    if(grid[i][j] < mn1){
                        mn2 = mn1;
                        mn1 = grid[i][j];
                        ind1 = j;
                    }else if(grid[i][j]<mn2){
                        mn2 = grid[i][j];
                        ind2 = j;
                    }
                }
