        }
        // for(auto &i: grid){
        //     for(auto &j: i)cout<<j<<" ";
        //     cout<<endl;
        // }
        return min(mn1,mn2);
    }
};

class Solution {
    public boolean isPossibleDivide(int[] arr, int k) {

        int n = arr.length;

        if(n%k!=0) return false;
        Arrays.sort(arr);

        ArrayList<Integer> a = new ArrayList<>();
        HashMap<Integer,Integer> hp = new HashMap<>();

        for(int i=0; i<n; i++){
            a.add(arr[i]);
            hp.put(arr[i],hp.getOrDefault(arr[i],0)+1);
        }

        while(a.size()!=0){
            if(a.size()<k){
                return false;
            }

            int y = Integer.valueOf(a.get(0));

            for(int i=1; i<=k; i++){
                if(hp.containsKey(y)){
                    hp.put(y,hp.get(y)-1);
                    if(hp.get(y)==0) hp.remove(y);

                    int x = a.indexOf(y);
                    a.remove(x);
                }else{
                    return false;
                }
                y=y+1;
            }
        }

        return true;
    }
}

static long MOD=1e9+7;               //Large mod less collisions.
class Solution {
public:
    long powMod(long x,int y) {           //Modular power
        long res=1;
        while (y>0) 
        { 
            if(y&1) 
                res=(res*x)%MOD; 
            y=y>>1;
            x=(x*x)%MOD;   
        } 
        return res; 
    } 
    int maxFreq(string s, int maxLetters, int minSize, int maxSize) 
    {
        long hash=0,Pow=powMod(53,minSize-1);
        int start=0,result=0;
        unordered_map<int,int> count;           	//Stores count of letters in the window.
        unordered_map<long,int> occurence;        //Stores count of occurence of that string.
        for(int i=0;i<s.length();i++)			//Sliding window
        {
            count[s[i]]++;						//Increase the count of letter at i.
            if(i-start+1>minSize)                  //Reduce the size of the window if increased to size.
            {
                hash-=(s[start]-'a')*Pow;
                if(--count[s[start]]==0)			//Remove the letter from map if count 0 to track unique letters.
                    count.erase(s[start]);
                start++;
            }
            hash=(hash*53+s[i]-'a')%MOD;
            if(i-start+1==minSize&&count.size()<=maxLetters)	//When the substring in the window matches the constraints.
                result=max(result,++occurence[hash]);     //Increase the occurence count of the string and get max.
        }
        return result;
    }
};

