class Solution {

    static boolean helper(int arr[], int idx){

        Queue<Integer> q = new LinkedList<>();
        q.add(idx);

        HashSet<Integer> hp = new HashSet<>();

        while(q.size()!=0){
            int a = q.remove();
            if(a>=arr.length || a<0) continue;
            if(arr[a]==0) return true;
            if(!hp.contains(a-arr[a])){
                q.add(a-arr[a]);
                hp.add(a-arr[a]);
            }

            if(!hp.contains(a+arr[a])){
                q.add(a+arr[a]);
                hp.add(a+arr[a]);
            }
        }
        return false;
    }
    public boolean canReach(int[] arr, int start) {
        return helper(arr,start);
    }
}

class Solution {
    public int minInsertions(String s) {
        String s2 = new StringBuilder(s).reverse().toString();
        int n = s.length();
        int[][] dp = new int[n+1][n+1];

        for(int i = 1; i <= n; i++) {
            for(int j = 1; j <= n; j++) {
                if(s.charAt(i-1) == s2.charAt(j-1)) dp[i][j] = 1 + dp[i-1][j-1];
                else dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]);
            }
        }
        return n - dp[n][n];
    }
}

class Solution {
private:

    int solveMemoization(string &s, string &t, int p1, int p2, vector<vector<int>> &dp)
    {
        if(p1<0 || p2<0)
            return 0;

        if(dp[p1][p2] != -1)
            return dp[p1][p2];

        int ans = 0;
        if(s[p1] == t[p2])
            ans = 1 + solveMemoization(s, t, p1-1, p2-1, dp);
        else  
            ans = max(solveMemoization(s, t, p1-1, p2, dp), solveMemoization(s, t, p1, p2-1, dp));

        dp[p1][p2] = ans;
        return dp[p1][p2];
    }

public:
    int minInsertions(string s) {
        int n = s.size();
        string t = s;
        reverse(t.begin(), t.end());

        vector<vector<int>> dp(n+1, vector<int> (n+1, -1));
        int longestPalindrome = solveMemoization(s, t, n-1, n-1, dp);

        return n - longestPalindrome;
    }
};

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    static boolean check(TreeNode root, int tar){
        if(root==null) return false;
        if(root.left==null && root.right==null){
            if(root.val==tar) return true;
            else return false;
        }

        return check(root.left,tar) || check(root.right,tar);
    }

    static TreeNode delete(TreeNode root, int tar){
        if(root==null) return null;
        if(root.left==null && root.right==null && root.val==tar) return null;

        TreeNode left = delete(root.left,tar);
        TreeNode right = delete(root.right,tar);
        root.left = left;
        root.right = right;
        return root;

    }


    public TreeNode removeLeafNodes(TreeNode root, int tar) {
        if(root.left==null && root.right==null && root.val==tar) return null;

        TreeNode ans = root;

        while(check(ans,tar)){
            ans = delete(ans,tar);
        }
        return ans;

    }
}

class Solution {
public:
    using int2 = pair<int, int>;

    struct cmp {
        bool operator()(int2& x, int2& y) {
            if (x.first != y.first) return x.first > y.first;
            return x.second < y.second;
        }
    };

    int minTaps(int n, vector<int>& ranges) {
        // Build the path with distance
        vector<vector<int2>> path(n + 1, vector<int2>());
        for (int i = 0; i <= n; i++) {
            int d=ranges[i];
            int l=max(0, i - d);
            int r=min(n, i + d);
            if (r != l) {
                path[l].push_back({1, r}); // (distance, endpoint)
            }
        }

        //Adding path with distance 0 makes l reaching all i with i<=r
        for (int i = 1; i <= n; i++) {
            path[i].push_back({0, i-1}); // (distance, endpoint)
        }

        // Dijkstra's algorithm
        vector<int> dist(n+1, INT_MAX);
        dist[0] = 0;
        priority_queue<int2, vector<int2>, cmp> pq;
        pq.push({0, 0});

        while (!pq.empty()) {
            auto [d, i] = pq.top();
            pq.pop();

            if (d>dist[i]) continue;

            for (auto [w, j] : path[i]) {
                if (dist[i]+w < dist[j]) {
                    dist[j] = dist[i] + w;
                    pq.push({dist[j], j});
                }
            }
        }

        return (dist[n] == INT_MAX) ? -1 : dist[n];
    }
};

class Solution {
public:
    int minTaps(int n, vector<int>& ranges) {
        vector<int> newRanges(n+1);
        for(int pos = 0; pos <= n; pos++){
            if(ranges[pos] == 0)continue;
            int leftLimit = max(0, pos - ranges[pos]);
            int rightLimit = min(n, pos + ranges[pos]);
            newRanges[leftLimit] = max(newRanges[leftLimit], rightLimit);
        }
        int lastTpCov = 0, tpCnt = 0;
        for(int pos = 0; pos <= n && lastTpCov < n; ){
            int currLastTpCov = lastTpCov;
            tpCnt++;
            while(pos <= n && pos <= lastTpCov){
                 currLastTpCov = max(newRanges[pos++], currLastTpCov);
            }
            if(currLastTpCov == lastTpCov)return -1;
            lastTpCov = currLastTpCov;
        }
        return tpCnt;

    }
};

class Solution {
public:
    int findTheCity(int n, vector<vector<int>>& edges, int distanceThreshold) {
        vector<vector<int>> dist(n,vector<int>(n,1e9));

        for(auto it:edges) {
            dist[it[0]][it[1]] = it[2];
            dist[it[1]][it[0]] = it[2];
        }

        for(int i=0;i<n;i++) {
            dist[i][i] = 0;
        }


        for(int node = 0;node<n;node++) {
            for(int i=0;i<n;i++) {
                for(int j=0;j<n;j++) {
                    if(dist[i][node] == 1e9 || dist[node][j] == 1e9)
                        continue;

                    dist[i][j] = min(dist[i][j], dist[i][node]+dist[node][j]);
                }
            }
        }

        int cityMax = n;
        int cityNo = -1;

        for(int i=0;i<n;i++) {
            int count=0;
            for(int j=0;j<n;j++) {
                if(dist[i][j] <= distanceThreshold) {
                    count++;
                }
            }
            if(count <= cityMax) {
                cityMax = count;
                cityNo = i;
            }

        }

        return cityNo;
    }
};

class Solution {
public:
    int findTheCity(int n,  vector<vector<int>>& edges,int distanceThreshold) {
        vector<vector<int>> dist(n,vector<int>(n,INT_MAX));
        for(auto it:edges){
            dist[it[0]][it[1]] = it[2];
            dist[it[1]][it[0]] = it[2];

        }
        for(int i=0;i<n;i++){
            dist[i][i]=0;
        }
        for(int k=0;k<n;k++){
            for(int i=0;i<n;i++){
                for(int j=0;j<n;j++){
                    if(dist[i][k]==INT_MAX || dist[k][j]==INT_MAX){
                        continue;
                    }
                    dist[i][j]= min(dist[i][j],dist[i][k]+dist[k][j]);
                }
            }
        }
        int ccity=n;
        int cityno=-1;
        for(int city=0;city<n;city++){
            int cnt=0;
            for(int adjcity =0;adjcity<n;adjcity++){
                if(dist[city][adjcity]<=distanceThreshold){
                    cnt++;
                }
            }
            if(cnt<=ccity){
                ccity=cnt;
                cityno=city;
            }
        }
        return cityno;
    }
};

class Solution {
    public int[] kWeakestRows(int[][] mat, int k) {
        int rows = mat.length;
        int cols = mat[0].length;

        List<int[]> weakArr = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            int soldCnt = 0;
            for (int c = 0; c < cols; c++) {
                soldCnt += mat[r][c];
            }
            weakArr.add(new int[]{soldCnt, r});
        }

        weakArr.sort(new Comparator<int[]>() {
            public int compare(int[] v1, int[] v2) {
                if (v1[0] != v2[0]) {
                    return Integer.compare(v1[0], v2[0]);
                } else {
                    return Integer.compare(v1[1], v2[1]);
                }
            }
        });

        int[] res = new int[k];
        for (int i = 0; i < k; i++) {
            res[i] = weakArr.get(i)[1];
        }
        return res;
    }
}

var checkIfExist = function(arr) {
    const hashmapEven = new Map();
    const hashmapOdd = new Map();

    for (let i = 0; i < arr.length; i++) {
        const item = arr[i];
        if (item % 2) {
            if (hashmapEven.has(item*2)) return true;
            hashmapOdd.set(item, 1);
        } else {
            if (hashmapOdd.has(item/2) || hashmapEven.has(item/2) || hashmapEven.has(item*2)) return true;
            hashmapEven.set(item, 1);
        }
    }
    return false;
};

