//Bucket sort & Brian Kerninghan's Algorithm
class Solution {
public:
    int HammingWeight(int x){//Brian Kerninghan's Algorithm
        int wt=0;
        while(x>0)
            x&=(x-1), wt++;
        return wt;
    }
    vector<int> sortByBits(vector<int>& arr) {
        vector<vector<int>> B(32);
        #pragma unroll
        for(int x :arr)
            B[HammingWeight(x)].push_back(x);
        #pragma unroll
        for (auto& b: B)
            sort(b.begin(), b.end());
        int count=0;
        #pragma unroll
        for(int i=0; i<32; i++)
            for(int x: B[i])
                arr[count++]=x;
        return arr;
    }
};

class Solution {
public:
    // Count the number of set bits (1s) in the binary representation of a number.
    static int countBits(int num) {
        int count = 0;

        while (num > 0) {
            count++;
            num &= (num - 1);  // Clear the least significant set bit.
        }

        return count;
    }

    static bool compare(int a, int b) {
        int bitCountA = countBits(a);
        int bitCountB = countBits(b);

        if (bitCountA == bitCountB) {
            return a < b;  // If set bit counts are equal, compare numerically.
        }

        return bitCountA < bitCountB;  // Sort by the set bit count in ascending order.
    }

    vector<int> sortByBits(vector<int>& arr) {
        sort(arr.begin(), arr.end(), compare);
        return arr;
    }
};

class Cashier {

    int discountOnEach, numOfBills, discount;
    int[] products, prices;
    Map<Integer, Integer> mapOfProducts;

    public Cashier(int n, int discount, int[] products, int[] prices) {
        discountOnEach = n;
        numOfBills = 0;
        this.discount = discount;
        this.products = products;
        this.prices = prices;
        initializeMapOfProducts();
    }

    private void initializeMapOfProducts() {
        mapOfProducts = new HashMap<>();
        for (int i = 0; i < products.length; i++) {
            mapOfProducts.put(products[i], i);
        }
    }

    public double getBill(int[] product, int[] amount) {
        int sum = 0;
            numOfBills++;
            for (int i = 0; i < product.length; i++) {
                int currentProduct = product[i];
                int idx = mapOfProducts.get(currentProduct);
                sum += prices[idx] * amount[i];
            }
            if (numOfBills % discountOnEach == 0) {
                return sum * ((100 - discount) / 100.0);
            }
            return sum * 1.0;
    }
}

