class Solution {
public:
    unordered_map<int, int> parent;

    bool findParent(int n, vector<int>& leftChild, vector<int>& rightChild) {
        #pragma unroll
        for (int i=0; i < n; i++) {
            int left = leftChild[i], right=rightChild[i];
            if (left != -1) {
                if (parent.count(left) != 0 || left == i) {
                    return 0;
                }
                parent[left] = i;
            }
            if (right != -1) {
                if (parent.count(right) != 0 || right == i) {
                    return 0;
                }
                parent[right] = i;
            }
        }
        return 1;
    }

    vector<int> root;

    int findRoot(int i) {
        if (parent.count(i)==0) 
            return i;

        if (root[i]!=-1) return root[i];
        // Mark the node as visited during this call
        root[i]=-2; //for detecting cycle
        return root[i]=findRoot(parent[i]);
    }

    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        bool yes = findParent(n, leftChild, rightChild);
        if (!yes) return 0;
        root.assign(n, -1);
        int R0=findRoot(0);
        if (R0==-2||parent.count(R0)) return 0;
        #pragma unroll
        for (int i = 0; i<n; i++) {
            if (root[i]==-1) {
                int R=findRoot(i);
                if (R==-2||R!=R0||parent.count(R)) return 0;//Root shouldn't have a parent.
            }
        }
        return 1;
    }
};

/**
 * @param {number[]} nums
 * @return {number[]}
 */
function forLoop(arr, i, res) {
    let count = 0;
    if(arr[i]!=undefined) {
        for(let j=0; j<arr.length; j++) {
            if(arr[i] > arr[j]) count++;
        }
        res.push(count);
        i++;
        forLoop(arr, i, res);
    }
}
var smallerNumbersThanCurrent = function(nums) {
    let i=0;
    let res = []
    forLoop(nums, i, res);
    return res;
};

public class Solution {
    public bool found;
    public void tryConnecting(ListNode head,TreeNode root){
        if(head==null){
            found=true;
            return;
        }
        if(root!=null){
            if(root.val==head.val){
                tryConnecting(head.next,root.left);
                tryConnecting(head.next,root.right);
            }
        }
    }
    public void dfs(ListNode head,TreeNode root){
        if(root!=null){
            if(root.val==head.val){
                tryConnecting(head,root);
            }
            dfs(head,root.left);
            dfs(head,root.right);
        }
    }
    public bool IsSubPath(ListNode head, TreeNode root) {
        found=false;
        dfs(head,root);
        return found;
    }
}

class Solution {
	public:
	//     DFS -> PreOrder Traversal
		TreeNode* dfs(TreeNode* curr,int val){
			if(!curr) return NULL;        
			if(curr->val == val) return curr;
			TreeNode* l = dfs(curr->left,val);
			if(l) return l ;
			TreeNode* r = dfs(curr->right,val);
			if(r) return r;
			return NULL;
		}

		TreeNode* getTargetCopy(TreeNode* original, TreeNode* cloned, TreeNode* target) {
			int val = target->val;
			return dfs(cloned,val);
		}
	};

class Solution{
public:
    const int mod = (int)1e9 + 7;
    int maxPerformance(int n, vector<int> &speed, vector<int> &efficiency, int k){
      // to maintain the heap of size k we will use priority queue
      priority_queue<int, vector<int>, greater<int>> pq;
      // to store the pair of efficiency and speed
      vector<pair<int, int>> v;
      for (int i = 0; i < n; i++){
        v.push_back({efficiency[i], speed[i]});
      }
	  // sort in decreasing order of efficiency
      sort(v.rbegin(), v.rend()); 
	  // totSpeed is the sum of speed of k engineers
      long totSpeed = 0, ans = 0;
	  // iterate over all engineers
      for (int i = 0; i < n; i++) {
        int currEff = v[i].first;
        int currSpeed = v[i].second;
		// if the size of pq is k
        if (pq.size() == k) {
		  // remove the minimum speed from the pq
          totSpeed -= pq.top();
          pq.pop();
        }
		// push the current speed in the pq
        pq.push(currSpeed); 
		// add the current speed to the totSpeed
        totSpeed += currSpeed; 
		// update the ans
        ans = max(ans, totSpeed * currEff); 
      }
      return ans % mod;
    }
};

class Solution {
    public int maxPerformance(int n, int[] speed, int[] efficiency, int k) {
        int[][] ord = new int[n][2];
        for (int i = 0; i < n; i++)
            ord[i] = new int[] {efficiency[i], speed[i]};
        Arrays.sort(ord, (a, b) -> Integer.compare(b[0], a[0]));
        PriorityQueue<Integer> sppq = new PriorityQueue<>();
        long totalSpeed = 0, best = 0;
        for (int[] pair : ord) {
            int spd = pair[1];
            sppq.add(spd);
            if (sppq.size() <= k) totalSpeed += spd;
            else totalSpeed += spd - sppq.poll();
            best = Math.max(best, totalSpeed * pair[0]);
        }
        return (int)(best % 1000000007);
    }
}

public class Solution 
{
    public int FindTheDistanceValue(int[] arr1, int[] arr2, int d) 
    {
        int result = 0;
        Array.Sort(arr2);
        foreach(var num in arr1)
        {
            int index1 = Array.BinarySearch(arr2, num + d), index2 = Array.BinarySearch(arr2, num - d);
            if(index1 < 0) 
                index1 = ~index1 - 1;
            if(index2 < 0) 
                index2 = ~index2;
            if(index2 > index1)
                result++;
        }

        return result;
    }
}

class Solution {
    public int maxNumberOfFamilies(int n, int[][] reservedSeats) {
        Map<Integer, Integer> cinemaSeats = new HashMap<>();
        for (int[] reserved: reservedSeats) {
            int row = reserved[0] - 1, col = reserved[1];
            cinemaSeats.put(row, setBit(cinemaSeats.getOrDefault(row, 0), 10 - col));
        }
        int numFamilies = 0;
        int leftAisle = 480, rightAisle = 30, middleAisle = 120;
        for (int row: cinemaSeats.values()) {
            row = ~(row) & ((1 << 10) - 1);
            if(((row & (leftAisle | rightAisle)) ^ (leftAisle | rightAisle)) == 0) numFamilies += 2;
            else if(((row & leftAisle) ^ leftAisle) == 0 ||
                    ((row & rightAisle) ^ rightAisle) == 0 ||
                    ((row & middleAisle) ^ middleAisle) == 0)
                numFamilies++;
        }
        return numFamilies + 2 * (n - cinemaSeats.keySet().size());
    }

    private int setBit(int cinemaSeat, int i) { return cinemaSeat | (1 << i); }
}

class Solution {
public:
