class Solution {
public:
string entityParser(string t) {    
    unordered_map<string,int>mpp ={{"&quot;",34},{"&apos;",39},{"&amp;",38},{"&gt;",62},{"&lt;",60},{"&frasl;",47}};
    string ans = "";
    for(int i = 0; i < t.size();)
    {
        if(t[i]=='&')
        {
          int j = i;
          string s;
          bool f = 0;
          while(j<t.size() && t[j]!=';')
          {
            if(f==0) f = 1;
            else if(f==1&&t[j]=='&')
            {
              ans = ans+s;
              s.clear();
            }
            s.push_back(t[j++]);
          }
          if(t[j]==';') s.push_back(t[j]);
          if(mpp.find(s)!=mpp.end())
          {
            char ch = char(mpp[s]);
            ans.push_back(ch);
          }
          else  ans = ans + s;
          i = j+1;
        }
        else ans.push_back(t[i++]); 
    }
      return ans;
    }
};

var minStartValue = function(nums) {
    let output = 0;
    let currentSum = 0;

    for (let i = 0; i < nums.length; i++) {
        if (currentSum + nums[i] < 1) {
            output += -(currentSum + nums[i]) + 1;
            currentSum = 1;
        } else {
            currentSum += nums[i];
        }
    }

    return output || 1;
};

class Solution {
public:
    int MOD = 1000000007;
    int numberOfArrays(string s, int k) 
    {
        int n = s.size();
        vector<int>dp(n + 1, 0);
        //In top down 
        //1) For string starting from startIdx
        //   we needed answers of strings starting from [startIdx+1, startIdx+2, ....]
        //2) Recursion did that for us

        //In bottom up
        //1) We need to pre-calculate the desired results first
        //2) So we will go from startIdx = n - 1 to startIdx = 0
        //3) Now for startIdx = x, we would already have answers stored for 
        //           startIdx = [x+1, x+2, x+3......]

        dp[n] = 1; //base case implemented here
        for (int startIdx = n - 1; startIdx >= 0; startIdx--)
        {
            long long currNum = 0, ways = 0;
            //=================================================
            for (int i = startIdx; i < s.size(); i++)
            {
                int currDig = s[i] - '0';
                currNum = (currNum * 10) + currDig; //building the number from L->R

                if (currNum < 1 || currNum > k) break;
                int nextWays = dp[i + 1]; 
                ways = (ways +  nextWays) % MOD;
            }
            //====================================================
            dp[startIdx] = ways;
        }
        return dp[0];
    }
};

var maxScore = function(C, K) {
    let total = 0
    for (let i = 0; i < K; i++) total += C[i]
    let best = total
    for (let i = K - 1, j = C.length - 1; ~i; i--, j--)
        total += C[j] - C[i], best = Math.max(best, total)
    return best
};

class Solution {
    public String destCity(List<List<String>> paths) {
        Set<String> cities = new HashSet<>(); 
        for (List<String> path : paths) {
            cities.add(path.get(0)); 
        }

        for (List<String> path : paths) {
            String dest = path.get(1); 
            if (!cities.contains(dest)) {
                return dest; 
            }
        }
        return "";
    }
}

