class Solution {
public:
    int countTriplets(vector<int>& arr) {
        int i, j, k, a, b, count=0;

        for(i=0 ; i<arr.size() ; i++)
        {
            a=0;
            for(j=i+1 ; j<arr.size() ; j++)
            {
                b=0;
                a = a^arr[j-1];
                for(k=j ; k<arr.size() ; k++)
                {
                    b = b^arr[k];
                    if(a==b)
                    {
                        count++;
                    }
                }
            }
        }
        return count;
    }
};

// OJ: https://leetcode.com/problems/form-largest-integer-with-digits-that-add-up-to-target/
// Author: github.com/lzl124631x
// Time: O(T)
// Space: O(T)
class Solution {
    inline bool isGreaterThan(string &a, string &b) {
        return a.size() != b.size() ? a.size() > b.size() : a > b;
    }
public:
    string largestNumber(vector<int>& A, int T) {
        int N = A.size();
        vector<vector<string>> dp(N + 1, vector<string>(T + 1, "0"));
        for (int i = 0; i <= N; ++i) dp[i][0] = "";
        for (int i = 0; i < N; ++i) {
            for (int c = 1; c <= T; ++c) {
                dp[i + 1][c] = dp[i][c];
                if (c < A[i] || dp[i + 1][c - A[i]] == "0") continue;
                auto s = string(1, '1' + i) + dp[i + 1][c - A[i]];
                if (isGreaterThan(s, dp[i + 1][c])) dp[i + 1][c] = s;
            }
        }
        return dp[N][T];
    }
};

class Solution {
public:
    int busyStudent(vector<int>& startTime, vector<int>& endTime, int queryTime) {

    int n=startTime.size();
    int count = 0;
    for (int i = 0; i < n; i++)
    {
        if (queryTime >= startTime[i] && queryTime <= endTime[i])
        {
            count++;
        }
    }
    return count;


    }
};

class Solution {
public:
    bool hasAllCodes(string s, int k) {
        if (k > s.size()) return false;

        unordered_set<string> my_set;

        for (int i = 0; i <= s.size()-k; i++)
            my_set.insert(s.substr(i, k));

        return my_set.size() == pow(2, k);
    }
};

class Solution {
public:

int f(int i,int j1,int j2,int row, int col,vector<vector<int>>& grid,vector<vector<vector<int>>>& dp){
    if( j1< 0 || j2 < 0 || j1 >= col || j2 >= col ){
        return -1e8;
    }

    if(i==row-1){
        if(j1==j2){
            return grid[i][j1];
        }
        else{
            return grid[i][j1] + grid[i][j2];
        }
    }
    if(dp[i][j1][j2]!=-1){
        return dp[i][j1][j2];
    }

    int maxi=-1e8;

    for(int dj1=-1;dj1<=1;dj1++){
        for(int dj2=-1;dj2<=1;dj2++){
            int val = 0;
            if(j1==j2){
                val = grid[i][j1];
            }
            else{
                val = grid[i][j1] + grid[i][j2];
            }
            val+=f(i+1,j1+dj1,j2+dj2,row,col,grid,dp);
        maxi = max (maxi,val);
        }    
    }
    return dp[i][j1][j2] = maxi;
}

    int cherryPickup(vector<vector<int>>& grid) {
        int row = grid.size();
        int col = grid[0].size();
        vector<vector<vector<int>>> dp(row,vector<vector<int>>(col,vector<int>(col,-1)));
        return f(0,0,col-1,row,col,grid,dp);
    }
};

