class Solution {
public:
    int maxProduct(vector<int>& nums) {
        priority_queue<int, vector<int>, greater<int>> pq;
        for (int x: nums){
            pq.push(x);
            if (pq.size()>2) pq.pop();    
        }
        int product=pq.top()-1;
        pq.pop();
        product*=(pq.top()-1);
        return product;
    }
};

class Solution {
    public int minReorder(int n, int[][] connections) {
        ArrayList<ArrayList<Integer>> adj =new ArrayList<>();
        for(int i=0;i<n;i++)
            adj.add(new ArrayList<Integer>());
        for(int i=0;i<connections.length;i++)
        {
            adj.get(connections[i][0]).add(connections[i][1]);
            adj.get(connections[i][1]).add(-connections[i][0]);
        }
        Queue<Integer> q=new LinkedList<>();
        q.add(0);
        boolean vis[]=new boolean[n];
        vis[0]=true;
        int minchg=0;
        while(q.size()!=0)
        {
            int help=q.poll();
            vis[Math.abs(help)]=true;
            for(int x:adj.get(Math.abs(help)))
            {
                if(!vis[Math.abs(x)])
                {
                    q.add(x);
                    vis[Math.abs(x)]=true;
                    if(x>0)
                        minchg++;
                }
            }
        }
        return minchg;
    }
}

class Solution {
public:
    vector<int> shuffle(vector<int>& nums, int n) {
        vector<int> a;
        vector<int> b;
        for (int i = 0; i < n; i++)
        {
            a.push_back(nums[i]);
        }
        for (int i = n; i < 2 * n; i++)
        {
            b.push_back(nums[i]);
        }
        int m = 0, k = 0;
        for (int i = 0; i < 2 * n; i++)
        {
            if (i % 2 == 0) 
            {
                nums[i] = a[m++];
            }
            else nums[i] = b[k++];
        }
        return nums;
    }
};

class Solution {
public:
    int findLeastNumOfUniqueInts(vector<int>& arr, int k) {
          unordered_map<int,int>mp;
   //get the freq of the arr elements
   for(int i=0;i<arr.size();i++)
   {
      mp[arr[i]]++;	
   }        
   vector<pair<int,int>>v;
   for(auto it=mp.begin();it!=mp.end();it++)
   {
      	v.push_back(make_pair(it->second,it->first)); // <freq , num>
   }
   sort(v.begin(),v.end());

   int idx=0;

   while(idx<v.size())
   {
   	  int ele=v[idx].second;
   	  int freq=v[idx].first;

   	  if(freq > k)   //  <5,8>      //k -->3
   	  {
   	     k=0;
      }
      else if(freq == k)
      {
      	 k=k-freq;
      	 idx++;    //we have removed successfully that entry
	  }
	  else if(freq < k)  //<3,8>  //k-->5
	  {
	  	 k=k-freq;
	  	 idx++;  //we have removes successfully that entry too..
	  }
	  if(k==0)
	  {
	  	break;
	  }
   }

   return v.size()-idx;
    }
};

class Solution {
public:
    int longestSubarray(vector<int>& nums) {
        vector<int> z;
        int n=nums.size();
        for(int i=0;i<n;i++)
        {
            if(nums[i]==0)
                z.push_back(i);//storing index of all the zeros
        }
        int maxi=INT_MIN,n1=z.size();
        if(n1<=1)
            return n-1;//since we have to delete one element
        if(n1>=2)
        {
             maxi=max(maxi,z[1]-1);//if 1st zero is deleted
             maxi=max(maxi,n-z[n1-2]-2);//tracking if last zero is deleted
        }
        for(int i=1;i<n1-1;i++)
        {
            maxi=max(maxi,z[i+1]-z[i-1]-2);//if any zero in between is deleted
        }
        return maxi;
    }
};

class Solution {
public:
    int minNumberOfSemesters(int n, vector<vector<int>>& dependencies, int k) {
        // dp[i] : the minimum number of semesters needed to take the courses with the bit set in i
        // the worst case is that in each semester we can only take one course, hence initialise with `n`
        // at the end, the answer would be dp[(1 << n) - 1], i.e. all bits set
        vector<int> dp(1 << n, n);
        // if the i-th bit is set in pre[j], 
        // that means we need to take course i in order to take course j
        vector<int> pre(n);
        // build the prerequisites
        for (auto& x : dependencies) {
            // make it 0-based index
            --x[0], --x[1];
            // set the bit at x[0]-th place
            pre[x[1]] |= 1 << x[0];
        }
        // base case: 0 semester. 0 course.
        dp[0] = 0;
        // i is a set of courses that we've already studied
        for (int i = 0; i < (1 << n); i++) {
            // init can as 0 to record how can courses we can study
            int can = 0;
            // iterate all courses
            for (int j = 0; j < n; j++) {
                // check if we've studied prerequisite courses
                if ((pre[j] & i) == pre[j]) {
                    // if so, we can study course j
                    can |= (1 << j);
                }
            }
            // remove those courses that we've already studied
            can &= ~i;
            // enumerate all the bit 1 combinations of `can`
            // i.e. all subsets of a bit representation
            for (int s = can; s ; s = (s - 1) & can) {
                // check if we can take __builtin_popcount(s) courses
                if (__builtin_popcount(s) <= k) {
                    // if so, we combine the previous results (what've studied already)
                    // or we take a new semester
                    dp[i | s] = min(dp[i | s], dp[i] + 1);
                }
            }
        }
        // same as dp[(1 << n) - 1]
        return dp.back();
    }
};

class Solution {
public:
    bool canMakeArithmeticProgression(vector<int>& arr) {  
        sort(arr.begin(), arr.end(), greater<int>());
        int diff = arr[0] - arr[1];
        for(int i = 1; i < (int)arr.size() - 1; i++){
            if (diff != (arr[i] - arr[i + 1])){
                return false;
            }
        }
        return true;
    }
};

class Solution {
public:
    using VI = vector<int>;
    static constexpr int INF = 2e9 + 7;
    int minDifference(VI& A, int min = INF) {
        sort(A.begin(), A.end());
        int N = A.size(),
            i = 0,
            j = N - 4;// ⭐️ -4 because N - 1 is the last element and we want to disclude 3 elements, thus N - 1 - 3 == N - 4
        while (0 <= j && j < N)
			min = std::min(min, A[j++] - A[i++]); // slide window by 3 👉
        return min < INF ? min : 0;
    }
};

class Solution {
    public int minDifference(int[] nums) {
        if (nums.length < 5) return 0;
        if (nums.length <= 8) return getDiff(nums, true);
        PriorityQueue<Integer> top4 = new PriorityQueue<>(), bot4 = new PriorityQueue<>((a, b) -> b - a);
        for (int n : nums) {
            top4.offer(n);
            bot4.offer(n);
            if (top4.size() > 4) top4.poll();
            if (bot4.size() > 4) bot4.poll();
        }
        int[] arr = new int[8];
        for (int l = 3, r = 4; l >= 0 && r < 8; l--, r++) {
            arr[l] = bot4.poll();
            arr[r] = top4.poll();
        } 
        return getDiff(arr, false);
    }

    private int getDiff(int[] arr, boolean needSort) {
        if (needSort) Arrays.sort(arr);
        int res = Integer.MAX_VALUE, n = arr.length;
        for (int i = 0; i < 4; i++) {
            res = Math.min(res, arr[n - (4 - i)] - arr[i]);
        }
        return res;
    }
}

class Solution {
    Boolean[] dp = new Boolean[100001];

        public boolean winnerSquareGame(int n) {
            if (n == 0) return false;
            if (dp[n] != null) return dp[n];
            boolean winner = false;
            for (int i = 1; i * i <= n; i++) {
                if (!winnerSquareGame(n - i * i)) {
                    winner = true;
                    break;

                }
            }
            return dp[n] = winner;
        }
}

