class Solution {
public:
    int numSub(string s) {
        long long int ans = 0, i = 0, j= 0, n = s.length(),mod = 1e9+7;
        while(i<n){
            j = i;
            while(j<n && s[i] == s[j]){
                j++;
                if(s[i]=='1'){
                    ans = (ans+j-i)%mod;
                }
            }
            i = j;
        }
        return ans;
    }
};

class Solution {
public:
    double maxProbability(int n, vector<vector<int>>& edges, vector<double>& succProb, int start, int end) {
        vector<pair<int,double>>adj[n]; //Creating adjacency list
        for(int i=0;i<edges.size();i++){
            adj[edges[i][0]].push_back({edges[i][1],succProb[i]});
            adj[edges[i][1]].push_back({edges[i][0],succProb[i]});
        }
        priority_queue<pair<double,int>>pq; //Use maxHeap for path with the maximum probability
        pq.push({1.0,start}); //{probability,node}
        vector<double>dist(n,INT_MIN);
        dist[start]=1;
        while(!pq.empty()){
            auto itr=pq.top();
            pq.pop();
            double dis=itr.first;
            int node=itr.second;
            for(auto it:adj[node]){
                int adjNode=it.first;
                double edW=it.second;
                if(dist[adjNode]<dis*edW){ //If greater probability is found then update probability of adjacent node & push adjacent node in maxHeap
                    dist[adjNode]=dis*edW;
                    pq.push({dist[adjNode],adjNode});
                }
            }
        }        
        if(dist[end]==INT_MIN) return 0.00000; //If there is no path from start to end
        else return dist[end];
    }
};

class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, 
                                 int start, int end) {
        double dp[] = new double[n];
        dp[start] = 1.0;
        boolean changes = true;
        while (changes) {
            changes = false;
            for (int edgeIdx = edges.length - 1; edgeIdx >= 0; edgeIdx--) {
                int u = edges[edgeIdx][0];
                int v = edges[edgeIdx][1];
                double prob = succProb[edgeIdx];
                if (dp[v] * prob > dp[u]) {
                    dp[u] = dp[v] * prob;
                    changes = true;
                }
                if (dp[u] * prob > dp[v]) {
                    dp[v] = dp[u] * prob;
                    changes = true;
                }
            }
        }
        return dp[end];
    }
}

class Solution {
    public int numSplits(String s) {
        HashMap<Character,Integer> map=new HashMap<>();
        for(int i=0; i<s.length() ; i++){
            char ch=s.charAt(i);
            if(map.containsKey(ch)){
                map.put(ch,map.get(ch)+1);
            }else{
                map.put(ch,1);
            }
        }
        int ans=0;
        HashSet<Character> set=new HashSet<>();
        for(int i=0; i<s.length() ; i++){
            if(map.containsKey(s.charAt(i)) && map.get(s.charAt(i))>0){
                map.put(s.charAt(i),map.get(s.charAt(i))-1);
                if(map.get(s.charAt(i))==0){
                   map.remove(s.charAt(i));
                }                
                set.add(s.charAt(i));
                if(set.size()==map.size()){
                    ans++;
                }
            }
        }
        return ans;
    }
}

class Solution {
public:
    int countGoodTriplets(vector<int>& arr, int a, int b, int c) {
        int n=arr.size(),cnt=0;
        for(int i=0;i<n;i++){
            for (int j=i+1;j<n;j++){
                for(int k=j+1;k<n;k++){
                    if(abs(arr[i]-arr[j])<=a && abs(arr[j]-arr[k])<=b && abs(arr[i]-arr[k])<=c) cnt++;
                }
            }
        }
        return cnt;
    }
};

class Solution {
    public int getWinner(int[] arr, int k) {
        int current = arr[0]; // Initialize with the first element
        int count = 0;

        for (int i = 1; i < arr.length ; i++) {
            if (current > arr[i]) {
                count++;
            } else {
                current = arr[i];
                count = 1;
            }

            if (count == k) return current;           
        }
        return current;
    }
}

class Solution {
public:
    int getWinner(vector<int>& arr, int k) {
        int maxElement = arr[0];
        queue<int> queue;
        for (int i = 1; i < arr.size(); i++) {
            maxElement = max(maxElement, arr[i]);
            queue.push(arr[i]);
        }

        int curr = arr[0];
        int winstreak = 0;

        while (!queue.empty()) {
            int opponent = queue.front();
            queue.pop();

            if (curr > opponent) {
                queue.push(opponent);
                winstreak++;
            } else {
                queue.push(curr);
                curr = opponent;
                winstreak = 1;
            }

            if (winstreak == k || curr == maxElement) {
                return curr;
            }
        }

        return -1;
    }
};

class Solution {
    public int longestAwesome(String s) {
        Map<Integer, Integer> pos = new HashMap<>();   // `state` => index of first occurence of this `state`
        int[] occurrences = new int[10];

        // Minimum answer will always be 1
        int ans = 1;

        // All digits have even number of occurences in the beginning.
        pos.put(1023, -1);

        for (int i = 0; i < s.length(); ++i) {
            occurrences[s.charAt(i) - '0']++;

            int currentState = 0;
            for (int j = 0; j < 10; ++j) {
                if (occurrences[j] % 2 == 0) {
                    currentState |= (1 << j);
                }
            }
            // Case 1: All even
            ans = Math.max(ans, i - pos.getOrDefault(currentState, i));

            // Case 2: All even, except one odd
            for (int digitWithOddOccurrences = 0; digitWithOddOccurrences < 10; ++digitWithOddOccurrences) {
                int state = 0;
                for (int j = 0; j < 10; ++j) {
                    if (j != digitWithOddOccurrences) {
                        if (occurrences[j] % 2 == 0) {
                            state |= (1 << j);
                        }
                    } else {
                        if (occurrences[j] % 2 == 1) {
                            state |= (1 << j);
                        }
                    }
                }

                ans = Math.max(ans, i - pos.getOrDefault(state, i));
            }
            if (!pos.containsKey(currentState)) {
                pos.put(currentState, i);
            }
        }

        return ans;
    }
}

class Solution {
    Integer dp[][]; int n, cuts[];
    public int minCost(int n, int[] cuts) {
        Arrays.sort(cuts);
        dp = new Integer[cuts.length+2][cuts.length+2];
        this.n=n;
        this.cuts=cuts;
        return f(0, cuts.length+1);
    }

    int get(int i) { return i==0? 0: (i==cuts.length+1? n: cuts[i-1]); }

    int f(int i, int j) {
        if(i+1==j) return dp[i][j]=0;
        if(dp[i][j]!=null) return dp[i][j];

        int min=Integer.MAX_VALUE;
        for(int k=i+1; k<j; k++) {
            min = Math.min(min, f(i, k) + f(k, j));
        }

        return dp[i][j] = min+get(j)-get(i);
    }
}

