class Solution {
    unordered_map<int, int> dp;
public:
    int minDays(int n) {
        dp[0] = 0;
        return solve(n);
    }

    int solve(int n) {
        if (dp.find(n) != dp.end()) {
            return dp[n];
        }
        int ans = INT_MAX;
        if (n%3 == 0 && n%2 == 0) {         // Divisible by both -
            ans = min(ans, 1 + solve(n/3)); // So find whichever yields minimum among
            ans = min(ans, 1 + solve(n/2)); // n/2 and n/3.

        } else if (n%3 == 0) {              // Only divisible by 3, but not 2
                                            // which means this is an odd number.
            ans = min(ans, 1 + solve(n/3)); // Try n/3.
            ans = min(ans, 1 + solve(n-1)); // Or it may happen that going to the nearest 
                                            // even number i.e. (n-1) might yield better
                                            // answer (which can take n/2 route). So try that.

        } else if (n%2 == 0) {                  // Only divisible by 2, but not 3.
            ans = min(ans, 1 + solve(n/2));     // Try n/2.

            // Similar to previous case, now find nearest number divisible by 3.
            if ((n-1)%3 == 0) {                 
                ans = min(ans, 1 + solve(n-1));
            } else {
                ans = min(ans, 2 + solve(n-2));
            }

        } else {                            // Not divisible by 3 and 2. Which means an odd number.
            ans = min(ans, 1+solve(n-1));   // (n-1) must be even, which will try n/2 route.
            if ((n-2)%3 == 0) {             // if n-2 is divisible by 3, then solve that which will
                                            // take n/3 route.
                ans = min(ans, 2 + solve(n-2));
            }
        }
        dp[n] = ans;                        // Very important - MEMOIZE.
        return dp[n];       // YAY, congratulations. Found the answer.
    }
};

class Solution {
public:
    unordered_map<int, int> dp;
    int minDays(int n) {
        return dfs(n);
    }

    int dfs(int n) {
        if(n == 1) return 1;
        if(n == 2) return 2;
        if(dp.count(n)) return dp[n];
        int res = INT_MAX;
        if(n % 2 == 0)
            res = min(res, 1 + dfs(n / 2));
        if(n % 3 == 0)
            res = min(res, 1 + dfs(n / 3));
        if((n - 1) % 2 == 0 || (n - 1 )% 3 == 0)
            res = min(res, 1 + dfs(n - 1));
        if((n - 2) % 3 == 0)
            res = min(res, 2 + dfs(n - 2));
        return dp[n] = res;
    }
};

class Solution {
public:
   int minOperations(vector<int>& A) {
        int res = 0, maxLen = 1;
        for (int a : A) {
            int bits = 0;
            while (a > 0) {
                res += a & 1;
                bits++;
                a >>= 1;
            }
            maxLen = max(maxLen, bits);
        }
        return res + maxLen - 1;
    }
};

class Solution {
    public int minOperations(int[] nums) {
        int addOneOperations = 0; // +1 operations
        int highestSetBit = 0; // x2 operations
        for (int bit = 0; bit <= 30; ++bit) {
            for (int num : nums) {
                if ((num & (1 << bit)) != 0) {
                    addOneOperations++;
                    highestSetBit = bit;
                }
            }
        }
        return addOneOperations + highestSetBit; // (+1 operations) + (x2 operations)
    }
}

var maxCoins = function(piles) {
    let max = 0;
    let n = piles.length;

    for (let i of piles) {
        if (max < i) max = i;
    }

    let freq = new Array(max + 1).fill(0);

    for (let i of piles) {
        freq[i]++;
    }

    let coins = 0;
    let chance = Math.floor(n / 3);
    let turn = 1;
    let i = max;

    while (chance !== 0) {
        if (freq[i] > 0) {
            if (turn === 1) turn = 0;
            else {
                chance--;
                turn = 1;
                coins += i;
            }
            freq[i]--;
        } else {
            i--;
        }
    }

    return coins;
};

class Solution {
public:
    vector<int> prefixSum;			//Stores prefixSums
    vector<vector<int>> memo;
    int dp(vector<int>& stoneValue,int i,int j)
    {
        if(i==j)
            return 0;
        if(memo[i][j]!=-1)
            return memo[i][j];
        memo[i][j]=0;
        for(int p=i+1;p<=j;p++)		//Try each partition.
        {
			int l=prefixSum[p]-prefixSum[i],r=prefixSum[j+1]-prefixSum[p];
			if(l<r)		//Left part is smaller
                memo[i][j]=max(memo[i][j],l+dp(stoneValue,i,p-1));
            else if(l>r)	//Right part is smaller
                memo[i][j]=max(memo[i][j],r+dp(stoneValue,p,j));
            else	//Both parts are equal
                memo[i][j]=max(memo[i][j],l+max(dp(stoneValue,p,j),dp(stoneValue,i,p-1)));
        }
        return memo[i][j];
    }
    int stoneGameV(vector<int>& stoneValue)
    {
        memo.resize(stoneValue.size(),vector<int>(stoneValue.size(),-1));
        prefixSum.resize(stoneValue.size()+1,0);
        for(int i=0;i<stoneValue.size();i++)		//Create prefix Sums
            prefixSum[i+1]=prefixSum[i]+stoneValue[i];
        return dp(stoneValue,0,stoneValue.size()-1);
    }
};

class Solution {
public:
    int Mod=1e9+7;
    //Calcute C_{n} choose k by Pascal's equation

    int compute_C_N_choose_K(int N, int K){
        if (K>N/2) K=N-K;//C_N choose K =C_N choose N-K
        vector<int> C_N(K+1, 0), prevC(K+1, 0);
        for(int i=0; i<=N; i++){
            C_N[0]=1;
            for(int j=1; j<=min(i, K);j++){
                C_N[j]=((long)prevC[j-1]+prevC[j])%Mod;  
            }
            prevC=C_N;  
        }
        return C_N[K];
    }

    long Subproblem(vector<int>& nums){
        int n=nums.size();
        if (n<=2) return 1;
        vector<int> left, right;
        int root=nums[0];
        for (int i=1; i<n; i++){
            if (root<nums[i]) right.push_back(nums[i]);
            else left.push_back(nums[i]);
        }
        long r=Subproblem(right), l=Subproblem(left);
        return compute_C_N_choose_K(n-1, left.size())*r%Mod*l%Mod;

    }
    int numOfWays(vector<int>& nums) {
        return (Subproblem(nums)-1)%Mod;
    }
};

class Solution {
    int [][] dp;
    int n;
    int finish;
    public int solve(int[] locations, int currCity, int remainingFuel) {
        if (remainingFuel < 0) {
            return 0;
        }
        if (dp[currCity][remainingFuel] != -1) {
            return dp[currCity][remainingFuel];
        }

        int ans = currCity == finish ? 1 : 0;
        for (int nextCity = 0; nextCity < n; nextCity++) {
            if (nextCity != currCity) {
                ans = (ans + solve(locations, nextCity,
                remainingFuel - Math.abs(locations[currCity] - locations[nextCity]))) % 1000000007;
            }
        }

        return dp[currCity][remainingFuel] = ans;
    }

    public int countRoutes(int[] locations, int start, int finish, int fuel) {
        n = locations.length;
        dp = new int[n][fuel + 1];
        this.finish = finish;
        for (int i = 0; i < n; ++i) {
            Arrays.fill(dp[i], -1);
        }

        return solve(locations, start, fuel);
    }
}

class Solution {
public:
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {

        unordered_map<long, int> m1, m2;
        for(int i : nums1) m1[(long long)i*i]++;
        for(int i : nums2) m2[(long long)i*i]++;

        int ans = 0;

        for(int i=0; i<nums2.size()-1; i++){
            for(int j=i+1; j<nums2.size(); j++){
                if(m1[(long long)nums2[i] * nums2[j]]){
                    ans += m1[(long long)nums2[i] * nums2[j]];
                }
            }
        }
        for(int i=0; i<nums1.size()-1; i++){
            for(int j=i+1; j<nums1.size(); j++){
                if(m2[(long long)nums1[i] * nums1[j]]){
                    ans += m2[(long long)nums1[i] * nums1[j]];
                }
            }
        }
        return ans; 
    }
};

class Solution {
public:
    bool isPrintable(vector<vector<int>>& tg) 
    {
        int n=tg.size(),m=tg[0].size();
        vector<int> xmax(61,-1),xmin(61,n),ymax(61,-1),ymin(61,m);
        vector<vector<int>> g(61);
        for(int i=0;i<n;i++)// find max &min index in x& y
        {
            for(int j=0;j<m;j++)
            {
                xmax[tg[i][j]]=max(xmax[tg[i][j]],i);
                xmin[tg[i][j]]=min(xmin[tg[i][j]],i);
                ymax[tg[i][j]]=max(ymax[tg[i][j]],j);
                ymin[tg[i][j]]=min(ymin[tg[i][j]],j);
            }
        }
        vector<int> indeg(61);
        for(int colr=1;colr<=60;colr++)
        {
            for(int i=xmin[colr];i<=xmax[colr];i++)
            {
                for(int j=ymin[colr];j<=ymax[colr];j++)
                {
                    if(tg[i][j]!=colr)
                    {
                        g[colr].push_back(tg[i][j]);
                        indeg[tg[i][j]]++;// count indegree
                    }

                }
            }
        }
        int visited=0;
        queue<int> q;
        for(int colr=1;colr<=60;colr++)///push whose indegree=0
        {
            if(!indeg[colr])
            {
                q.push(colr);
            }
        }

            while(!q.empty())
            {
                int node=q.front();
                q.pop();
                visited++;
                for(auto &child:g[node])
                {
                    if(!(--indeg[child]))
                        q.push(child);
                }
            }

        return visited==60;
    }
};
