class Solution {
public:
    string reorderSpaces(string str) {

        int n = str.size();

        vector<string> words;

        int total_spaces = 0;

        int i = 0;

        while(i < n)
        {
            // find word

            string word = "";

            while(i < n && isalpha(str[i]))
            {
                word += str[i];

                i++;
            }

            if(word.size())
            {
                words.push_back(word);
            }

            // count spaces

            while(i < n && str[i] == ' ')
            {
                i++;

                total_spaces++;
            }
        }

        // edge case if no. of words = 1

        if(words.size() == 1)
        {
            string res = "";

            res += words[0];

            // push spaces at the end

            if(total_spaces)
            {
                string space(total_spaces, ' ');

                res += space;
            }

            return res;
        }

        // first of all distribute equal no. of spaces between words

        int equal_spaces = total_spaces / (words.size() - 1);

        // find remaining spaces

        int rem_spaces = total_spaces % (words.size() - 1);

        string res = "";

        // iterate over words and create res

        i = 0;

        while(i < words.size())
        {
            res += words[i];

            // do not provide spaces after the last word

            if(i != words.size() - 1)
            {
                string space(equal_spaces, ' ');

                res += space;
            }

            i++;
        }

        // push the remaining spaces at the end

        if(rem_spaces)
        {
            string space(rem_spaces, ' ');

            res += space;
        }

        return res;
    }
};

class Solution {
public:
    int reqSubset(int mask, int r, int n, vector<vector<int>>& requests){
        vector<int> indeg(n ,0), outdeg(n, 0);
        for(int i=0; i<r; i++)
            if(mask& (1<<i)){
                indeg[requests[i][1]]++;
                outdeg[requests[i][0]]++;
            }     
        if (indeg==outdeg)
            return __builtin_popcount(mask);   
        else 
            return 0;
    }

    int maximumRequests(int n, vector<vector<int>>& requests) {
        int r=requests.size();
        int ans=0;

        int reqMask=(1<<r)-1;//all combination bits are set to 1
        //Sort the masks according Hamming weight in descending order
        vector<int> masks(1<<r);
        iota(masks.begin(), masks.end(), 0);
        sort(masks.begin(), masks.end(), [&](auto &a, auto &b) {
            auto aa = __builtin_popcount(a);
            auto bb = __builtin_popcount(b);
            return (aa > bb) || (aa == bb) && (a > b);
        });

        for (int mask: masks){
        //    cout<<mask<<endl;
            ans=max(ans, reqSubset(mask, r, n, requests));
            if (ans>0) break; //It's fine! just O(1) tries
        }   
        return ans;
    }
};

class ParkingSystem {
    int big, medium, small;
    public ParkingSystem(int big, int medium, int small) {
        this.big=big;
        this.medium=medium;
        this.small=small;

    }

    public boolean addCar(int carType) {
        if((carType==1 && big==0) || (carType==2 && medium==0) || (carType==3 && small==0))
            return false;

        if(carType==1) big--;
        if(carType==2) medium--;
        if(carType==3) small--;
        return true;
    }
}

