class Solution {
public:
    int bestTeamScore(vector<int>& scores, vector<int>& ages) {
        vector<tuple<int,int>> items;
        for (int i = 0; i < size(scores); ++i) items.push_back({scores[i], ages[i]});
        sort(begin(items), end(items));

        map<int,int> res; res[0] = 0;
        for(auto [sc, ag] : items) {
            auto it0 = res.upper_bound(ag);
            int sc2 = sc + (--it0)->second;
            auto it = res.insert(it0, {ag, sc2});
            if (it->second < sc2) it->second = sc2;
            ++it;
            while (it != res.end() && it->second <= sc2) {
                auto it2 = it++;
                res.erase(it2);
            }
        }
        return res.rbegin()->second;
    }
};

class Solution {
public:
    // Function to check if the given array forms an arithmetic sequence
    bool check(vector<int>& arr) {
        sort(arr.begin(), arr.end()); // Sort the array
        int diff = arr[1] - arr[0]; // Calculate the difference between the first two elements

        // Check if the difference remains the same for consecutive elements
        for (int i = 2; i < arr.size(); i++) {
            if (arr[i] - arr[i - 1] != diff) {
                return false; // If the difference changes, it's not an arithmetic sequence
            }
        }

        return true; // If all differences are the same, it's an arithmetic sequence
    }

    // Function to check arithmetic subarrays in the given range
    vector<bool> checkArithmeticSubarrays(vector<int>& nums, vector<int>& l, vector<int>& r) {
        vector<bool> ans; // Vector to store results

        // Iterate through the ranges and check each subarray
        for (int i = 0; i < l.size(); i++) {
            // Extract the subarray from nums using the given range [l[i], r[i]]
            vector<int> arr(begin(nums) + l[i], begin(nums) + r[i] + 1);
            ans.push_back(check(arr)); // Check if the subarray forms an arithmetic sequence
        }

        return ans; // Return the results for each subarray
    }
};

class Solution {
public:
    int n, m;
    int dir[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    vector<int> visited; // Change to vector of integers
    int to1D(int i, int j) {
        return i*m +j;
    }

    bool dfs(int idx, int& maxEffort, int maxD, vector<vector<int>>& heights) {
        if (idx == n*m-1) return 1;
        auto [i, j] = div(idx, m);
        // Mark the current cell as visited
        visited[idx] = 1;

        // Store the result of the recursive calls
        bool result=0;

        // Loop through neighboring cells
        for (auto& di : dir) {
            int r = i + di[0], s = j + di[1];
            if (r < 0 || r >= n || s < 0 || s >= m || visited[to1D(r, s)]) continue;

            int w = abs(heights[i][j] - heights[r][s]);
            if (w <= maxD) {
                maxEffort = max(maxEffort, w);
                result = result || dfs(to1D(r, s), maxEffort, maxD, heights);

                // If a path is found, we can break early
                if (result) return 1;
            }
        }
        return result;
    }

    int minimumEffortPath(vector<vector<int>>& heights) {
        n = heights.size(), m = heights[0].size();
        if (n == 1 && m == 1) return 0; // Edge case
        visited.assign(n*m, 0); 
        int maxEffort = 0;
        dfs(0, maxEffort, INT_MAX, heights);
        int l = 0, r=maxEffort; // Searching bounds
        int result=-1;

        while (l <= r) {
            int mid = l + (r - l) / 2;
            visited.assign(n*m, 0); // Reset visited for the next binary search

            if (dfs(0, maxEffort, mid, heights)) {
                result = mid;
                r = mid-1;
            } 
            else 
                l = mid+1;
        }
        return result;
    }
};

