class Solution {
public:
    int minimumJumps(vector<int>& forbidden, int a, int b, int x) {
        vector<vector<int>> dp(6002, vector<int> (2,0));
        if(x == 0) return 0;
        for(int &num : forbidden)
        {
            if(num == x) return -1;
            dp[num][0]++;
            dp[num][1]++;
        }
        dp[0][0] = 1;
        dp[0][1] = 1;
        queue<pair<int, int>> q;
        q.push({0,1});
        if(dp[x][1]) return -1;
        int ans = 0;
        while(!q.empty())
        {
            int s = q.size();
            while(s--)
            {
                pair<int, int> tp = q.front();
                q.pop();
                int val = tp.first;
                int ab = tp.second;
                if(val == x) return ans;
                if(ab)
                {
                    int tmp = val + a;
                    if(tmp <= 6001 && !dp[tmp][1])
                    {
                        q.push({tmp, 1});
                        dp[tmp][1]=1;
                    }
                    tmp = val - b;
                    if(tmp >= 0 && !dp[tmp][0])
                    {
                        q.push({tmp, 0});
                        dp[tmp][0]=1;
                    }
                }
                else
                {
                    int tmp = val + a;
                    if(tmp <= 6001 && !dp[tmp][1])
                    {
                        q.push({tmp, 1});
                        dp[tmp][1]=1;
                    }
                }
            }
            ans++;
        }

        return -1;
    }
};

class Solution(object):
    def minOperations(self, nums, x):

        total_sum = sum(nums)
        max_length = -1
        curr_sum = 0
        count_left = 0

        for right_pointer in range(len(nums)):
            curr_sum += nums[right_pointer]
            while count_left <= right_pointer and curr_sum > total_sum - x:
                curr_sum -= nums[count_left]
                count_left += 1
            if curr_sum == total_sum - x:
                max_length = max(max_length, right_pointer - count_left + 1)

        return -1 if max_length == -1 else len(nums) - max_length

class FrontMiddleBackQueue(object):

    def __init__(self):
        self.A = []

    def pushFront(self, val):
        self.A.insert(0, val)

    def pushMiddle(self, val):
        self.A.insert(len(self.A) / 2, val)

    def pushBack(self, val):
        self.A.append(val)

    def popFront(self):
        return (self.A or [-1]).pop(0)

    def popMiddle(self):
        return (self.A or [-1]).pop((len(self.A) - 1) / 2)

    def popBack(self):
        return (self.A or [-1]).pop()

class Solution {
public:
    int minimumMountainRemovals(vector<int>& nums) {
        int n = nums.size(),i,j;
        vector<int> dp(n);
        for(i = 0; i < n; i++){//find lis from left side
            dp[i] = 1;
            for(j = i-1; j >= 0; j--){
                if(nums[j]<nums[i]&&dp[i]<dp[j]+1){
                    dp[i] = dp[j]+1;
                }
            }
        }
        vector<int> r(n);
        for(i = n-1; i >= 0; i--){//find lis from right side
            r[i] = 1;
            for(j = i+1; j < n; j++){
                if(nums[j]<nums[i]&&r[i]<r[j]+1){
                    r[i] =r[j]+1;
                }
            }
        }
        int ans = 0;
        for(i = 1; i < n-1; i++){
            if(dp[i]>1&&r[i]>1){//if length of lis from left and right > 1 than update ans
                ans = max(ans,dp[i]+r[i]-1);
            }
        }
        return n-ans;
    }
};

class Solution {
public:
    int minimumMountainRemovals(vector<int>& nums) {
        int n = nums.size();
        vector<int> dp1(n,1);
        vector<int> dp2(n,1);

        for(int i=0;i<n;i++){
            for(int j=0;j<i;j++){
                if(nums[i] > nums[j] && 1+dp1[j] > dp1[i])
                    dp1[i] = 1+dp1[j];
            }
        }
        reverse(nums.begin(),nums.end());

        for(int i=0;i<n;i++){
            for(int j=0;j<i;j++){
                if(nums[i] > nums[j] && 1+dp2[j] > dp2[i])
                    dp2[i] = 1+dp2[j];
            }
        }
        reverse(dp2.begin(),dp2.end());
        int maxLen = 1;
        for(int i=0;i<n;i++){
            if(dp1[i]>1 && dp2[i]>1){
                maxLen = max(dp1[i] + dp2[i] - 1, maxLen);
            }
        }

        return n-maxLen;
    }
};

// Time Complexity: O(N)
// Space Complexity: O(1)
class Solution {
public:
    // the idea is to use bit manipulation to set the current number based on the previous number
    // for example, 
    // n = 1, ans = 0b1
    // n = 2 (10), we need to shift 2 bits of the previous ans to the left and add `n`
    // i.e. 1 -> 100 (shift 2 bits to the left) -> 110 (set `10`). ans = 0b110
    // n = 3 (11), we need to shift 2 bits of the previous ans to the left and add `n` 
    // i.e 110 -> 11000 (shift 2 bits to the left) -> 11011 (set `11`). ans = 0b11011
    // n = 4 (100), we need to shift 3 bits of the previous ans to the left and add `n`
    // i.e. 11011 -> 11011000 (shift 3 bits to the left) -> 11011100 (set `100). ans = 0b11011100
    // so now we can see a pattern here
    // we need to shift `l` bits of the previous ans to the left and add the current `i` 
    // how to know `l`? it is not difficult to see `x` only increases when we meet power of 2
    int concatenatedBinary(int n) {
        // `l` is the bit length to be shifted
        int M = 1e9 + 7, l = 0;
        // use long here as it potentially could overflow for int
        long ans = 0;
        for (int i = 1; i <= n; i++) {
            // i & (i - 1) means removing the rightmost set bit
            // e.g. 100100 -> 100000
            //      000001 -> 000000
            //      000000 -> 000000
            // after removal, if it is 0, then it means it is power of 2
            // as all power of 2 only contains 1 set bit
            // if it is power of 2, we increase the bit length `l`
            if ((i & (i - 1)) == 0) l += 1;
            // (ans << l) means shifting the orginal answer `l` bits to th left
            // (x | i) means  using OR operation to set the bit
            // e.g. 0001 << 3 = 0001000
            // e.g. 0001000 | 0001111 = 0001111
            ans = ((ans << l) | i) % M;
        }
        return ans;
    }
};

class Solution(object):
    def getSumAbsoluteDifferences(self, nums):
        total_sum = sum(nums)
        left, right = 0, total_sum
        result = []

        for i, n in enumerate(nums):
            right -= n
            result.append(n * i - left + right - n * (len(nums) - i - 1))
            left += n

        return result

class Solution {
public:
    vector<int> getSumAbsoluteDifferences(vector<int>& nums) {
        int total_sum=0;
        int n=nums.size();
        for(int i=0; i<n; i++)total_sum+=nums[i];
        vector<int> ans;
        int curr_sum=0;
        for(int i=0; i<n; i++){
            curr_sum+=nums[i];
            int Rsum=total_sum-curr_sum;
            int Lsum=curr_sum-nums[i];
            Lsum=(i*nums[i])-Lsum;
            Rsum=Rsum-(n-(i+1))*nums[i];
            ans.push_back(Lsum+Rsum);
        }
        return ans;
    }
};

