class Solution {
    public int maximumUniqueSubarray(int[] nums) {
        Map<Integer, Integer> seen = new HashMap<>();
        int l = 0, sum = 0, ans = 0;
        for (int r = 0; r < nums.length; r++) {
            int x = nums[r];
            if (seen.containsKey(x)) {
                int index = seen.get(x);
                while (l <= index) {  // Move the left side until index + 1
                    seen.remove(nums[l]);
                    sum -= nums[l];
                    l += 1;
                }
            }
            seen.put(x, r);
            sum += x;
            ans = Math.max(ans, sum);
        }
        return ans;
    }
}

class Solution {
public:
    double averageWaitingTime(vector<vector<int>>& c) {
        double ans = 0, totalTime = c[0][0], waitTime = 0; // totalTime is initialised with arrival time of first customer
        for(int i=0; i<c.size(); i++)
        {
            if(c[i][0]<totalTime){  // Case when the chef is busy making other orders
                totalTime += c[i][1];
                waitTime += totalTime - c[i][0];
            }
            else{ // case when chef is already free 
                totalTime = c[i][0] + c[i][1];
                waitTime += c[i][1];
            }
        }
        return waitTime/(c.size());
    }
};

class Solution {
    long long int maxOperations(int k,unordered_map<int,int> &mp) {
        long ans = 0;unordered_map<int,bool> pmp;
        for(auto it : mp){
            int x = it.first;
            int y = k - x;
            if(mp.find(y)!=mp.end()){
                if(!pmp[x] || !pmp[y]){
                    long add = long(mp[x])*long(mp[y]);
                    if(x==y) add = (add-mp[x])/2;
                    ans += add;
                    pmp[x] = true,pmp[y] = true;
                }
            }
        }
        return ans;
    }
public:
    int countPairs(vector<int>& deliciousness) {
        vector<int> v;int x = 1;long ans = 0; 
        for(int i = 0;i<=21;i++) v.push_back(x),x<<=1;
        unordered_map<int,int> mp;
        for(auto it :deliciousness) mp[it]++;
        for(auto it:v) {
            ans = ans + maxOperations(it,mp);
        }

        return int(ans% 1000000007);
    }
};

const int mod = 1e9 + 7;

int count_bet(vector<int> &a, int ind, int low, int high) {
    if(low > high) return 0;

    auto l_itr = lower_bound(a.begin(), a.begin() + ind, low);
    auto r_itr = upper_bound(a.begin(), a.begin() + ind, high);
    return (r_itr - l_itr);
}

class Solution {
public:
    int waysToSplit(vector<int>& a) {
        int n = a.size();

        auto pref = a;
        for(int i = 1; i < n; i++) {
            pref[i] += pref[i - 1];
        }

        int sum = pref.back();
        long long cnt = 0;

        int suf = 0;
        for(int i = n - 1; i >= 2; i--) {
            suf += a[i];
            auto in_bet = count_bet(pref, i - 1, sum - 2*suf, (sum - suf)/2);
            cnt = (cnt + in_bet) % mod;
        }

        return cnt;
    }
};

class Solution {
public:
    int totalMoney(int n) {
        int ans = 0;        // Variable to store the total money earned
        int monday = 1;     // Represents the amount earned on Monday

        while (n > 0) {     // Continue the loop until 'n' days are exhausted
            for (int day = 0; day < min(n, 7); day++) {  // Iterate for each day of the week or until 'n' days are left
                ans += monday + day;  // Increment 'ans' by the amount earned on the current day (monday + day)
            }

            n -= 7;         // Deduct 7 days (a week) from the total number of days left
            monday++;       // Increment the amount earned on Monday for the next week
        }

        return ans;        // Return the total amount earned over 'n' days
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* swapNodes(ListNode* head, int k) {
    ListNode *itr = head, *ptr1 = NULL, *ptr2 = NULL;
    uint n = 0, count = 0;

    while(itr != NULL) {
        n++;
        itr = itr->next;
    }

    itr = head;
    while(itr != NULL) {
        count++;
        if(count == k) {
            ptr1 = itr;
        } else if(count == n - k + 1) {
            ptr2 = itr;
        }
        itr = itr->next;
    }

    if(ptr1 != NULL && ptr2 != NULL)
        swap(ptr1->val, ptr2->val);

    return head;
}

    void swap(int &a, int &b) {
        int temp;
        temp = a;
        a = b;
        b = temp;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    int length(ListNode* head){
        int cnt = 0 ;
        while(head!=NULL){
            cnt++;
            head = head->next;
        }
        return cnt;
    }
    ListNode* swapNodes(ListNode* head, int k) {
        // kth node from start = n - k + 1  th node from end
        int n = length(head);

        int end = n-k+1, i = 1;
        ListNode* t1 = head, *t2 = head;

        while(i < k){
            t1 = t1->next;
            i++;
        }

        i = 1;

        while(i<end){
            t2 = t2->next;
            i++;
        }

        int data = t1->val;
        t1->val = t2->val;
        t2->val = data;

        return head;
    }
};

