class Solution {
public:

	vector<vector<int>> mem;  
    bool check(vector<vector<int>>& a, int u, int v) {
        if(mem[u][v] != 0) return mem[u][v] == 1;
        for(int i=0; i<a[v].size(); i++) {
            if(find(a[u].begin(), a[u].end(), a[v][i]) != a[u].end()) {
                mem[v][u] = mem[u][v] = 1;
                return true;
            }
        }
        mem[u][v] = mem[v][u] = -1;
        return false;
    }

    int minimumTeachings(int n, vector<vector<int>>& languages, vector<vector<int>>& friendships) {
        int m = languages.size(), ret = m, i;
        mem.assign(m + 1, vector<int>(m + 1, 0));

        for(i=0; i<m; i++)
            sort(languages[i].begin(), languages[i].end()); 

        for(int lang=1; lang<=n; lang++) {
            int count = 0;
            vector<bool> teach(m, false);
            for(i=0; i<friendships.size(); i++) {
                int u = friendships[i][0] - 1;
                int v = friendships[i][1] - 1;
                if(check(languages, u, v)) 
                    continue;
                if(find(languages[u].begin(), languages[u].end(), lang) == languages[u].end()) {
                    if(!teach[u])
                        count++;
                    teach[u] = true;
                }
                if(find(languages[v].begin(), languages[v].end(), lang) == languages[v].end()) {
                    if(!teach[v])
                        count++;
                    teach[v] = true;
                }
            }
            ret = min(ret, count);
        }
        return ret;
    }
};

// OJ: https://leetcode.com/problems/change-minimum-characters-to-satisfy-one-of-three-conditions/
// Author: github.com/lzl124631x
// Time: O(A + B)
// Space: O(1)
class Solution {
public:
    int minCharacters(string a, string b) {
        array<int, 26> ca = {}, cb = {};
        for (char c : a) ca[c - 'a']++;
        for (char c : b) cb[c - 'a']++;
        int M = a.size(), N = b.size(), op1 = M, op2 = N, ans = INT_MAX;
        for (int i = 0; i < 26; ++i) {
            op1 += cb[i] - ca[i];
            op2 += ca[i] - cb[i];
            if (i < 25) ans = min({ ans, op1, op2 });
            ans = min(ans, M + N - ca[i] - cb[i]);
        }
        return ans;
    }
};

var minCharacters = function(A, B) {
    let lenA = A.length, fmA = new Uint32Array(26),
        lenB = B.length, fmB = new Uint32Array(26),
        best = sumA = sumB = 0
    for (let i = 0; i < lenA; i++) fmA[A.charCodeAt(i)-97]++
    for (let i = 0; i < lenB; i++) fmB[B.charCodeAt(i)-97]++
    for (let i = 0; i < 26; i++) best = Math.max(best, fmA[i]+fmB[i])
    for (let i = 0; i < 25; i++) {
        sumA += fmA[i], sumB += fmB[i]
        best = Math.max(best, sumA-sumB+lenB, sumB-sumA+lenA)
    }
    return lenA + lenB - best
};

class Solution {
public:
    int kthLargestValue(vector<vector<int>>& matrix, int k) {
        int m = matrix.size();
        int n = matrix[0].size();

        vector<int> ans;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i) matrix[i][j] ^= matrix[i-1][j];
                if (j) matrix[i][j] ^= matrix[i][j-1];
                if (i && j) matrix[i][j] ^= matrix[i-1][j-1];
                ans.push_back(matrix[i][j]);
            }
        }

        sort(ans.begin(), ans.end());
        return ans[ans.size()-k];
    }
};

class Solution {
public:
    int findSum(int n){
        int sum=0;
        while(n>0){
            sum+=(n%10);
            n/=10;
        }
        return sum;
    }
    int countBalls(int lowLimit, int highLimit) {
        int maxi=1;
        unordered_map<int,int>m;
        for(int i=lowLimit;i<=highLimit;i++){
            int x=findSum(i);
            if(m.find(x)!=m.end()){
                maxi=max(maxi,m[x]+1);
            }
            m[x]++;
        }
        return maxi;

    }
};

class Solution {
public:
    int maxAbsoluteSum(vector<int>& nums) {
        int ans = 0,cs1=0,cs2=0;
        for(auto &i: nums){
            cs1 += i;
            if(cs1<0){
                cs1 = 0;
            }
            cs2 += i;
            if(cs2>0){
                cs2 = 0;
            }
            ans = max({ans,cs1,-cs2});
        }
        return ans;
    }
};

class Solution {
public:

    vector<vector<int>> memo;

    // searching for 1st next non-conflicting event 
    int search(vector<vector<int>>& events, int end, int idx){
        int n=events.size();
        int l=idx, r=n-1;
        while(l<r){
            int m=l+(r-l)/2;
            int start=events[m][0];
            if(start>end){
                r=m;
            }else{
                l=m+1;
            }
        }

        return ((l<n && events[l][0]>end) ? l:-1);
    }

    int profit(vector<vector<int>>& events, int n, int k, int idx){
        if(idx==n || k==0) return 0;

        if(memo[idx][k]!=-1) return memo[idx][k];

        int maxval=0;

        // not attend
        maxval = profit(events, n, k, idx+1);

        // attend event
        int next_possible_idx = search(events, events[idx][1], idx+1);
        maxval = max(maxval, events[idx][2] + (next_possible_idx==-1 ? 0:profit(events,n,k-1,next_possible_idx)));

        return memo[idx][k]=maxval;
    }

    int maxValue(vector<vector<int>>& events, int k) {
        int n=events.size();
        sort(events.begin(),events.end());

        memo.resize(n,vector<int>(k+1,-1));

        return profit(events,n,k,0);
    }
};

/**
 * @param {string} s
 * @return {number}
 */
var minOperations = function(s) {
    const length = s.length;
    let dif1 = 0;
    let dif2 = 0;

    for (let i = 0; i < length; i++) {
        if (i%2) {
            if (s[i] !== '0') dif1++;
            if (s[i] !== '1') dif2++;
        } else {
            if (s[i] !== '1') dif1++;
            if (s[i] !== '0') dif2++;
        }
    }

    return Math.min(dif1, dif2);
};

class Solution {
    public int minimumSize(int[] nums, int maxOperations) {
        int min = 0;
        int max = 1000000000;

        while (min +1< max) {
            int mid = (max - min)/2 + min;
            int count = 0;

            for (int a: nums) {
                count+=(a-1)/mid;
            }

            if (count <= maxOperations) {
                max = mid;
            } else {
                min = mid;
            }
        }
        return max;
    }
}

class Solution {
public:
   unordered_map<int, vector<int>> cops;
unordered_map<int, vector<pair<int, int>>> ancestors;
void traverse(vector<int>& n, vector<vector<int>> &al, int i, int parent, int level, vector<int> &res) {
    int max_level = -1;
    for (auto cop : cops[n[i]]) {
        auto &v = ancestors[cop];
        if (!v.empty() && v.back().first > max_level) {
            max_level = v.back().first;
            res[i] = v.back().second;
        }
    }
    ancestors[n[i]].push_back({level, i});
    for (auto child : al[i])
        if (child != parent)
            traverse(n, al, child, i, level + 1, res);
    ancestors[n[i]].pop_back();
}
vector<int> getCoprimes(vector<int>& n, vector<vector<int>>& edges) {
    unordered_set<int> s(begin(n), end(n));
    for (auto n1 : s) {
        for (auto n2 : s)
            if (__gcd(n1, n2) == 1)
                cops[n1].push_back(n2);
    }
    vector<vector<int>> al(n.size());
    vector<int> res(n.size(), -1);
    for (auto &e : edges) {
        al[e[0]].push_back(e[1]);
        al[e[1]].push_back(e[0]);
    }
    traverse(n, al, 0, 0, 0, res);
    return res;
}
};

class Solution {
public:

    int minOperations(vector<int>& nums1, vector<int>& nums2) {

        int n1 = nums1.size();
        int n2 = nums2.size(); 

        int sum1 = accumulate(nums1.begin(),nums1.end(),0);
        int sum2 = accumulate(nums2.begin(),nums2.end(),0); 

        priority_queue<int>pq;

        int req = abs(sum1-sum2);
        int cnt = 0;

        if(sum1>sum2)
        {
           for(int i = 0;i<n1;++i) pq.push(nums1[i]-1);

           for(int i = 0;i<n2;++i) pq.push(6-nums2[i]);

        }

        else
        {
           for(int i = 0;i<n2;++i) pq.push(nums2[i]-1);

           for(int i = 0;i<n1;++i) pq.push(6-nums1[i]);

        }

        while(pq.top() > 0)
        {
            if(req <= 0) break;

            int top = pq.top();
            pq.pop();
            req -= top;
            cnt++;  
        }

        if(req > 0) return -1;

        return cnt;
    }
};

class Solution {
public:
    int nearestValidPoint(int x, int y, vector<vector<int>>& points) {
        int val= -1; int v= INT_MAX;
        for (int i=0; i<points.size(); i++){
            if (x!=points[i][0] && y!= points[i][1])continue;
            if (v > (abs(points[i][0]-x)+abs(points[i][1]-y))){
                val= i; 
                v=(abs(points[i][0]-x)+abs(points[i][1]-y));}
        }
        return val;
    }
};

class Numeric
    def max(v)
        self < v ? v : self
    end
end

class Solver
    attr_reader :nums, :ns2, :gcd

    def initialize(nums)
        @nums, @ns2, @gcd = nums, nums.size / 2, Array.new(nums.size) {|_| Array.new(nums.size) }
        nums.each_with_index {|v, idx|
            (idx+1...nums.size).each {|j| @gcd[idx][j] = v.gcd(nums[j]) }
        }
    end

    def rec(op = 1, mask = 0)
        return 0 if op > ns2
        @dp[mask] ||= nums.size.times.inject(-1) {|res, i|
            next res unless mask[i].zero?
            (i+1...nums.size).inject(res) {|res1, j|
                next res1 unless mask[j].zero?
                res1.max(op * gcd[i][j] + rec(op + 1, mask | (1 << i) | (1 << j)))
            }
        }
    end

    def solve
        @dp = Array.new(1 << nums.size)
        rec
    end
end

def max_score(nums)
    Solver.new(nums).solve
end

class Solution {
public:
   long modpow(long base, int exp, int modulus) {
  long result = 1;
  for (; exp > 0; exp >>= 1) {
    result = result * (exp & 1 ? base : 1) % modulus;
    base = base * base % modulus;
  }
  return result;
}    
int maxNiceDivisors(int n) {
    int st[6] = {0, 1, 2, 3, 4, 6}, mod = 1000000007;
    return n < 6 ? st[n] : st[3 + n % 3] * modpow(3, n / 3 - 1, mod) % mod;
}
};

class Solution {
  private int rev(int n) {
    var rev = 0;

    while (n > 0) {
      rev = (rev * 10) + (n % 10);
      n /= 10;
    }
    return rev;
  }

  public int countNicePairs(int[] nums) {
    var map = new HashMap<Integer, Integer>();
    var ans = 0;

    for (var n : nums) {
      var rev = rev(n);
      var a = map.getOrDefault(n - rev, 0);
      ans = (ans + a) % 1000000007;
      map.put(n - rev, a + 1);
    }
    return ans;
  }
}

class Solution {
    public String truncateSentence(String s, int k) {
        int count = 0;
        int index = 0;
        for(index = 0; index < s.length(); index++){
            if(s.charAt(index) == ' ')
                count++;   
            if(count==k)
                break;   
        }
        return s.substring(0,index);
    }
}

class Solution {
    public String truncateSentence(String s, int k) {
        String arr[] = s.split(" ");
        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < k; i++) {
            if(i < arr.length) {
                sb.append(arr[i]).append(" ");
            }
        }
        return sb.toString().trim();
    }
}

// OJ: https://leetcode.com/contest/weekly-contest-236/problems/finding-mk-average/
// Author: github.com/lzl124631x
// Time: 
//     MKAverage: O(1)
//     addElement: O(logM)
//     calculateMKAverage: O(1)
// Space: O(M)
class MKAverage {
    multiset<int> top, bot, mid;
    queue<int> q;
    long sum = 0, m, k;
public:
    MKAverage(int m, int k) : m(m), k(k) {}

    void addElement(int n) {
        if (q.size() < m) mid.insert(n); // when there are less than `m` numbers, always insert into `mid`.
        q.push(n);
        if (q.size() == m) {
            // when we reached exactly `m` numbers, we nudge numbers from `mid` to `top` and `bot`, and calculate `sum`.
            for (int i = 0; i < k; ++i) {
                bot.insert(*mid.begin());
                mid.erase(mid.begin());
            }
            for (int i = 0; i < k; ++i) {
                top.insert(*mid.rbegin());
                mid.erase(prev(mid.end()));
            }
            for (int x : mid) sum += x;
        } else if (q.size() > m) {
            // when we've seen more than `m` numbers. We first add the new number `n` to where it should belong.
            // If we add `n` to `top` or `bot`, we balance them with `mid` to make sure `top` and `bot` have exactly `k` numbers
            if (n < *bot.rbegin()) {
                bot.insert(n);
                int x = *bot.rbegin();
                bot.erase(prev(bot.end()));
                mid.insert(x);
                sum += x; 
            } else if (n > *top.begin()) {
                top.insert(n);
                int x = *top.begin();
                top.erase(top.begin());
                mid.insert(x);
                sum += x;
            } else {
                mid.insert(n);
                sum += n;
            }
            // Then we remove the number `rm` that is no longer one of the latest `m` numbers.
            int rm = q.front();
            q.pop();
            auto it = mid.find(rm);
            if (it != mid.end()) { // first try removing from `mid`, then `top` or `bot`.
                mid.erase(it);
                sum -= rm;
            } else {
                it = top.find(rm);
                if (it != top.end()) {
                    top.erase(it);
                } else {
                    bot.erase(bot.find(rm));
                }
            }
            // Lastly, balance `top` and `bot` if needed
            if (bot.size() < k) {
                int x = *mid.begin();
                bot.insert(x);
                mid.erase(mid.begin());
                sum -= x;
            } else if (top.size() < k) {
                int x = *mid.rbegin();
                top.insert(x);
                mid.erase(prev(mid.end()));
                sum -= x;
            }
        }
    }

    int calculateMKAverage() {
        return q.size() == m ? (sum / (m - 2 * k)) : -1;
    }
};
